import { STUDY_API, type Plot, type StudyDef, type StudyOutput } from '../engine/studies/contract.ts';
import { readInputs, type InputSpec, type InputValues } from '../engine/inputs/schema.ts';
import { timeframeMs, type Timeframe } from '../engine/time/timeframe.ts';
import type { Bar } from '../engine/series/source.ts';
import { periodStart } from './htf-candles.ts';

/**
 * `previous-ohlc`: the OEC PREVIOUS OHLC piece — the previous period's open, high, low and close (and the midpoint of its range) for the
 * chart's reference timeframes, which is where the Trade Plan takes its levels from (D-10).
 *
 * The Pine (`OECLiquidityindicators/OddEyeCircle`): `OHLC_DATA_PREV(tf)` (line 99) reads one series per timeframe with `lookahead_on` and
 * takes `[1]` — the previous *completed* period's open/high/low/close plus `(high[1] + low[1]) / 2` as the midpoint; `Previous_OHLC`
 * (2023) draws one line and one label a level, and the calls (2051-2144) do it for 1m, 5m, 15m, 1h, 4h, 1d, 1w and 1M.
 *
 * What the Pine actually draws, and this piece with it: close, high and low of each period (open and the midpoint are commented out in the
 * calls, 2085-2144). They are computed here as values as well and can be switched on (`open`, `mid`), off by default: parity is the three
 * the Pine draws.
 *
 * Two traps from the map (`docs/platform/pieces.md`), both respected: `lookahead_on` means the previous period is the last *completed* one
 * (a forming bar is never used), and the Pine's "1m" series is `Intra_1m_tf = '5'` (line 151) — there is no real 1m series; both P1m and
 * P5m read the 5-minute one.
 *
 * A period whose series the host has not resolved, or whose previous period is not the one right before (a gap), is not drawn: the piece
 * never invents a level. `compute` is pure and imports no hub, store or fetch; the engine's painter draws the plots.
 */
interface Period { readonly id: string; readonly code: string; readonly label: string; readonly series: Timeframe; readonly color: string }

/** The Pine's calls in their order; 1m and 5m share the 5-minute series (`Intra_1m_tf`, 151). */
const PERIODS: readonly Period[] = [
  { id: 'p1m', code: 'P1m', label: 'Prev. 1m (5m series)', series: '5', color: '#11ff40' },
  { id: 'p5m', code: 'P5m', label: 'Prev. 5m', series: '5', color: '#11ff40' },
  { id: 'p15m', code: 'P15m', label: 'Prev. 15m', series: '15', color: '#11ff40' },
  { id: 'p1h', code: 'P1H', label: 'Prev. 1H', series: '60', color: '#11ff40' },
  { id: 'p4h', code: 'P4H', label: 'Prev. 4H', series: '240', color: '#ff9800' },
  { id: 'pd', code: 'PD', label: 'Prev. Day', series: 'D', color: '#08bcd4' },
  { id: 'pw', code: 'PW', label: 'Prev. Week', series: 'W', color: '#fffcbc' },
  { id: 'pm', code: 'PM', label: 'Prev. Month', series: 'M', color: '#08d48c' },
];

const SERIES: readonly Timeframe[] = ['5', '15', '60', '240', 'D', 'W', 'M'];

/** The bar size of each series, in ms. */
const SERIES_MS: Readonly<Record<string, number>> = {
  '5': 5 * 60_000, '15': 15 * 60_000, '60': 3_600_000, '240': 14_400_000, D: 86_400_000, W: 604_800_000, M: 2_592_000_000,
};

/**
 * The Pine's own gate, copied as it is (`GlobalFunctions library:192-197`). A chart belongs to one **family** and only that family's
 * previous periods are drawn: `show_W()` is a 1m, 15m or 4H intraday chart or a weekly one; `show_M()` is a seconds chart, a 5m or 1H
 * intraday one, a daily or a monthly one. The monthly level is the exception: its call asks `show_below_equal_M()` (`:235`), true on
 * everything but a seconds chart. A 30-minute chart belongs to neither family and draws only the monthly level, as the Pine does.
 * A chart with no bars yet (`chartMs` 0) filters nothing.
 */
export function showsPeriod(chartMs: number, period: string): boolean {
  if (!(chartMs > 0)) return true;
  const minutes = chartMs / 60_000;
  const seconds = chartMs < 60_000;
  const daily = chartMs >= 86_400_000 && chartMs < 604_800_000;
  const weekly = chartMs >= 604_800_000 && chartMs < 2_592_000_000;
  const monthly = chartMs >= 2_592_000_000;
  const intraday = !seconds && !daily && !weekly && !monthly;
  const showW = (intraday && (minutes === 1 || minutes === 15 || minutes === 240)) || weekly;
  const showM = seconds || (intraday && (minutes === 5 || minutes === 60)) || daily || monthly;
  const belowEqualM = !seconds;
  switch (period) {
    case 'p1m': case 'p15m': case 'p4h': case 'pw': return showW;
    case 'p5m': case 'p1h': case 'pd': return showM;
    case 'pm': return belowEqualM;
    default: return true;
  }
}

/** The chart's own bar size: the piece is told bars, not the chart's timeframe name. */
function chartBarMs(bars: readonly Bar[]): number {
  for (let index = 1; index < bars.length; index += 1) {
    const step = bars[index]![0] - bars[index - 1]![0];
    if (step > 0) return step;
  }
  return 0;
}

/** The inputs that change the result: each period and level on/off with its colour, plus the three the Pine keeps commented out. */
const INPUTS: readonly InputSpec[] = [
  ...PERIODS.flatMap((period): InputSpec[] => [
    { id: `${period.id}.on`, kind: 'bool', name: period.label, default: true, group: 'Periods' },
    { id: `${period.id}.high`, kind: 'bool', name: `${period.code} high`, default: true, group: 'Levels' },
    { id: `${period.id}.low`, kind: 'bool', name: `${period.code} low`, default: true, group: 'Levels' },
    { id: `${period.id}.close`, kind: 'bool', name: `${period.code} close`, default: true, group: 'Levels' },
    { id: `${period.id}.color`, kind: 'color', name: `${period.code} colour`, default: period.color, group: 'Style' },
  ]),
  { id: 'open', kind: 'bool', name: 'Open (not drawn by the Pine)', default: false, group: 'Levels' },
  { id: 'mid', kind: 'bool', name: '50% (not drawn by the Pine)', default: false, group: 'Levels' },
  { id: 'width', kind: 'int', name: 'Width', default: 1, min: 1, max: 5, group: 'Style' },
  { id: 'style', kind: 'string', name: 'Style', default: 'dotted', options: ['solid', 'dashed', 'dotted'], group: 'Style' },
  { id: 'hierarchy', kind: 'bool', name: 'Follow the chart timeframe', default: true, group: 'Periods' },
  { id: 'labels', kind: 'bool', name: 'Labels', default: true, group: 'Style' },
  { id: 'prices', kind: 'bool', name: 'Price in the label', default: true, group: 'Style' },
];

/**
 * The start of the period right before the one `start` begins: the previous day, week (`start - 7 days`, Monday to Monday) or month, or
 * the previous bar for the fixed sizes. Used to refuse a series whose gap leaves an older period as "the previous one".
 */
export function previousStart(start: number, tf: Timeframe): number {
  if (tf === 'D') return start - timeframeMs('D');
  if (tf === 'W') return start - timeframeMs('W');
  if (tf === 'M') { const date = new Date(start); return Date.UTC(date.getUTCFullYear(), date.getUTCMonth() - 1, 1); }
  return start - timeframeMs(tf);
}

/** The previous completed bar of `tf` at `now`, or null when the series does not hold the period right before the current one. */
export function previousBar(bars: readonly Bar[], now: number, tf: Timeframe): Bar | null {
  const start = periodStart(now, tf), wanted = previousStart(start, tf);
  for (const bar of bars) if (bar[0] === wanted) return bar;
  return null;
}

const dashOf = (style: string): readonly number[] => style === 'solid' ? [] : style === 'dashed' ? [6, 4] : [2, 3];
const flag = (params: InputValues, id: string): boolean => params[id] === true;
const text = (params: InputValues, id: string, fallback: string): string => typeof params[id] === 'string' ? params[id] : fallback;
const number = (params: InputValues, id: string, fallback: number): number => typeof params[id] === 'number' && Number.isFinite(params[id]) ? params[id] : fallback;
const priceText = (value: number): string => Number(value.toFixed(2)).toString();

export const PREVIOUS_OHLC: StudyDef = {
  api: STUDY_API,
  id: 'previous-ohlc',
  name: 'Previous OHLC',
  inputs: INPUTS,
  data: [
    // The chart's own candles, for the hierarchy rule only: nothing of them is drawn.
    { key: 'chart', kind: 'candles' as const, label: 'Chart candles' },
    ...SERIES.map(tf => ({ key: `series:${tf}`, kind: 'candles' as const, label: `${tf} candles` })),
  ],
  compute(ctx): StudyOutput | null {
    const params = readInputs(INPUTS, ctx.params);
    const open = flag(params, 'open'), mid = flag(params, 'mid'), labels = flag(params, 'labels'), prices = flag(params, 'prices');
    const width = Math.max(1, Math.min(5, Math.round(number(params, 'width', 1)))), dash = dashOf(text(params, 'style', 'dotted'));
    const hierarchy = flag(params, 'hierarchy');
    const chart = ctx.data.candles('chart');
    const chartMs = chart ? chartBarMs(chart.bars) : 0;
    const plots: Plot[] = [];
    for (const period of PERIODS) {
      if (!flag(params, `${period.id}.on`)) continue;
      // The chart's family decides which previous periods are its key levels (D-26, `GlobalFunctions library:192-197`).
      if (hierarchy && !showsPeriod(chartMs, period.id)) continue;
      const series = ctx.data.candles(`series:${period.series}`);
      if (!series) continue; // the host has not resolved this series: nothing is drawn
      const bar = previousBar(series.bars, ctx.now, period.series);
      if (!bar) continue; // no complete previous period to read: never a level from another period
      const start = periodStart(ctx.now, period.series), from = previousStart(start, period.series), color = text(params, `${period.id}.color`, period.color);
      const levels: { suffix: string; value: number; on: boolean }[] = [
        { suffix: 'C', value: bar[4], on: flag(params, `${period.id}.close`) },
        { suffix: 'H', value: bar[2], on: flag(params, `${period.id}.high`) },
        { suffix: 'L', value: bar[3], on: flag(params, `${period.id}.low`) },
      ];
      if (open) levels.push({ suffix: 'O', value: bar[1], on: true });
      if (mid) levels.push({ suffix: '50%', value: (bar[2] + bar[3]) / 2, on: true });
      for (const level of levels) {
        if (!level.on) continue;
        const code = `${period.code}-${level.suffix}`;
        plots.push({ kind: 'line', points: [{ t: from, p: level.value }, { t: start, p: level.value }], style: { width, color, dash } });
        if (labels) plots.push({ kind: 'label', t: start, p: level.value, text: prices ? `${code} ${priceText(level.value)}` : code, color });
      }
    }
    return plots.length ? { plots } : null;
  },
};
