/**
 * The candles as a layer of their own: canvas 0 of the map, under the heatmap, with the bars folded to the room they are given.
 *
 * The layer owns nothing: it reads the state's candles, the map's view and the plot's size, and draws. What it draws comes from
 * `candle/lod.ts` (pure): under a pixel a bar a line of closes, between one and two a column a bar, from two the bar's own body and wick.
 *
 * The paths are built once for a key (the candles, the timeframe, the view, the plot, the theme) and only drawn again when that key changes,
 * so a frame that only moves the pointer over the map, or redraws anything above it, costs this layer nothing: it keeps what it drew.
 * Off until validated (T-1005): `main.ts` creates it only with the flag or `?candleslayer`.
 */
import { PALETTES, type Palette } from '../theme.ts';
import type { AppState, CandleRow } from '../store.ts';
import type { View } from '../view.ts';
import { TIMEFRAMES } from '../hub.ts';
import { columns, lodMode, pxPerBar, type LodMode } from '../candle/lod.ts';
import { paintCandles } from '../candle/paint-candles.ts';

/** What the canvas holds: the key it was drawn for, and the regime it was drawn in. */
interface Drawn { key: string; mode: LodMode }

export class CandlesLayer {
  /** The layer's canvas, the map pane's first: the heatmap and everything above it paint over it. */
  readonly root = document.createElement('canvas');
  #ctx: CanvasRenderingContext2D;
  /** The candles array the version counts: a new array is new data, and the last bar may also change inside the same one. */
  #bars: readonly CandleRow[] | null = null;
  #version = 0;
  #drawn: Drawn | null = null;
  #w = 0; #h = 0; #dpr = 0;

  constructor(host: HTMLElement) {
    this.root.className = 'candles';
    this.root.setAttribute('aria-hidden', 'true');
    this.#ctx = this.root.getContext('2d')!;
    host.prepend(this.root);
  }

  /**
   * Draw the candles for this state, view and plot; nothing at all when what was drawn is what this asks for. `left` is where the plot
   * starts in the pane (the columns left of the map), `dpr` the device pixel ratio.
   */
  draw(state: AppState, view: View, plotW: number, plotH: number, left: number, dpr: number, extras: { hollow: boolean; hot?: (index: number) => boolean }): void {
    const span = view.t1 - view.t0;
    if (!state.show.candles || !(span > 0) || plotW <= 1 || plotH <= 1) { this.#clear(); return; }
    const barMs = TIMEFRAMES[state.timeframe] ?? 3_600_000;
    const px = pxPerBar(plotW, span, barMs), mode = lodMode(px);
    if (state.candles !== this.#bars) { this.#bars = state.candles; this.#version += 1; }
    const last = state.candles[state.candles.length - 1];
    const key = [this.#version, state.candles.length, last ? `${last[0]}:${last[4]}` : '', state.timeframe, Math.round(view.t0), Math.round(view.t1),
      view.p0, view.p1, Math.round(plotW), Math.round(plotH), Math.round(left), dpr, mode, state.theme, extras.hollow ? 'hollow' : 'solid',
      state.highlight.on ? 'hot' : 'plain'].join('|');
    if (this.#drawn?.key === key) return;
    this.#size(plotW, plotH, left, dpr);
    const ctx = this.#ctx, palette = PALETTES[state.theme] ?? PALETTES.light!;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, plotW, plotH);
    this.root.hidden = false;
    this.#paint(state, view, plotW, plotH, barMs, mode, px, palette, extras);
    this.#drawn = { key, mode };
  }

  /** The canvas's own pixels, its box and where the plot starts in the pane. Only what changed is written. */
  #size(plotW: number, plotH: number, left: number, dpr: number): void {
    const w = Math.round(plotW), h = Math.round(plotH);
    if (w !== this.#w) { this.root.width = Math.round(plotW * dpr); this.root.style.width = `${plotW}px`; this.#w = w; }
    if (h !== this.#h) { this.root.height = Math.round(plotH * dpr); this.root.style.height = `${plotH}px`; this.#h = h; }
    if (dpr !== this.#dpr) { this.root.width = Math.round(plotW * dpr); this.root.height = Math.round(plotH * dpr); this.#dpr = dpr; }
    this.root.style.left = `${left}px`;
  }

  /** Turn the numbers into paths and draw them: one path a regime, so a still chart paints twice and a moving one loops once. */
  #paint(state: AppState, view: View, plotW: number, plotH: number, barMs: number, mode: LodMode, px: number, p: Palette, extras: { hollow: boolean; hot?: (index: number) => boolean }): void {
    const ctx = this.#ctx, edge = p.dark ? 'rgba(255,255,255,0.92)' : 'rgba(18,20,24,0.92)';
    const y = (price: number): number => view.yOf(price, plotH);
    if (mode === 'line') {
      // More bars than pixels: the closes, joined, a pixel a column.
      const path = new Path2D();
      columns(state.candles, view.t0, view.t1, plotW, barMs).forEach((c, i) => {
        const x = c.x + 0.5, cy = y(c.close);
        if (i === 0) path.moveTo(x, cy); else path.lineTo(x, cy);
      });
      ctx.strokeStyle = p.candleUp; ctx.lineWidth = 1; ctx.stroke(path);
      return;
    }
    const up = new Path2D(), down = new Path2D(), wicks = new Path2D();
    const body = (path: Path2D, x: number, open: number, close: number, width: number): void => {
      const top = Math.min(y(open), y(close)), height = Math.max(1, Math.abs(y(close) - y(open)));
      path.rect(x - width / 2, top, width, height);
    };
    if (mode === 'column') {
      // One pixel a column, several bars in it: the column's extremes and its open and close.
      for (const c of columns(state.candles, view.t0, view.t1, plotW, barMs)) {
        wicks.moveTo(c.x + 0.5, y(c.high)); wicks.lineTo(c.x + 0.5, y(c.low));
        body(c.close >= c.open ? up : down, c.x + 0.5, c.open, c.close, 1);
      }
    } else {
      // A body a bar: the heat's own painter, moved here with T-1034 (halo, hollow while the dust shows, the unusual ones' ring).
      paintCandles(ctx, { state, view, plotW, plotH, palette: p, hollow: extras.hollow, ...(extras.hot ? { hot: extras.hot } : {}) });
      return;
    }
    ctx.globalAlpha = 0.9; ctx.strokeStyle = edge; ctx.lineWidth = 1; ctx.stroke(wicks);
    ctx.globalAlpha = 1; ctx.fillStyle = p.candleUp; ctx.fill(up);
    ctx.fillStyle = p.candleDown; ctx.fill(down);
  }

  /** Nothing to draw: the canvas is cleared once and hidden until a draw asks for it again. */
  #clear(): void {
    if (!this.#drawn && this.root.hidden) return;
    this.#ctx.setTransform(1, 0, 0, 1, 0, 0);
    this.#ctx.clearRect(0, 0, this.root.width, this.root.height);
    this.root.hidden = true;
    this.#drawn = null;
  }
}
