import { STUDY_API, type Plot, type StudyDef } from '../../engine/studies/contract.ts';
import { readInputs, type InputSpec } from '../../engine/inputs/schema.ts';

/**
 * The first study written against the contract: a simple moving average of the chart's closes. It is the proof that a study is one file
 * plus one line in `registry.ts` — it declares an input, asks for the chart's candles and returns one line.
 */
const INPUTS: readonly InputSpec[] = [
  { id: 'length', kind: 'int', name: 'Length', default: 20, min: 1, max: 500, group: 'Inputs' },
];

export const SMA: StudyDef = {
  api: STUDY_API,
  id: 'sma',
  name: 'Simple moving average',
  inputs: INPUTS,
  data: [{ key: 'chart', kind: 'candles', label: 'Chart candles' }],
  compute(ctx): { plots: readonly Plot[] } | null {
    const series = ctx.data.candles('chart');
    if (!series || !series.bars.length) return null;
    const params = readInputs(INPUTS, ctx.params);
    const raw = params['length'];
    const length = typeof raw === 'number' && Number.isFinite(raw) ? Math.max(1, Math.min(500, Math.round(raw))) : 20;
    const points: { t: number; p: number }[] = [];
    let sum = 0;
    series.bars.forEach((bar, index) => {
      sum += bar[4];
      if (index >= length) sum -= series.bars[index - length]![4];
      if (index >= length - 1) points.push({ t: bar[0], p: sum / length });
    });
    if (!points.length) return null;
    return { plots: [{ kind: 'line', points, style: { width: 1.5 } }] };
  },
};
