/**
 * Level of detail for the candles: what to draw when there are more bars than pixels, and how several bars share one pixel column.
 *
 * Three regimes, by the pixels one bar is given (`pxPerBar`):
 *   under 1     more bars than pixels: one column of pixels, joined at the close (no body, no wick);
 *   1 to 2      a column a bar, widened: one pixel of body and the column's extremes;
 *   2 and up    the bar's own body and wick.
 *
 * Pure: no DOM, no canvas, no store. `panes/candles-layer.ts` only turns these numbers into paths; a test checks it with node.
 */
import type { CandleRow } from '../store.ts';

/** From this many pixels a bar, the candle has its own body and wick. Below it, bars share columns. */
export const LOD_BODY_PX = 2;
/** From this many pixels a bar, the bars still get their own pixel column; below it, one column holds several bars. */
export const LOD_LINE_PX = 1;

export type LodMode = 'line' | 'column' | 'body';

/** The pixels one bar is given: the width of the plot over the bars in view. 0 when the window has no span (nothing to draw). */
export function pxPerBar(plotW: number, spanMs: number, barMs: number): number {
  if (!(plotW > 0) || !(spanMs > 0) || !(barMs > 0)) return 0;
  return plotW * barMs / spanMs;
}

/** The regime a bar width asks for. */
export function lodMode(px: number): LodMode {
  if (!(px > 0)) return 'line';
  if (px >= LOD_BODY_PX) return 'body';
  return px >= LOD_LINE_PX ? 'column' : 'line';
}

/** One pixel column: every bar whose slot reaches it, added up. */
export interface Column {
  /** The column's pixel, from 0 (the window's first) to `plotW - 1`. */
  x: number;
  /** The open of the earliest bar in the column and the close of the latest. */
  open: number;
  close: number;
  /** The highest high and the lowest low of the column's bars. */
  high: number;
  low: number;
  /** The first and last bar's start, and how many bars the column holds. */
  first: number;
  last: number;
  count: number;
}

/**
 * The bars of the window folded into pixel columns, in time order: a bar goes in the column its start falls in (a bar that began before the
 * window shows in the first column), and a column's open and close are its earliest and latest bar's, whatever order the bars come in.
 */
export function columns(bars: readonly CandleRow[], t0: number, t1: number, plotW: number, barMs: number): Column[] {
  const span = t1 - t0, width = Math.floor(plotW);
  if (!(span > 0) || width < 1 || !(barMs > 0)) return [];
  const byX = new Map<number, Column>();
  for (const bar of bars) {
    const t = bar[0]!;
    if (!(t + barMs > t0 && t < t1)) continue;
    const x = Math.min(width - 1, Math.max(0, Math.floor((t - t0) / span * width)));
    const open = bar[1]!, high = bar[2]!, low = bar[3]!, close = bar[4]!;
    const into = byX.get(x);
    if (!into) { byX.set(x, { x, open, close, high, low, first: t, last: t, count: 1 }); continue; }
    into.high = Math.max(into.high, high);
    into.low = Math.min(into.low, low);
    if (t < into.first) { into.first = t; into.open = open; }
    if (t >= into.last) { into.last = t; into.close = close; }
    into.count += 1;
  }
  return [...byX.values()].sort((a, b) => a.x - b.x);
}
