import type { ReadoutRow } from '../../engine/studies/contract.ts';
import { el } from '../dom.ts';
import { t } from '../i18n.ts';
import { price } from '../format.ts';
import { note } from '../ui.ts';

/**
 * The Trade Plan panel (T-1040, D-31): it **reads** the numbers `st-entry` publishes in its `readout` and computes nothing. The piece
 * draws a plan with those same numbers, so the panel and the chart cannot say different things, and the calculation is not paid twice.
 *
 * The design is `docs/platform/plan-panel-design.md` (T-1041): a record with an order that means something (the price), not a list of
 * settings. One row is one number; the hierarchy is size and order, never another box.
 */

/** The four views of the design, over the seven codes the piece emits. No eighth is invented. */
export type PlanView = 'none' | 'armed' | 'entering' | 'closed';

const VIEW_OF: Readonly<Record<string, PlanView>> = {
  armed: 'armed', 'tp1-wait': 'armed',
  entered: 'entering', 'tp1-confirmed': 'entering',
  'tp-confirmed': 'closed', stopped: 'closed', 'entry-invalid': 'closed',
};

/** Which view a plan's state code belongs to; a code the design does not know is no plan at all rather than a guessed one. */
export function planView(state: string | undefined): PlanView { return (state !== undefined && VIEW_OF[state]) || 'none'; }

/** The levels the ladder draws, in the order the piece names them. `major` is entry and stop: the two numbers that command. */
export const LEVELS: readonly { id: string; major: boolean; risk: boolean }[] = [
  { id: 'tpLp', major: false, risk: false },
  { id: 'riskStop', major: false, risk: true },
  { id: 'riskEntry', major: false, risk: true },
  { id: 'entry', major: true, risk: false },
  { id: 'stop', major: true, risk: false },
];

/** The six targets, in the machine's own order; the ones it tracks are marked, as the design says. */
export const TARGETS = 6;
export const TRACKED = new Set([1, 3, 5, 6]);

export interface PlanLevel { readonly id: string; readonly price: number; readonly major: boolean; readonly risk: boolean }
export interface Plan {
  readonly id: string;
  readonly side: 'bull' | 'bear' | 'unknown';
  readonly session: string;
  readonly state: string;
  readonly view: PlanView;
  /** By price, highest first, so the ladder reads like the chart (a level the Pine inverts is shown where it falls). */
  readonly ladder: readonly PlanLevel[];
  readonly targets: readonly (number | null)[];
}

/** One row of a readout as the panel needs it: named values by id, both read as codes (the visible words are the app's). */
function named(row: ReadoutRow): Map<string, number | string | boolean> {
  return new Map(row.values.map(value => [value.id, value.value]));
}

/**
 * The plan a readout carries, or `null` when the piece has none to publish. Its `id` is `st:<side>:<session>` (`st-entry.ts`), and it
 * says the session the panel shows without parsing a sentence.
 */
export function planOf(rows: readonly ReadoutRow[]): Plan | null {
  const row = rows[0];
  if (!row) return null;
  const values = named(row), [, side = '', session = ''] = row.id.split(':');
  const number = (id: string): number | null => { const value = values.get(id); return typeof value === 'number' && Number.isFinite(value) ? value : null; };
  const state = values.get('state');
  const ladder: PlanLevel[] = [];
  for (const level of LEVELS) {
    const at = number(level.id);
    if (at !== null) ladder.push({ id: level.id, price: at, major: level.major, risk: level.risk });
  }
  ladder.sort((a, b) => b.price - a.price);
  const targets: (number | null)[] = [];
  for (let index = 1; index <= TARGETS; index++) targets.push(number(`tp${index}`));
  return {
    id: row.id,
    side: side === 'bull' || side === 'bear' ? side : 'unknown',
    session, state: typeof state === 'string' ? state : '',
    view: planView(typeof state === 'string' ? state : undefined),
    ladder, targets,
  };
}

const VIEW_WORD: Readonly<Record<PlanView, string>> = {
  none: t('No plan'), armed: t('Armed'), entering: t('In entry'), closed: t('Closed'),
};

const LEVEL_NAME: Readonly<Record<string, string>> = {
  entry: t('Entry'), stop: t('Stop'), riskEntry: t('Risk entry'), riskStop: t('Risk stop'), tpLp: t('TP at liquidity'),
};

/**
 * The panel's body: a band with the side, the view and the session, the ladder by price and the six targets. Without a plan it says so
 * and draws no ladder at all — a ladder of dashes looks like a plan that exists. Returns the redraw, which the panel's clock calls.
 */
export function buildPlanPanel(body: HTMLElement, read: () => readonly ReadoutRow[]): () => void {
  const render = (): void => {
    const plan = planOf(read());
    if (!plan) {
      body.replaceChildren(
        el('div', { class: 'plan-head' }, el('strong', { class: 'plan-state', textContent: VIEW_WORD.none })),
        note(t('No plan right now: the pieces have not given a trigger yet.')),
      );
      return;
    }
    const head = el('div', { class: `plan-head ${plan.side}` },
      el('strong', { class: 'plan-side', textContent: plan.side === 'bear' ? t('Short') : plan.side === 'bull' ? t('Long') : t('Plan') }),
      el('span', { class: 'plan-state', textContent: VIEW_WORD[plan.view] }),
      el('span', { class: 'plan-session', textContent: plan.session }),
    );
    // The state travels as the piece's own code, for a reader of the page, never as a sentence of the piece's.
    head.setAttribute('data-state', plan.state);
    // A code the four views do not know is shown as itself, never as another view's word: "No plan" over a drawn ladder is a lie.
    if (plan.view === 'none' && plan.state !== '') head.querySelector('.plan-state')!.textContent = plan.state;
    body.replaceChildren(
      head,
      el('div', { class: 'plan-ladder' }, ...plan.ladder.map(level =>
        el('div', { class: `plan-row${level.major ? ' major' : ''}${level.risk ? ' risk' : ''}` },
          el('span', { class: 'plan-name', textContent: LEVEL_NAME[level.id] ?? level.id }),
          el('span', { class: 'plan-price', textContent: price(level.price) }),
        ))),
      el('div', { class: 'plan-tps' }, ...plan.targets.map((at, index) =>
        el('span', { class: `plan-tp${TRACKED.has(index + 1) ? ' tracked' : ''}`, textContent: at === null ? '—' : `TP${index + 1} ${price(at)}` }))),
      note(t('The numbers are the piece\'s own, the ones it draws.')),
    );
  };
  render();
  return render;
}
