import { STUDY_API, type Plot, type StudyDef, type StudyOutput } from '../engine/studies/contract.ts';
import { readInputs, type InputSpec, type InputValues } from '../engine/inputs/schema.ts';
import type { Bar } from '../engine/series/source.ts';

/**
 * `cycle-90`: the OEC 90 MIN CYCLE piece — the four sessions of the 90-minute cycle (Asia, London, NY AM, NY PM) in their A and M
 * variants, which is where ST ENTRY takes its setups from (D-14: this piece is the one source of setups, and `reverse-zone`,
 * `singularity`, `bookmap-trigger` and `st-entry` hang off it).
 *
 * The Pine (`OECLiquidityindicators/OddEyeCircle`): the session strings are `cycle_zeusy_<group>_<variant>_time` (2657-2675), each
 * `'HHMM-HHMM:1234567'` — every day of the week — and its third argument says the clock is `'America/New_York'` (`critical_cycle_<group>`
 * and `_M`, 2681-2699). `time_critical_complement_A/M/D/X` (2703-2706) is the union of one variant across the four groups; `st-entry` and
 * `_Swing_RZ_Singularity` (3259) read the complements, and the box levels come from `GlobalFunctions._Draw_Range` (2060) →
 * `Draw_Range` (1996), which takes `high`/`low` of every bar inside the session as its top and bottom (3067-3088 pass it the session
 * string and take `[top, bot]` back), and `ST_Lines.OEC_Entry_Stop_Lines` gets `critical_cycle_<group>` plus the matching D or X window
 * (3330-3337): the A calls pass `critical_cycle_<group>_D`, the M calls `critical_cycle_<group>_X`.
 *
 * What this piece gives a consumer: `cycleSessions` — for each session of the asked span, its `from` and `to`, its `active` flag and,
 * once it has ended, its `high` and `low`. That is the period, the range and whether it is active, the three things the Pine hands to
 * `ST_Lines.OEC_Entry_Stop_Lines`.
 *
 * The **four** variants are carried (A, M, D, X; `OddEyeCircle:2657-2670`), because `st-entry` passes `_D` as the second window of A and
 * `_X` as the second of M (`:3330-3337`) and the bearish sides of `reverse-zone`, `singularity` and `bookmap-trigger` wait for D/X. X is
 * carried only where the Pine's X is a window of its own (Asia, London, NY PM): `cycle_nyam_X_time` repeats `_D` (`:2669-2670`), so the
 * duplicate NY AM X session is **not** carried (T-1036, D-27) and that stretch is answered by `nyam_d` alone. The `NYAM_M` call passing
 * `bool(na)` as its second window (`:3336`) is a call-site oddity of `st-entry`, not a window, and it belongs to that piece's card.
 *
 * Two rules the contract adds to the Pine's arithmetic:
 *
 * - the range of a session is not published before the session ends: the one under way is `active` with `high`/`low` null, and its
 *   box is drawn when it closes. Every bar a range reads starts inside its own window, so no bar after the session reaches it either.
 * - the sessions never consult the chart's timeframe for their boundaries: they are wall-clock times in `America/New_York`, so a
 *   daylight-saving change moves them in UTC (the Pine's do too, it reads the same zone). The zone is **not** an input any more: the
 *   page's zone (D-29, D-30) only writes hours, never places a window, so a chart read in UTC gets the same windows, spelled in UTC.
 *
 * `compute` is pure: no hub, no store, no fetch — the chart's candles arrive through `StudyData` and the painter draws the plots.
 */
const MINUTE = 60_000, DAY = 86_400_000;

/** The zone the Pine reads its sessions in: the third argument of its `time()` calls (2681-2699). */
export const CYCLE_90_ZONE = 'America/New_York';

/** The two clocks the piece can be read on: the Pine's zone, or the same wall-clock numbers read in UTC. */
export type CycleZone = 'America/New_York' | 'UTC';

export type CycleGroup = 'asia' | 'london' | 'nyam' | 'nypm';
export type CycleVariant = 'A' | 'M' | 'D' | 'X';

/** One session as the Pine declares it: its window as minutes after the zone's midnight, its label and its colour. */
export interface CycleSessionSpec {
  readonly id: string;
  readonly group: CycleGroup;
  readonly variant: CycleVariant;
  /** `1730` in the Pine's string is minute 1050. */
  readonly startMin: number;
  readonly endMin: number;
  /** The Pine's label default for the variant (`cycle_*_label`, 286-333). */
  readonly label: string;
  /** The Pine's colour for the group, with the variant's transparency (288-330). */
  readonly color: string;
  /** The Pine's transparency for the variant: 60 for A, 90 for M (288-330), its `color.new(colour, transparency)`. */
  readonly transparency: number;
}

/** The fifteen sessions the piece carries, in the Pine's order (`OddEyeCircle:2657-2675`): the Pine's duplicate NY AM X is not one (T-1036). */
export const CYCLE_SESSIONS: readonly CycleSessionSpec[] = [
  { id: 'asia_a', group: 'asia', variant: 'A', startMin: 17 * 60 + 30, endMin: 19 * 60, label: 'Asia A', color: '#e91e63', transparency: 60 },
  { id: 'asia_m', group: 'asia', variant: 'M', startMin: 19 * 60, endMin: 20 * 60 + 30, label: 'Asia M', color: '#e91e63', transparency: 90 },
  { id: 'asia_d', group: 'asia', variant: 'D', startMin: 20 * 60 + 30, endMin: 22 * 60, label: 'Asia D', color: '#e91e63', transparency: 90 },
  { id: 'asia_x', group: 'asia', variant: 'X', startMin: 22 * 60, endMin: 23 * 60 + 30, label: 'Asia X', color: '#e91e63', transparency: 90 },
  { id: 'london_a', group: 'london', variant: 'A', startMin: 60, endMin: 2 * 60 + 30, label: 'London A', color: '#2157f3', transparency: 60 },
  { id: 'london_m', group: 'london', variant: 'M', startMin: 2 * 60 + 30, endMin: 4 * 60, label: 'London M', color: '#2157f3', transparency: 90 },
  { id: 'london_d', group: 'london', variant: 'D', startMin: 4 * 60, endMin: 5 * 60 + 30, label: 'London D', color: '#2157f3', transparency: 90 },
  { id: 'london_x', group: 'london', variant: 'X', startMin: 5 * 60 + 30, endMin: 7 * 60, label: 'London X', color: '#2157f3', transparency: 90 },
  { id: 'nyam_a', group: 'nyam', variant: 'A', startMin: 7 * 60, endMin: 8 * 60 + 30, label: 'NY AM A', color: '#ff5d00', transparency: 60 },
  { id: 'nyam_m', group: 'nyam', variant: 'M', startMin: 8 * 60 + 30, endMin: 10 * 60, label: 'NY AM M', color: '#ff5d00', transparency: 90 },
  // The Pine writes the same window twice (`cycle_nyam_X_time` and `_D_time`, `OddEyeCircle:2669-2670`): the duplicate NY AM X is not
  // carried (T-1036), so this stretch is answered by `nyam_d` alone; X stays only where the Pine's X is a window of its own.
  { id: 'nyam_d', group: 'nyam', variant: 'D', startMin: 10 * 60, endMin: 11 * 60 + 30, label: 'NY AM D', color: '#ff5d00', transparency: 90 },
  { id: 'nypm_a', group: 'nypm', variant: 'A', startMin: 11 * 60 + 30, endMin: 13 * 60, label: 'NY PM A', color: '#ff5d00', transparency: 60 },
  { id: 'nypm_m', group: 'nypm', variant: 'M', startMin: 13 * 60, endMin: 14 * 60 + 30, label: 'NY PM M', color: '#ff5d00', transparency: 90 },
  { id: 'nypm_d', group: 'nypm', variant: 'D', startMin: 14 * 60 + 30, endMin: 16 * 60, label: 'NY PM D', color: '#ff5d00', transparency: 90 },
  { id: 'nypm_x', group: 'nypm', variant: 'X', startMin: 16 * 60, endMin: 17 * 60 + 30, label: 'NY PM X', color: '#ff5d00', transparency: 90 },
];

/** One session of one day: its window, and its high and low once it has ended. What the other pieces import. */
export interface CycleSession {
  readonly id: string;
  readonly group: CycleGroup;
  readonly variant: CycleVariant;
  readonly from: number;
  readonly to: number;
  /**
   * The session's high and low, grown while it runs (D-22, as the Pine does), or null when its start is not in the bars held: a
   * session measured from part of its window says nothing rather than half a range.
   */
  readonly high: number | null;
  readonly low: number | null;
  /** True while `now` is inside the session. */
  readonly active: boolean;
}

/** A calendar date in the session zone, as the wall clock reads it. */
interface CalendarDay { readonly y: number; readonly mo: number; readonly d: number }
/** A wall clock reading in the session zone. */
interface Wall { readonly y: number; readonly mo: number; readonly d: number; readonly hh: number; readonly mm: number; readonly ss: number }

const formatters = new Map<string, Intl.DateTimeFormat>();

/** One formatter a zone: `Intl` is the engine's only source of a zone's rules, and it holds the history of the daylight-saving changes. */
function formatterOf(zone: string): Intl.DateTimeFormat {
  const held = formatters.get(zone);
  if (held) return held;
  const made = new Intl.DateTimeFormat('en-US', { timeZone: zone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
  formatters.set(zone, made);
  return made;
}

/** How the zone's clock reads the instant `t`. */
export function wallClock(t: number, zone: CycleZone = CYCLE_90_ZONE): Wall {
  const parts = formatterOf(zone).formatToParts(new Date(t));
  let y = 0, mo = 1, d = 1, hh = 0, mm = 0, ss = 0;
  for (const part of parts) {
    const value = Number(part.value);
    if (part.type === 'year') y = value; else if (part.type === 'month') mo = value; else if (part.type === 'day') d = value;
    else if (part.type === 'hour') hh = value; else if (part.type === 'minute') mm = value; else if (part.type === 'second') ss = value;
  }
  return { y, mo, d, hh, mm, ss };
}

/** The zone's offset at `t` in milliseconds (its clock minus UTC): negative west of Greenwich, so New York is -5h or -4h. */
export function zoneOffset(t: number, zone: CycleZone = CYCLE_90_ZONE): number {
  const wall = wallClock(t, zone);
  return Date.UTC(wall.y, wall.mo - 1, wall.d, wall.hh, wall.mm, wall.ss) - t;
}

const minuteOf = (wall: Wall): number => wall.hh * 60 + wall.mm;
const atMidnight = (day: CalendarDay): number => Date.UTC(day.y, day.mo - 1, day.d);

/**
 * The instant the zone's clock reads `minuteOfDay` on `day`. A wall time the zone skips (the hour a spring-forward removes) opens at
 * the jump itself: the first minute whose clock has passed it, walked back a minute at a time (only a session start inside the gap
 * reaches that branch, so it costs nothing on the other 364 days).
 */
export function wallInstant(day: CalendarDay, minuteOfDay: number, zone: CycleZone = CYCLE_90_ZONE): number {
  const hour = Math.floor(minuteOfDay / 60), minute = minuteOfDay % 60, wanted = Date.UTC(day.y, day.mo - 1, day.d, hour, minute);
  const offsets = new Set([zoneOffset(wanted - DAY / 2, zone), zoneOffset(wanted + DAY / 2, zone)]);
  const candidates = [...offsets].map(offset => wanted - offset).sort((a, b) => a - b);
  for (const t of candidates) {
    const wall = wallClock(t, zone);
    if (wall.y === day.y && wall.mo === day.mo && wall.d === day.d && wall.hh === hour && wall.mm === minute) return t;
  }
  // Two readings an hour apart are the fall-back's repeated hour: the earlier one is the session's start.
  if (candidates.length > 1 && minuteOf(wallClock(candidates[0]!, zone)) === minuteOfDay) return candidates[0]!;
  let t = candidates[candidates.length - 1]!;
  for (let step = 0; step < 180 && minuteOf(wallClock(t, zone)) >= minuteOfDay; step += 1) t -= MINUTE;
  return t + MINUTE;
}

/** The zone's date of an instant. */
export function dayOf(t: number, zone: CycleZone = CYCLE_90_ZONE): CalendarDay {
  const wall = wallClock(t, zone);
  return { y: wall.y, mo: wall.mo, d: wall.d };
}

/** Every date from the date of `from` to the date of `to`, walked as calendar dates (never as a day of 24 hours: a DST day is not one). */
export function daysBetween(from: number, to: number, zone: CycleZone = CYCLE_90_ZONE): CalendarDay[] {
  const first = dayOf(from, zone), last = dayOf(to, zone), out: CalendarDay[] = [];
  for (let cursor = atMidnight(first); cursor <= atMidnight(last); cursor += DAY) {
    const date = new Date(cursor);
    out.push({ y: date.getUTCFullYear(), mo: date.getUTCMonth() + 1, d: date.getUTCDate() });
  }
  return out;
}

/**
 * The high and low of a session: the highest high and the lowest low of the bars that start inside its window, which is what
 * `Draw_Range` (`GlobalFunctions library:1996`) keeps while `time()` says the bar is in the session. A bar that starts before the
 * window is not read, so a range never reaches past its own session.
 */
export function sessionRange(bars: readonly Bar[], from: number, to: number): { readonly high: number; readonly low: number } | null {
  let high = -Infinity, low = Infinity, seen = 0;
  for (const bar of bars) {
    if (bar[0] < from || bar[0] >= to) continue;
    if (bar[2] > high) high = bar[2];
    if (bar[3] < low) low = bar[3];
    seen += 1;
  }
  return seen === 0 ? null : { high, low };
}

/**
 * The sessions of `CYCLE_SESSIONS` whose window opens inside `[from, to]`, measured on the bars held.
 *
 * `now` decides what has ended: a session that ends at or before it carries its high and low, the one under way is `active` with
 * both null (the contract publishes no range before its session ends), and a session whose bars are not held says so with nulls too.
 * `heldFrom` is where the candles the caller holds begin (the resolved series' own `heldFrom`, at least): a session that starts
 * before it is measured from part of its window, so it is reported without a range rather than with half of one.
 */
export function cycleSessions(bars: readonly Bar[], from: number, to: number, now: number, zone: CycleZone = CYCLE_90_ZONE, heldFrom?: number): CycleSession[] {
  if (!bars.length || to < from) return [];
  const held = heldFrom ?? bars[0]![0], out: CycleSession[] = [];
  for (const day of daysBetween(from, to, zone)) {
    for (const spec of CYCLE_SESSIONS) {
      const start = wallInstant(day, spec.startMin, zone), end = wallInstant(day, spec.endMin, zone);
      if (start > to || end <= from) continue;
      const active = start <= now && now < end;
      if (!active && end > now) continue; // opens later and has not finished either: nothing to say about it yet
      // D-22: the Pine grows the range while the session runs (`GlobalFunctions library:2001-2018`, `top := math.max(top, high)` with
      // the reset at `na(range_timezone[1])`). A session under way reads its bars up to `now` and never past it: a replay's series
      // can hold bars after the moment shown, and they are the future of that moment. The guard stays: a session whose start is not
      // in the bars held is a missing datum, not a live one, and carries no range.
      const measured = start >= held ? sessionRange(bars, start, active ? Math.min(end, now + 1) : end) : null;
      out.push({ id: spec.id, group: spec.group, variant: spec.variant, from: start, to: end, high: measured?.high ?? null, low: measured?.low ?? null, active });
    }
  }
  return out.sort((a, b) => a.from - b.from || a.id.localeCompare(b.id));
}

/** The session of a group and variant running at `now`, or null: `st-entry` asks this for the setup it is judging. */
export function activeSession(sessions: readonly CycleSession[], group: CycleGroup, variant: CycleVariant): CycleSession | null {
  for (const session of sessions) if (session.group === group && session.variant === variant && session.active) return session;
  return null;
}

/**
 * The part of the Pine's `time_critical_complement_A` / `_M` / `_D` / `_X` (2703-2706) this piece answers: whether any group's session of
 * that variant is running. All four variants are carried, so a consumer asking for D or X gets the Pine's answer.
 */
export function cycleComplement(sessions: readonly CycleSession[], variant: CycleVariant): boolean {
  for (const session of sessions) if (session.variant === variant && session.active) return true;
  return false;
}

const INPUTS: readonly InputSpec[] = [
  ...CYCLE_SESSIONS.flatMap((session): InputSpec[] => [
    { id: `${session.id}.on`, kind: 'bool', name: session.label, default: true, group: session.group === 'asia' ? 'Asia' : session.group === 'london' ? 'London' : session.group === 'nyam' ? 'NY AM' : 'NY PM' },
    { id: `${session.id}.label`, kind: 'string', name: `${session.label} label`, default: session.label, group: 'Labels' },
    { id: `${session.id}.color`, kind: 'color', name: `${session.label} colour`, default: session.color, group: 'Colours' },
  ]),
  { id: 'labels', kind: 'bool', name: 'Label', default: true, group: 'Style' },
  { id: 'pips', kind: 'bool', name: 'Range in the label', default: false, group: 'Style' },
  { id: 'border', kind: 'string', name: 'Border', default: 'dotted', options: ['solid', 'dashed', 'dotted'], group: 'Style' },
  { id: 'width', kind: 'int', name: 'Width', default: 1, min: 1, max: 5, group: 'Style' },
  { id: 'fill', kind: 'int', name: 'Fill transparency', default: 90, min: 0, max: 100, group: 'Style' },
];

const dashOf = (border: string): readonly number[] => border === 'solid' ? [] : border === 'dashed' ? [6, 4] : [2, 3];
const flag = (params: InputValues, id: string): boolean => params[id] === true;
const text = (params: InputValues, id: string, fallback: string): string => typeof params[id] === 'string' ? params[id] : fallback;
const number = (params: InputValues, id: string, fallback: number): number => typeof params[id] === 'number' && Number.isFinite(params[id]) ? params[id] : fallback;
const priceText = (value: number): string => Number(value.toFixed(2)).toString();

export const CYCLE_90: StudyDef = {
  api: STUDY_API,
  id: 'cycle-90',
  name: '90 min cycle',
  inputs: INPUTS,
  data: [{ key: 'chart', kind: 'candles', label: 'Chart candles' }],
  compute(ctx): StudyOutput | null {
    const series = ctx.data.candles('chart');
    if (!series || series.bars.length === 0) return null;
    const params = readInputs(INPUTS, ctx.params);
    // The windows are always the Pine's zone (D-14, D-30): the page's zone never moves them, only their writing.
    const zone: CycleZone = CYCLE_90_ZONE;
    // A replay shows the moment it shows: the sessions are judged at that moment, never at the wall clock's.
    const now = ctx.replayAt ?? ctx.now;
    const from = Math.max(ctx.view.t0, series.bars[0]![0]), to = Math.min(ctx.view.t1, now);
    if (to <= from) return null;
    const sessions = cycleSessions(series.bars, from, to, now, zone, series.heldFrom);
    if (sessions.length === 0) return null;
    const labels = flag(params, 'labels'), pips = flag(params, 'pips');
    const width = Math.max(1, Math.min(5, Math.round(number(params, 'width', 1))));
    // The Pine's `_opacity` is a transparency, not a solidity: it fills with `color.new(_color, _opacity)` (`GlobalFunctions library:1902`),
    // so its default 95 is a faint wash and the two crisp lines are what the eye reads.
    const fill = (100 - Math.max(0, Math.min(100, Math.round(number(params, 'fill', 90))))) / 100;
    const dash = dashOf(text(params, 'border', 'dotted'));
    const plots: Plot[] = [];
    for (const session of sessions) {
      if (!flag(params, `${session.id}.on`)) continue;
      const color = text(params, `${session.id}.color`, CYCLE_SESSIONS.find(spec => spec.id === session.id)?.color ?? '#e91e63');
      if (session.high === null || session.low === null) {
        // Its start is not in the bars held: the period is drawn, its levels are not.
        plots.push({ kind: 'bgcolor', t0: session.from, t1: Math.min(session.to, now), color, alpha: fill });
        continue;
      }
      // The Pine grows the session's box while it runs: the right edge is `now` until the session ends (D-22).
      const until = session.active ? Math.min(session.to, now) : session.to;
      plots.push({ kind: 'box', t0: session.from, t1: until, p0: session.low, p1: session.high, color, width, alpha: fill });
      // The Pine's 'Sandwich' (1897-1906): the two lines crisp over a faint fill.
      plots.push({ kind: 'line', points: [{ t: session.from, p: session.high }, { t: until, p: session.high }], style: { color, width, dash } });
      plots.push({ kind: 'line', points: [{ t: session.from, p: session.low }, { t: until, p: session.low }], style: { color, width, dash } });
      if (labels) {
        const name = text(params, `${session.id}.label`, CYCLE_SESSIONS.find(spec => spec.id === session.id)?.label ?? session.id);
        plots.push({ kind: 'label', t: session.from, p: session.high, text: pips ? `${name} ${priceText(session.high - session.low)}` : name, color });
      }
    }
    return plots.length === 0 ? null : { plots };
  },
};
