/**
 * The candles' own painting, in one place (T-1034): the map's canvas layer draws them and the heatmap no longer does, so the chart shows one
 * set of candles instead of two stacked copies.
 *
 * Pure drawing over the options it is given: the state, the view, the plot's size, the palette and two answers the caller owns — whether the
 * trade dust is on (the candles are then outlines, so the orders show through) and which bars are unusually busy (their ring). It touches no
 * pane and asks for nothing.
 */
import type { AppState } from '../store.ts';
import type { View } from '../view.ts';
import type { Palette } from '../theme.ts';
import { candleBody, footprintLayout } from '../panes/footprint.ts';
import { TIMEFRAMES } from '../hub.ts';

export interface CandlePaintOptions {
  readonly state: AppState;
  readonly view: View;
  readonly plotW: number;
  readonly plotH: number;
  readonly palette: Palette;
  /** How far the footprint's layout has taken over the slot (0 to 1); 0 without the footprint in view. */
  readonly narrowing?: number;
  /** While the trade dust shows: outline and a thin wick, never a filled body over the orders. */
  readonly hollow: boolean;
  /** Whether bar `i` is unusually busy (its volume ring, from the Highlights settings). */
  readonly hot?: (index: number) => boolean;
}

/** The bars of the view: a filled body with a contrasting edge, or the dust's hollow one; the unusual ones keep their ring either way. */
export function paintCandles(ctx: CanvasRenderingContext2D, o: CandlePaintOptions): void {
  const { state, view: v, plotW: pw, plotH: ph, palette: p } = o;
  const tf = TIMEFRAMES[state.timeframe] ?? 3_600_000;
  const bar = Math.max(1, pw * tf / (v.t1 - v.t0));
  // With the footprint on, the candle slides to the left of its slot and keeps a solid body, the row column takes the rest.
  const narrowing = o.narrowing ?? 0, layout = footprintLayout(bar), normal = candleBody(bar);
  const body = normal + (Math.max(1, layout.body) - normal) * narrowing;
  const hot = o.hot ?? (() => false);
  // A contrasting halo/outline keeps candles legible over both pink and green heat; it fades out over the dimmed footprint view.
  const edge = p.dark ? 'rgba(255,255,255,0.92)' : 'rgba(18,20,24,0.92)', halo = p.dark ? 'rgba(0,0,0,0.55)' : 'rgba(255,255,255,0.7)', outline = 1 - 0.85 * narrowing;
  // While the trade dust shows, a candle is its outline and a thin wick: a filled body (and its halo) would hide the orders inside it.
  const hollow = o.hollow;
  for (let ci = 0; ci < state.candles.length; ci++) {
    const c = state.candles[ci]!;
    if (c[0]! + tf < v.t0 || c[0]! > v.t1) continue;
    // Every candle, the one still forming too, has the same body and stands in the middle of its slot, so the spacing is the same all along.
    const xClassic = v.xOf(c[0]! + tf / 2, pw), x = xClassic + (v.xOf(c[0]!, pw) + layout.candleCenter - xClassic) * narrowing, up = c[4]! >= c[1]!;
    const color = up ? p.candleUp : p.candleDown;
    const yh = v.yOf(c[2]!, ph), yl = v.yOf(c[3]!, ph), yo = v.yOf(c[1]!, ph), yc = v.yOf(c[4]!, ph), cx = Math.round(x) + 0.5;
    const top = Math.min(yo, yc), height = Math.max(1.5, Math.abs(yc - yo));
    if (hollow) {
      ctx.globalAlpha = 0.9; ctx.lineWidth = 1; ctx.strokeStyle = color;
      ctx.beginPath(); ctx.moveTo(cx, yh); ctx.lineTo(cx, top); ctx.moveTo(cx, top + height); ctx.lineTo(cx, yl); ctx.stroke();
      ctx.lineWidth = 1.5; ctx.strokeRect(Math.round(x - body / 2) + 0.75, Math.round(top) + 0.75, Math.max(1, Math.round(body) - 1.5), Math.max(1, Math.round(height) - 1.5));
    } else {
      ctx.globalAlpha = outline;
      ctx.lineWidth = 3.5; ctx.strokeStyle = halo; ctx.beginPath(); ctx.moveTo(cx, yh); ctx.lineTo(cx, yl); ctx.stroke();
      ctx.lineWidth = 1.6; ctx.strokeStyle = edge; ctx.beginPath(); ctx.moveTo(cx, yh); ctx.lineTo(cx, yl); ctx.stroke();
      if (narrowing > 0.01) { ctx.globalAlpha = Math.min(1, narrowing * 1.5); ctx.lineWidth = 1.4; ctx.strokeStyle = color; ctx.beginPath(); ctx.moveTo(cx, yh); ctx.lineTo(cx, yl); ctx.stroke(); }
      ctx.lineWidth = 1;
      ctx.globalAlpha = outline; ctx.fillStyle = halo; ctx.fillRect(x - body / 2 - 1.5, top - 1.5, body + 3, height + 3);
      ctx.globalAlpha = 1; ctx.fillStyle = color; ctx.fillRect(x - body / 2, top, body, height);
      if (body >= 3) { ctx.globalAlpha = outline; ctx.strokeStyle = edge; ctx.strokeRect(x - body / 2 + 0.5, top + 0.5, body - 1, Math.max(0.5, height - 1)); }
    }
    // Hollow or filled, a candle of unusual volume keeps its ring (Highlights).
    if (hot(ci)) {
      ctx.save(); ctx.globalAlpha = 1; ctx.shadowColor = color; ctx.shadowBlur = 12; ctx.strokeStyle = color; ctx.lineWidth = 2.4;
      ctx.strokeRect(x - body / 2 - 2.5, top - 2.5, body + 5, height + 5); ctx.restore();
    }
  }
  ctx.globalAlpha = 1;
}
