import { t } from './i18n.ts';

/**
 * The page's own news: what a visit finds changed since the last one. The version below is the one this build carries; the browser keeps the
 * one it was last shown in `hlm-seen-update-v1`, which is a fact of that browser and never a setting of the page, so a layout does not carry it
 * (the news dot is the `whatsNew` switch, which does travel).
 */
export const SEEN_KEY = 'hlm-seen-update-v1';
export const WHATS_NEW_VERSION = '2026-10-25';

/** One entry of the news: a title and a sentence or two, the newest first. */
export interface NewsItem { title: string; text: string }

/** What this build has to tell; every word goes through `t()`, as the rest of the page's do. */
export const WHATS_NEW: readonly NewsItem[] = [
  { title: t('The profile\'s levels stay in its column'), text: t('The point of control and the value area are drawn inside the volume profile\'s column and no longer run across the map. The newest profile says POC, VAH and VAL; older ones PD, PW or PM.') },
  { title: t('The desktop\'s view on a phone'), text: t('Settings offers the desktop\'s arrangement and its full bar on a touch screen, so the columns and the book fit; the row stays while the choice is on.') },
  { title: t('The bar under the chart is shorter'), text: t('Since when it records, where it saves and where the data comes from moved into the tip over the live connection.') },
  { title: t('Hide the traded column\'s header'), text: t('The Volume profile\'s panel can hide the TRADED header; with it off, its bars start at the top.') },
];

/** Whether this version has not been shown here: what the browser last saw against what the page carries. */
export const unseen = (seen: string | null): boolean => seen !== WHATS_NEW_VERSION;

/** The version this browser was last shown (null when never, or with storage unavailable). */
export function readSeen(): string | null {
  try { return window.localStorage.getItem(SEEN_KEY); } catch { return null; }
}

/** Remember that this browser has been shown the news. */
export function markSeen(): void {
  try { window.localStorage.setItem(SEEN_KEY, WHATS_NEW_VERSION); } catch { /* storage unavailable */ }
}
