import { STUDY_API, type Plot, type StudyDef, type StudyOutput } from '../engine/studies/contract.ts';
import { readInputs, type InputSpec, type InputValues } from '../engine/inputs/schema.ts';
import type { Bar } from '../engine/series/source.ts';
import { CYCLE_90_ZONE, CYCLE_SESSIONS, cycleSessions, type CycleSession, type CycleZone } from './cycle-90.ts';
import { rzBullishChart, rzBearishChart, type ZoneOhlc } from './reverse-zone.ts';
import { singularityBullishChart, singularityBearishChart } from './singularity.ts';
import { bookmapBars } from './bookmap-trigger.ts';

/**
 * `st-entry`: the 90-minute cycle trade plan (D-08, D-14).
 *
 * The Pine arms one setup per group and variant (`OddEyeCircle:3330-3337`): the call at `:3330` creates the bullish setup inside the
 * **A** window (`critical_cycle_asia`) and the bearish one inside **D** (`critical_cycle_asia_D`); the `_M` call does the same with **M**
 * and **X**. A setup is armed on the bar the window turns off (`_end_session_bull = _swing_ST_session_bull and not _swing_ST_session_bull[1]`,
 * `OEC-library:1267`) and only when the session had the trigger of `:3020`/`:3031`:
 *
 *   `((rz or s) and bookmap) or ((rz or bookmap) and s) or (bookmap and rz_s_Retest)`
 *
 * which is a formula, not an invented quorum (D-09). The state machine is `OEC_Entry_Stop_Lines` (`OEC-library:1257`) plus
 * `Touch_Bullish`/`Touch_Bearish` (`:587`, `:885`): after arming it tracks the stop, the entry, TP_lp and the TPs.
 *
 * The seven levels and the six TPs are `Bullish_TP_Calc`/`Bearish_TP_Calc` (`:3167`, `:3190`) applied to the session's range, exactly as
 * D-10 fixes them; the pattern TPs (1.618-4.618) are not part of the plan. The HTF branch of `:3225` is not ported (D-17): the call is the
 * chart one, `Bullish_TP_Calc(bot_<session>, top_<session>)`.
 *
 * **The stop is the box's level (−1.0), not the `stop` variable (−0.9).** `Bullish_TP_Calc` returns both, but the call at `:3330` puts
 * `bot_lvl_box_bullish_Asia` (`:3170`) in the `_stop_y_bull` slot of `OEC_Entry_Stop_Lines` (`OEC-library:1257`), and the bearish
 * `top_lvl_box_bearish_Asia` in `_stop_y_bear`; `OEC-library:1312`/`:1353` copy those into `stop_bull_default`/`stop_bear_default`, which
 * is what the stop box draws (`:379`, `:388`, `:412`, `:421`) and what the hit test reads (`:459-463`). The `stop` variable the
 * calculator also returns is destructured at `:3230` and used nowhere. `risk_stop` (−0.786) therefore sits between the entry and the
 * stop, as it does in the original: the defect is copied, not repaired (a port that fixes it cannot be compared with the Pine).
 *
 * Not ported here, and said in the card: the `*_htf` and `*_double` evaluators (they compare against the previous higher-timeframe candle,
 * which is `previous-ohlc`'s data, not this piece's); the retest term of the formula (there is no retest piece yet, so it is false); and the
 * bearish bookmap bubbles, which `bookmap-trigger` does not emit yet — so a bearish plan can be built and stepped but, today, the trigger
 * never gets its third term. `compute` is pure: the painter draws.
 */

/** A chart candle as the evaluators read it. */
export interface Candle { readonly o: number; readonly h: number; readonly l: number; readonly c: number }

const candleOf = (bar: Bar): Candle => ({ o: bar[1], h: bar[2], l: bar[3], c: bar[4] });

/** The seven levels of D-10 plus the six TPs. The box's two prices are the session's own range; `stop` is the box's level (see above). */
export interface StLevels {
  readonly boxTop: number;
  readonly boxBottom: number;
  readonly entry: number;
  readonly riskEntry: number;
  readonly stop: number;
  readonly riskStop: number;
  readonly tpLp: number;
  readonly tps: readonly [number, number, number, number, number, number];
}

/** `Bullish_TP_Calc(bottom, top)` (`OddEyeCircle:3167`), verbatim coefficients. */
export function bullishTpCalc(bottom: number, top: number): StLevels {
  const range = top - bottom;
  return {
    boxTop: top,
    boxBottom: top - range,
    entry: top - range * 0.5,
    riskEntry: top - range * 0.382,
    stop: top + range * -1,
    riskStop: top - range * 0.786,
    tpLp: top + range * 0.618,
    tps: [top + range * 1.5, top + range * 2, top + range * 2.5, top + range * 3, top + range * 4, top + range * 4.5],
  };
}

/** `Bearish_TP_Calc(top, bottom)` (`OddEyeCircle:3190`), verbatim coefficients. */
export function bearishTpCalc(top: number, bottom: number): StLevels {
  const range = top - bottom;
  return {
    boxTop: bottom + range,
    boxBottom: bottom,
    entry: bottom + range * 0.5,
    riskEntry: bottom + range * 0.382,
    stop: bottom - range * -1,
    riskStop: bottom + range * 0.786,
    tpLp: bottom - range * 0.618,
    tps: [bottom - range * 1.5, bottom - range * 2, bottom - range * 2.5, bottom - range * 3, bottom - range * 4, bottom - range * 4.5],
  };
}

/**
 * The per-session trigger of `OddEyeCircle:3020` (bullish) and `:3031` (bearish), copied as it is. `retest` is the Pine's third term
 * (`bookmap and rz_s_Retest`); there is no retest piece yet, so its caller passes false.
 */
export function planTrigger(rz: boolean, s: boolean, bookmap: boolean, retest: boolean): boolean {
  return ((rz || s) && bookmap) || ((rz || bookmap) && s) || (bookmap && retest);
}

export type PlanSide = 'bull' | 'bear';

/**
 * The states the Pine's machine shows in a label (`OEC-library:632-880`): armed, entry taken or refused, TP_lp waiting or confirmed,
 * a TP reached, or the stop taken (which closes the setup: `st.is_active := false`, `:610`).
 */
export type PlanState = 'armed' | 'entered' | 'entry-invalid' | 'tp1-wait' | 'tp1-confirmed' | 'tp-confirmed' | 'stopped';

/**
 * The TPs the machine actually tracks. The Pine's boxes and `Touch_Bullish` use TP1 (1.5), TP3 (2.5), TP5 (4) and TP6 (4.5)
 * (`OEC-library:381-385`, `:741-879`): 2.0 and 3.0 are drawn as levels but never tracked. The indexes are the `tps` ones.
 */
export const TRACKED_TPS: readonly number[] = [0, 2, 4, 5];

export interface StPlan {
  readonly side: PlanSide;
  /** The session that armed it, e.g. `asia_a`. */
  readonly session: string;
  /** The bar the setup is armed on: the first one at or after the window's end (`OEC-library:1267`, `:1298`). */
  readonly created: number;
  readonly levels: StLevels;
  readonly state: PlanState;
  readonly stopHit: boolean;
  readonly entryValid: boolean;
  readonly entryInvalid: boolean;
  readonly tpLpTouched: boolean;
  readonly tpLpConfirmed: boolean;
  readonly tpsTouched: readonly boolean[];
  readonly tpsConfirmed: readonly boolean[];
}

export function initialPlan(side: PlanSide, session: string, created: number, levels: StLevels): StPlan {
  return {
    side, session, created, levels, state: 'armed', stopHit: false, entryValid: false, entryInvalid: false,
    tpLpTouched: false, tpLpConfirmed: false,
    tpsTouched: [false, false, false, false, false, false], tpsConfirmed: [false, false, false, false, false, false],
  };
}

function stateOf(plan: Omit<StPlan, 'state'>): PlanState {
  if (plan.stopHit) return 'stopped';
  if (plan.tpsConfirmed.some(Boolean) || plan.tpsTouched.some(Boolean)) return 'tp-confirmed';
  if (plan.entryValid) return 'entered';
  if (plan.tpLpConfirmed) return 'tp1-confirmed';
  if (plan.tpLpTouched) return 'tp1-wait';
  if (plan.entryInvalid) return 'entry-invalid';
  return 'armed';
}

/**
 * One confirmed bar of `Touch_Bullish`/`Touch_Bearish` (`OEC-library:587`, `:885`) with the chart evaluators (`:472-575`). The order is the
 * Pine's: the stop first (it closes the setup), then the entry, then TP_lp, then the TPs.
 */
export function nextPlan(plan: StPlan, prev2: Candle, prev: Candle, cur: Candle): StPlan {
  if (plan.stopHit) return plan;
  const level = plan.levels;
  let stopHit = false, entryValid = plan.entryValid, entryInvalid = plan.entryInvalid;
  let tpLpTouched = plan.tpLpTouched, tpLpConfirmed = plan.tpLpConfirmed;
  const tpsTouched = [...plan.tpsTouched], tpsConfirmed = [...plan.tpsConfirmed];

  if (plan.side === 'bull') {
    // eval_stop_hit_bullish (`OEC-library:459`); the Pine sets is_active false and deletes the drawing (`:610`).
    if (cur.l <= level.stop) stopHit = true;
    // eval_entry_invalid_bullish (`:472`): a bearish close below the entry, below the previous low.
    if (cur.c < cur.o && cur.c < prev.l && cur.c < level.entry && prev.c < level.entry && prev.c < prev.o) entryInvalid = true;
    // eval_entry_valid_bullish (`:481`): a bullish close over the previous one, the previous bar dipping under the entry.
    if (cur.c > cur.o && cur.c > prev.c && prev.l < level.entry && prev.c < prev.o && prev2.c > level.entry) entryValid = true;
    if (cur.h >= level.tpLp) tpLpTouched = true;
    // eval_tp1_valid_bullish (`:503`).
    if (cur.c > cur.o && cur.c > level.tpLp && prev.c > level.tpLp && cur.c > prev.h && prev.c > prev.o) tpLpConfirmed = true;
    for (const index of TRACKED_TPS) {
      const tp = level.tps[index]!;
      if (cur.h >= tp) tpsTouched[index] = true;
      // TP1 (index 0) needs eval_tp_valid_bullish (`:517`); 2.5, 4 and 4.5 are confirmed on touch (`OEC-library:796`, `:833`, `:863`).
      const valid = index === 0
        ? cur.c > cur.o && cur.c > prev.h && cur.c > tp && prev.c > prev.o && prev.c > tp
        : cur.h >= tp;
      if (valid) tpsConfirmed[index] = true;
    }
  } else {
    // eval_stop_hit_bearish (`:462`).
    if (cur.h >= level.stop) stopHit = true;
    // eval_entry_invalid_bearish (`:532`).
    if (cur.c > cur.o && cur.c > prev.h && cur.c > level.entry && prev.c > level.entry && prev.c > prev.o) entryInvalid = true;
    // eval_entry_valid_bearish (`:541`).
    if (cur.c < cur.o && cur.c < prev.c && prev.h > level.entry && prev.c > prev.o && prev2.c < level.entry) entryValid = true;
    if (cur.l <= level.tpLp) tpLpTouched = true;
    // eval_tp1_valid_bearish (`:561`).
    if (cur.c < cur.o && cur.c < level.tpLp && prev.c < level.tpLp && cur.c < prev.l && prev.c < prev.o) tpLpConfirmed = true;
    for (const index of TRACKED_TPS) {
      const tp = level.tps[index]!;
      if (cur.l <= tp) tpsTouched[index] = true;
      const valid = index === 0
        ? cur.c < cur.o && cur.c < prev.l && cur.c < tp && prev.c < prev.o && prev.c < tp
        : cur.l <= tp;
      if (valid) tpsConfirmed[index] = true;
    }
  }

  const next = { ...plan, stopHit, entryValid, entryInvalid, tpLpTouched, tpLpConfirmed, tpsTouched, tpsConfirmed };
  return { ...next, state: stateOf(next) };
}

/** The setup a session arms: A and M call it bullish, D and X bearish (`OddEyeCircle:3330-3337`). */
function sideOf(session: CycleSession): PlanSide {
  return session.variant === 'A' || session.variant === 'M' ? 'bull' : 'bear';
}

/**
 * Why there is no plan (T-1055), as a code the app translates. Chosen with `stPlans` in front: `waitingSession` is no window closed yet,
 * `noTrigger` is a window that closed without the formula of `:3020`/`:3031`, and `noBookmap` is the subcase where the reason was the
 * missing bookmap bubble. A rejected entry is **not** here: in this port it is a plan row whose `state` is `entry-invalid` or `stopped`.
 */
export type PlanReason = 'waitingSession' | 'noTrigger' | 'noBookmap';

export interface PlanStatus {
  readonly plans: readonly StPlan[];
  /** Null when there is at least one plan. */
  readonly reason: PlanReason | null;
}

export interface StParams {
  readonly bins: number;
  readonly mode: string;
  readonly autoTop: number;
  readonly manual: number;
  readonly minVolPct: number;
}

/**
 * The plans of the stretch, oldest first, one per session that ends with the trigger of `:3020`/`:3031`. A session only arms a plan when it
 * has ended and its bars are held (its high and low are `cycle-90`'s, never half a window), and the bar that arms it is the first one at or
 * after the window's end. The machine then runs on every confirmed bar.
 *
 * The `NYAM_M` call passes `bool(na)` as its bearish window and `na` for every bearish level (`OddEyeCircle:3336`). That window is the
 * Pine's duplicate of `nyam_d` (`cycle_nyam_X_time`, `:2669-2670`), which `cycle-90` does not carry as a session any more (T-1036),
 * so nothing is skipped here: the D setup from the `NYAM_A` call is the one that exists there.
 */
export function stPlanStatus(chart: readonly Bar[], ltf: readonly Bar[], now: number, zone: CycleZone, params: StParams): PlanStatus {
  if (chart.length < 5) return { plans: [], reason: 'waitingSession' };
  const barMs = chart[1]![0] - chart[0]![0];
  if (!(barMs > 0)) return { plans: [], reason: 'waitingSession' };
  const sessions = cycleSessions(chart, chart[0]![0], chart[chart.length - 1]![0] + barMs, now, zone);
  const bubbles = bookmapBars(chart, ltf, now, zone, params);
  const plans: StPlan[] = [];

  // The four conditions once per bar, as prefix counts: a session then asks its window in constant time instead of walking the
  // stretch four times per window (a week of five-minute bars is 112 sessions over 2,000 bars).
  const bullRz: boolean[] = [], bullS: boolean[] = [], bearRz: boolean[] = [], bearS: boolean[] = [];
  for (let index = 0; index < chart.length; index += 1) {
    const bar = chart[index]!;
    const cur: ZoneOhlc = { o: bar[1], h: bar[2], l: bar[3], c: bar[4] };
    const p1 = index >= 1 ? chart[index - 1]! : null, p2 = index >= 2 ? chart[index - 2]! : null, p3 = index >= 3 ? chart[index - 3]! : null;
    const o1: ZoneOhlc = p1 ? { o: p1[1], h: p1[2], l: p1[3], c: p1[4] } : cur;
    const o2: ZoneOhlc = p2 ? { o: p2[1], h: p2[2], l: p2[3], c: p2[4] } : cur;
    const o3: ZoneOhlc = p3 ? { o: p3[1], h: p3[2], l: p3[3], c: p3[4] } : cur;
    bullRz.push(index >= 3 && rzBullishChart(cur, o1, o2, o3));
    bullS.push(index >= 3 && singularityBullishChart(cur, o1, o2, o3));
    bearRz.push(index >= 3 && rzBearishChart(cur, o1, o2, o3));
    bearS.push(index >= 3 && singularityBearishChart(cur, o1, o2, o3));
  }
  const prefix = (flags: readonly boolean[]): number[] => {
    const counts = new Array<number>(flags.length + 1).fill(0);
    for (let index = 0; index < flags.length; index += 1) counts[index + 1] = counts[index]! + (flags[index] ? 1 : 0);
    return counts;
  };
  const rzBull = prefix(bullRz), sBull = prefix(bullS), rzBear = prefix(bearRz), sBear = prefix(bearS);
  const firstAtOrAfter = (t: number): number => {
    let low = 0, high = chart.length;
    while (low < high) { const mid = (low + high) >> 1; if (chart[mid]![0] < t) low = mid + 1; else high = mid; }
    return low;
  };
  const withBookmap = new Set(bubbles.map(bubble => `${bubble.side}:${bubble.session.id}`));
  // What kept the plan from existing, kept as codes and not as prose (T-1055).
  let waited = true, withoutBookmap = false;

  for (const session of sessions) {
    if (session.active) continue; // its window has not closed: nothing can arm yet, and the piece says it is waiting
    if (session.high === null || session.low === null) continue; // its bars are not held: no range to build on
    waited = false;
    const side = sideOf(session);
    const from = firstAtOrAfter(session.from), to = firstAtOrAfter(session.to);
    const rz = (side === 'bull' ? rzBull[to]! - rzBull[from]! : rzBear[to]! - rzBear[from]!) > 0;
    const s = (side === 'bull' ? sBull[to]! - sBull[from]! : sBear[to]! - sBear[from]!) > 0;
    const bookmap = withBookmap.has(`${side}:${session.id}`);
    if (!bookmap && (rz || s)) withoutBookmap = true;
    // The retest term of the formula has no piece yet: it is false, and the card says so.
    if (!planTrigger(rz, s, bookmap, false)) continue;

    const levels = side === 'bull' ? bullishTpCalc(session.low, session.high) : bearishTpCalc(session.high, session.low);
    const index = firstAtOrAfter(session.to);
    if (index >= chart.length) continue; // the window ends after the last bar: nothing to arm on yet
    if (!(chart[index]![0] + barMs <= now)) continue; // the arming bar has not closed
    let plan = initialPlan(side, session.id, chart[index]![0], levels);
    for (let at = index; at < chart.length; at += 1) {
      const bar = chart[at]!;
      if (bar[0] + barMs > now) break; // the forming bar is not read
      if (at < 2) continue;
      plan = nextPlan(plan, candleOf(chart[at - 2]!), candleOf(chart[at - 1]!), candleOf(bar));
      if (plan.stopHit) break;
    }
    plans.push(plan);
  }
  plans.sort((a, b) => a.created - b.created || a.side.localeCompare(b.side));
  if (plans.length) return { plans, reason: null };
  return { plans, reason: waited ? 'waitingSession' : withoutBookmap ? 'noBookmap' : 'noTrigger' };
}

/** The plans of the stretch, oldest first. Kept as the piece's own API; `stPlanStatus` adds why there is none. */
export function stPlans(chart: readonly Bar[], ltf: readonly Bar[], now: number, zone: CycleZone, params: StParams): readonly StPlan[] {
  return stPlanStatus(chart, ltf, now, zone, params).plans;
}

const INPUTS: readonly InputSpec[] = [
  { id: 'plan', kind: 'bool', name: 'Trade plan', default: true, group: 'ST entry' },
  { id: 'bins', kind: 'int', name: 'Price bins (bookmap)', default: 10, min: 5, max: 30, group: 'Bookmap' },
  { id: 'mode', kind: 'string', name: 'Threshold mode', default: 'auto', options: ['auto', 'manual'], group: 'Bookmap' },
  { id: 'autoTop', kind: 'float', name: 'Auto: top %', default: 10, min: 1, max: 50, group: 'Bookmap' },
  { id: 'manual', kind: 'float', name: 'Manual: delta threshold', default: 1_000, min: 1, max: 1_000_000_000, group: 'Bookmap' },
  { id: 'minVolPct', kind: 'float', name: 'Min volume %', default: 80, min: 10, max: 200, group: 'Bookmap' },
];

const flag = (params: InputValues, id: string): boolean => params[id] === true;
const text = (params: InputValues, id: string, fallback: string): string => typeof params[id] === 'string' ? params[id] as string : fallback;
const number = (params: InputValues, id: string, fallback: number): number => typeof params[id] === 'number' && Number.isFinite(params[id]) ? params[id] : fallback;
const labelOf = (id: string): string => CYCLE_SESSIONS.find(spec => spec.id === id)?.label ?? id;
const stateText: Record<PlanState, string> = {
  armed: 'armed', entered: 'entry', 'entry-invalid': 'entry ✗', 'tp1-wait': 'TP1 wait', 'tp1-confirmed': 'TP1 ✓', 'tp-confirmed': 'TP ✓', stopped: 'stop',
};

export const ST_ENTRY: StudyDef = {
  api: STUDY_API,
  id: 'st-entry',
  name: 'ST entry (trade plan)',
  inputs: INPUTS,
  data: [
    { key: 'chart', kind: 'candles', label: 'Chart candles' },
    { key: 'ltf', kind: 'candles', label: 'Lower-timeframe candles' },
  ],
  compute(ctx): StudyOutput | null {
    const chart = ctx.data.candles('chart'), ltf = ctx.data.candles('ltf');
    if (!chart) return null;
    if (!ltf) return null; // the bookmap term of the trigger needs it: without it there is no plan, never a series in its place
    const params = readInputs(INPUTS, ctx.params);
    if (!flag(params, 'plan')) return null;
    // The windows are the Pine's zone (D-14, D-30): the page's zone never moves them, only writes their hours.
    const zone: CycleZone = CYCLE_90_ZONE;
    const status = stPlanStatus(chart.bars, ltf.bars, ctx.now, zone, {
      bins: Math.round(number(params, 'bins', 10)),
      mode: text(params, 'mode', 'auto'),
      autoTop: number(params, 'autoTop', 10),
      manual: number(params, 'manual', 1_000),
      minVolPct: number(params, 'minVolPct', 80),
    });
    const plans = status.plans;
    if (!plans.length) {
      // Nothing to draw, but the panel must be able to say **why** (D-08, T-1055): codes, never prose.
      return {
        plots: [],
        readout: [{ id: 'st:none', label: 'plan', values: [{ id: 'state', value: 'noPlan' }, { id: 'reason', value: status.reason ?? 'noTrigger' }] }],
      };
    }
    const barMs = chart.bars.length > 1 ? chart.bars[1]![0] - chart.bars[0]![0] : 0;
    const last = chart.bars[chart.bars.length - 1]![0] + barMs;
    const plots: Plot[] = [], labels = [], tags = [];
    for (const plan of plans) {
      const color = plan.side === 'bull' ? ctx.palette.bid : ctx.palette.ask;
      const stop = plan.state === 'stopped';
      // Entry and stop are the two the machine closes on; the TPs are its targets. The drawing stays plain: the painter owns the look.
      plots.push({ kind: 'line', points: [{ t: plan.created, p: plan.levels.entry }, { t: last, p: plan.levels.entry }], style: { color, width: 1, dash: stop ? [3, 3] : [] } });
      plots.push({ kind: 'line', points: [{ t: plan.created, p: plan.levels.stop }, { t: last, p: plan.levels.stop }], style: { color: ctx.palette.ask, width: 1, dash: [6, 4] } });
      for (const index of TRACKED_TPS) {
        const tp = plan.levels.tps[index]!;
        const taken = plan.tpsConfirmed[index] === true;
        plots.push({
          kind: 'line', points: [{ t: plan.created, p: tp }, { t: last, p: tp }],
          style: { color, width: 1, dash: taken ? [] : [2, 3], alpha: taken ? 1 : 0.6 },
        });
      }
      labels.push({ text: `${plan.side === 'bull' ? '+' : '-'}ST ${labelOf(plan.session)} · ${stateText[plan.state]}`, price: plan.levels.entry, t: plan.created, rank: 4, color });
      // The state travels in the tag's key as well: the Trade Plan reads it without parsing a drawing.
      tags.push({ key: `st:${plan.side}:${plan.session}:${plan.state}`, price: plan.levels.entry, text: `ST ${labelOf(plan.session)}`, rank: 4, color });
    }
    // The plan as numbers (D-31): the same values the lines above are drawn at, so a panel never recalculates them.
    const readout = plans.map(plan => ({
      id: `st:${plan.side}:${plan.session}`,
      label: `${plan.side} ${plan.session}`,
      values: [
        { id: 'state', value: plan.state },
        { id: 'created', value: plan.created },
        { id: 'entry', value: plan.levels.entry },
        { id: 'stop', value: plan.levels.stop },
        { id: 'riskEntry', value: plan.levels.riskEntry },
        { id: 'riskStop', value: plan.levels.riskStop },
        { id: 'tpLp', value: plan.levels.tpLp },
        ...plan.levels.tps.map((tp, index) => ({ id: `tp${index + 1}`, value: tp })),
      ],
    }));
    return { plots, labels, tags, readout };
  },
};
