/**
 * A piece's own opacity (T-0046): the number its panel shows, kept in `state.studyOpacity` by study id. One for each, so a busy piece can sit
 * behind a quiet one without hiding it; the Layers panel's opacity for the whole studies layer still scales them all together.
 */
export type StudyOpacity = Readonly<Record<string, number>>;

/** The opacity a piece draws at, 0 to 1: its own setting, 100% when it was never touched. */
export function studyAlpha(state: { studyOpacity: StudyOpacity }, id: string): number {
  const held = state.studyOpacity[id];
  return typeof held === 'number' && Number.isFinite(held) ? Math.min(100, Math.max(0, held)) / 100 : 1;
}

/** The same setting, written: whole percent, kept inside 0 to 100, so a save or a layout can only hold what the slider offers. */
export function setStudyOpacity(opacity: StudyOpacity, id: string, percent: number): StudyOpacity {
  const value = Number.isFinite(percent) ? Math.round(Math.min(100, Math.max(0, percent))) : 100;
  return { ...opacity, [id]: value };
}
