import { STUDY_API, type Plot, type StudyDef, type StudyOutput } from '../engine/studies/contract.ts';
import { readInputs, type InputSpec } from '../engine/inputs/schema.ts';
import { isTimeframe, timeframeMs, type Timeframe } from '../engine/time/timeframe.ts';
import type { Bar } from '../engine/series/source.ts';

/**
 * `htf-candles`: the OEC TIMEFRAME CANDLES ported to the study contract — candles of a higher timeframe drawn to the right of the chart.
 *
 * The Pine it comes from (`OECLiquidityindicators/OddEyeCircle`): a new HTF candle starts when the HTF period's start time changes
 * (`newDay_tf_1`, lines 1936-1956), the candle is given the bar's open/high/low/close (`newDC_tf_1`, 1212-1235) and every bar updates its
 * high, low and close (`updateDC_tf_1`, 1240-1265); the drawing places them right of the last bar (`drawDC_tf_1`, 1284-1335:
 * `position = bar_index + offset + (count - i) * 3`, the body two bars wide, the wick in the middle).
 *
 * One computation, two styles: `candle` draws the body and the wick, `ohlc` the high-low bar with its open and close ticks. The style is an
 * input, never a second path through the aggregation.
 *
 * The card's other half (KENJI FORCE/TREND) is not a candle style in its Pine: it is a macro bias table (VIX, DXY, PCCE, USDT.D with
 * percent thresholds, `KENJI` lines 352-370 and 660-720). See the card's Notas: it needs the user's correction before it is a piece.
 *
 * `compute` is pure (same input, same output), imports no hub, store or fetch, and returns plots; the engine's painter
 * (`engine/draw/painter.ts`) is the `render(Scope)` that draws them, so this file never touches a canvas.
 */
const MINUTE = 60_000, DAY = 86_400_000, WEEK = 604_800_000;

const INPUTS: readonly InputSpec[] = [
  { id: 'type', kind: 'string', name: 'Type', default: 'htf-pda', options: ['custom', 'htf-pda', 'htf-pda-w', 'htf-pda-m'], group: 'Timeframe candles' },
  { id: 'timeframe', kind: 'tf', name: 'Timeframe', default: '60', group: 'Timeframe candles' },
  { id: 'style', kind: 'string', name: 'Style', default: 'candle', options: ['candle', 'ohlc'], group: 'Timeframe candles' },
  { id: 'count', kind: 'int', name: 'Candles', default: 6, min: 4, max: 10, group: 'Timeframe candles' },
  { id: 'offset', kind: 'int', name: 'Offset', default: 80, min: 5, max: 100, group: 'Timeframe candles' },
  { id: 'dual', kind: 'bool', name: 'Two frames', default: false, group: 'Timeframe candles' },
  { id: 'second', kind: 'tf', name: 'Second timeframe', default: 'D', group: 'Timeframe candles' },
  { id: 'label', kind: 'bool', name: 'Timeframe label', default: true, group: 'Style' },
  { id: 'bull', kind: 'color', name: 'Bullish', default: '#73c3e1', group: 'Style' },
  { id: 'bear', kind: 'color', name: 'Bearish', default: '#ffc0b2', group: 'Style' },
  { id: 'wick', kind: 'color', name: 'Wick', default: '#ffffff', group: 'Style' },
];

type HtfType = 'custom' | 'htf-pda' | 'htf-pda-w' | 'htf-pda-m';
type Style = 'candle' | 'ohlc';

interface HtfBar { start: number; open: number; high: number; low: number; close: number }

/** The bar size the chart's candles are on, from their own starts (a study is told the bars, not the page's timeframe name). */
function barSize(bars: readonly Bar[]): number {
  for (let index = 1; index < bars.length; index += 1) {
    const step = bars[index]![0] - bars[index - 1]![0];
    if (step > 0) return step;
  }
  return MINUTE;
}

/**
 * Pine's `auto_htfPDA`, `_W` and `_M` (`GlobalFunctions library` 304-345), on the bar size instead of the page's timeframe id. Pine answers
 * `12M` above a week and the engine has no 12-month timeframe: a month is the highest it holds, and the piece says so in its own options.
 */
export function autoTimeframe(chartMs: number, type: Exclude<HtfType, 'custom'>): Timeframe {
  const minutes = chartMs / MINUTE, intraday = chartMs < DAY;
  if (type === 'htf-pda-w') {
    if (intraday) return minutes < 15 ? '15' : minutes < 240 ? '240' : 'W';
    return chartMs === DAY ? 'W' : 'M';
  }
  if (type === 'htf-pda-m') {
    if (intraday) return minutes < 5 ? '5' : minutes < 60 ? '60' : 'D';
    return 'M';
  }
  if (intraday) return minutes < 5 ? '15' : minutes < 15 ? '60' : minutes < 60 ? '240' : minutes < 240 ? 'D' : 'W';
  return 'M';
}

/** The start of the period `t` falls in: Pine's `timeframe.change` boundaries, in UTC (the page's candles are exchange-stamped and its days, weeks and months start at 00:00, Monday and the 1st, UTC). */
export function periodStart(t: number, tf: Timeframe): number {
  if (tf === 'D') return Math.floor(t / DAY) * DAY;
  if (tf === 'W') {
    const day = Math.floor(t / DAY) * DAY, weekday = new Date(day).getUTCDay();
    return day - ((weekday + 6) % 7) * DAY; // Monday
  }
  if (tf === 'M') { const date = new Date(t); return Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), 1); }
  return Math.floor(t / timeframeMs(tf)) * timeframeMs(tf);
}

/**
 * How far the second frame starts after the first, in chart bars: the Pine's `+ 40` (`OddEyeCircle:1669`), fixed and not a gap worked out
 * from the candle count. With `count = 6` the first frame ends 18 bars out and the second begins 43, so 25 bars of air between them — the
 * room its own timeframe box (`'TF\n'` at `position + 20`, `:1497`) is drawn in.
 */
export const DUAL_GAP = 40;

/**
 * The frames to draw and where each starts, in chart bars after the last one (T-0044): one, or with the dual mode on two — the automatic
 * one (or the fixed one) and the second the person chose, as the Pine's `tf_candles_tf_2`. Both frames place their candles the same way
 * (`(count - i) * 3`, `:1301` and `:1669`); the second starts `DUAL_GAP` bars further out, exactly as the Pine does. A second frame equal to
 * the first adds nothing.
 */
export function framePlan(tf: Timeframe, dual: boolean, offset: number, second: Timeframe = 'D'): { tf: Timeframe; offset: number }[] {
  const frames = [{ tf, offset }];
  if (dual && second !== tf) frames.push({ tf: second, offset: offset + DUAL_GAP });
  return frames;
}

/** The chart's bars folded into the higher timeframe: a new candle when the period's start changes, then high, low and close follow (`newDC_tf_1` / `updateDC_tf_1`). */
export function aggregate(bars: readonly Bar[], tf: Timeframe): HtfBar[] {
  const out: HtfBar[] = [];
  for (const bar of bars) {
    const start = periodStart(bar[0], tf), last = out[out.length - 1];
    if (!last || last.start !== start) {
      out.push({ start, open: bar[1], high: bar[2], low: bar[3], close: bar[4] });
      continue;
    }
    last.high = Math.max(last.high, bar[2]);
    last.low = Math.min(last.low, bar[3]);
    last.close = bar[4];
  }
  return out;
}

const TIMEFRAME_NAMES: Readonly<Record<Timeframe, string>> = { '1': '1m', '5': '5m', '15': '15m', '30': '30m', '60': '1H', '240': '4H', D: 'D', W: 'W', M: 'M' };

export const HTF_CANDLES: StudyDef = {
  api: STUDY_API,
  id: 'htf-candles',
  name: 'Higher-timeframe candles',
  inputs: INPUTS,
  data: [{ key: 'chart', kind: 'candles', label: 'Chart candles' }],
  compute(ctx): StudyOutput | null {
    const series = ctx.data.candles('chart');
    if (!series || series.bars.length < 2) return null;
    const params = readInputs(INPUTS, ctx.params);
    const type: HtfType = params['type'] === 'custom' || params['type'] === 'htf-pda' || params['type'] === 'htf-pda-w' || params['type'] === 'htf-pda-m' ? params['type'] : 'htf-pda';
    const style: Style = params['style'] === 'ohlc' ? 'ohlc' : 'candle';
    const rawCount = params['count'], rawOffset = params['offset'];
    const count = typeof rawCount === 'number' && Number.isFinite(rawCount) ? Math.max(4, Math.min(10, Math.round(rawCount))) : 6;
    const offset = typeof rawOffset === 'number' && Number.isFinite(rawOffset) ? Math.max(5, Math.min(100, Math.round(rawOffset))) : 80;
    const bull = typeof params['bull'] === 'string' ? params['bull'] : '#73c3e1';
    const bear = typeof params['bear'] === 'string' ? params['bear'] : '#ffc0b2';
    const wick = typeof params['wick'] === 'string' ? params['wick'] : '#ffffff';
    const label = params['label'] === true;
    const chartMs = barSize(series.bars);
    const custom = params['timeframe'];
    const tf: Timeframe = type === 'custom' && typeof custom === 'string' && isTimeframe(custom) ? custom : autoTimeframe(chartMs, type === 'custom' ? 'htf-pda' : type);
    const rawSecond = params['second'];
    const second: Timeframe = typeof rawSecond === 'string' && isTimeframe(rawSecond) ? rawSecond : 'D';
    const lastStart = series.bars[series.bars.length - 1]![0];
    const plots: Plot[] = [];
    // One frame, or two with the dual mode on (T-0044): each at its own offset, oldest first, so a line drawn over another is the newer one.
    for (const frame of framePlan(tf, params['dual'] === true, offset, second)) {
      const groups = aggregate(series.bars, frame.tf).slice(-count);
      if (!groups.length) continue;
      groups.forEach((group, index) => {
        const position = frame.offset + (index + 1) * 3;
        const t0 = lastStart + position * chartMs, t1 = t0 + 2 * chartMs, center = t0 + chartMs;
        const color = group.close > group.open ? bull : bear;
        if (style === 'candle') {
          plots.push({ kind: 'line', points: [{ t: center, p: group.high }, { t: center, p: group.low }], style: { width: 1, color: wick } });
          plots.push({ kind: 'box', t0, t1, p0: Math.min(group.open, group.close), p1: Math.max(group.open, group.close), color });
          return;
        }
        // OHLC: the high-low bar with the open and the close ticked either side and named, as `drawDC_tf_1` does with box borders and 'A'/'C'.
        const half = chartMs * 0.4;
        plots.push({ kind: 'line', points: [{ t: center, p: group.high }, { t: center, p: group.low }], style: { width: 1, color } });
        plots.push({ kind: 'line', points: [{ t: center - half, p: group.open }, { t: center + half, p: group.open }], style: { width: 1, color } });
        plots.push({ kind: 'line', points: [{ t: center - half, p: group.close }, { t: center + half, p: group.close }], style: { width: 1, color } });
        plots.push({ kind: 'label', t: center + half, p: group.open, text: 'O', color });
        plots.push({ kind: 'label', t: center + half, p: group.close, text: 'C', color });
      });
      if (label) {
        const oldest = groups[0]!;
        plots.push({ kind: 'label', t: lastStart + (frame.offset + 3) * chartMs, p: oldest.high, text: TIMEFRAME_NAMES[frame.tf], color: wick });
      }
    }
    return plots.length ? { plots } : null;
  },
};
