/**
 * What one study's `compute()` did, as a row the console and the layers panel can read: it drew (and how many plots), it returned nothing,
 * it asked for data the page could not resolve, or it threw. Pure — no DOM, no time, no store — so `tests/studies-host.test.mts` holds it to
 * one row per study and cause.
 */
import type { StudyOutput } from '../../engine/studies/contract.ts';

/** Why a study did not draw. */
export type StudyMiss = 'noData' | 'null' | 'error';
export interface StudyResult {
  readonly id: string;
  readonly name: string;
  /** How many plots it returned: 0 when it did not draw. */
  readonly plots: number;
  readonly miss: StudyMiss | null;
  /** The `DataReq` keys it could not resolve, or the message of a thrown error. */
  readonly data?: string;
  readonly error?: string;
}

/** The outcome of one study from what its compute did; an output with no plots is nothing, never a drawing of zero. */
export function studyOutcome(id: string, name: string, result: { output: StudyOutput | null; error?: unknown; missing?: readonly string[] }): StudyResult {
  if (result.error !== undefined && result.error !== null) {
    return { id, name, plots: 0, miss: 'error', error: result.error instanceof Error ? result.error.message : String(result.error) };
  }
  const plots = result.output ? result.output.plots.length : 0;
  if (plots > 0) return { id, name, plots, miss: null };
  const missing = result.missing ?? [];
  if (missing.length) return { id, name, plots: 0, miss: 'noData', data: missing.join(', ') };
  return { id, name, plots: 0, miss: 'null' };
}
