/**
 * `range-pressure`: the "HEATMAP" of KENJI, ported to the study contract. It is **not** a heatmap and knows nothing about depth: it is a
 * multi-window stochastic that colours the candles.
 *
 * For each bar, for `i` = 1..`plotNumber` a window of `i * inc` bars gives one stochastic — `(close - ll) / (hh - ll) * 100`, `hh`/`ll` the
 * window's high and low, 50 when the window is flat — smoothed by an EMA whose length is `smooth` (or `smooth + i` with Waves on) and kept
 * per window between bars; the bar's value is the mean of the `plotNumber` smoothed values. The state is the one `getColour` reads:
 * ≥80 overbought, ≥70 pre-overbought, ≤20 oversold, ≤30 pre-sold, else neutral.
 *
 * Pine: `KENJI` `getColour` (`:776-786`), the loop (`:790-830`) and the inputs (`:766-769`). The barcolor call (`:2781`) is presentation:
 * whether a candle is painted only on the extremes is the renderer's decision, so this piece returns the value and the state of every bar
 * and a `bgcolor` over the bar's slot for the painter; it never paints.
 */
import type { InputSpec, InputValues } from '../engine/inputs/schema.ts';
import { readInputs } from '../engine/inputs/schema.ts';
import type { Plot, StudyDef, StudyOutput } from '../engine/studies/contract.ts';
import type { Bar } from '../engine/series/source.ts';

/** A number input as the Pine falls back when the value is not one. */
const num = (values: InputValues, id: string, fallback: number): number => { const v = values[id]; return typeof v === 'number' && Number.isFinite(v) ? v : fallback; };
/** A boolean input. */
const bool = (values: InputValues, id: string, fallback: boolean): boolean => { const v = values[id]; return typeof v === 'boolean' ? v : fallback; };

/** The colour a state has in the palette of the study, as the Pine's four colours and grey. */
export type RangePressureState = 'overbought' | 'preOverbought' | 'neutral' | 'preSold' | 'oversold';
export interface RangePressureRow { readonly value: number; readonly state: RangePressureState }

export const INPUTS: readonly InputSpec[] = [
  { id: 'inc', kind: 'int', name: 'Increment', default: 10, min: 1, max: 20, group: 'Range pressure' },
  { id: 'smooth', kind: 'int', name: 'Smooth', default: 2, min: 1, max: 10, group: 'Range pressure' },
  { id: 'plotNumber', kind: 'int', name: 'Windows', default: 21, min: 1, max: 28, group: 'Range pressure' },
  // Waves: each window's EMA is one bar longer than the one before it (`smooth + i`), as `IncType` in the Pine (`:769`, `:802`).
  { id: 'waves', kind: 'bool', name: 'Waves', default: false, group: 'Range pressure' },
];

/** The state of one value, by the Pine's thresholds (`getColour`, `:776-786`); a value exactly on a threshold takes the stricter state. */
export function stateOf(value: number): RangePressureState {
  if (value >= 80) return 'overbought';
  if (value >= 70) return 'preOverbought';
  if (value <= 20) return 'oversold';
  if (value <= 30) return 'preSold';
  return 'neutral';
}

/** The colour each state is painted with, from the four Pine inputs (`pre_bull` #179cef, `final_bull` #02269e, `pre_bear` #b96f02, `final_bear` #cf0000). */
export const COLOURS: Readonly<Record<RangePressureState, string>> = {
  overbought: '#cf0000', preOverbought: '#b96f02', neutral: 'rgba(128,128,128,0)', preSold: '#179cef', oversold: '#02269e',
};

/**
 * The value and the state of every bar, in the bars' order. The EMAs are kept per window as the Pine keeps them in `emaHist`, so the result
 * for a bar depends on the bars before it and on nothing else. Pure: no canvas, no store, no network.
 */
export function rangePressure(bars: readonly Bar[], values: InputValues): RangePressureRow[] {
  const inc = Math.max(1, Math.round(num(values, 'inc', 10))), smooth = Math.max(1, Math.round(num(values, 'smooth', 2)));
  const windows = Math.min(28, Math.max(1, Math.round(num(values, 'plotNumber', 21)))), waves = bool(values, 'waves', false);
  const ema = new Array<number | null>(windows + 1).fill(null), out: RangePressureRow[] = [];
  for (let n = 0; n < bars.length; n++) {
    let sum = 0;
    for (let i = 1; i <= windows; i++) {
      const c = i * inc;
      // The Pine sets `hh = high` and then loops `for k = 0 to c - 1` over `high[k]`/`low[k]` (inclusive), so the window is this bar
      // plus the c - 1 before it: the current bar is already in hh/ll, so the loop starts at the bar before it.
      let hh = bars[n]![2]!, ll = bars[n]![3]!;
      for (let k = 1; k < c; k++) {
        const bar = bars[n - k];
        if (!bar) continue;
        hh = Math.max(hh, bar[2]!); ll = Math.min(ll, bar[3]!);
      }
      const close = bars[n]![4]!;
      const stoch = hh !== ll ? (close - ll) / (hh - ll) * 100 : 50;
      const alpha = 2 / ((waves ? smooth + i : smooth) + 1), previous = ema[i];
      const next = previous === null || previous === undefined ? stoch : stoch * alpha + previous * (1 - alpha);
      ema[i] = next;
      sum += next;
    }
    const value = sum / windows;
    out.push({ value, state: stateOf(value) });
  }
  return out;
}

/** The bars of the view, as the painter's `bgcolor`: a band over each bar's slot in the state's colour, and none where it is neutral. */
function plotsOf(bars: readonly Bar[], barMs: number, rows: readonly RangePressureRow[]): Plot[] {
  const plots: Plot[] = [];
  for (let i = 0; i < bars.length; i++) {
    const row = rows[i], bar = bars[i];
    if (!row || !bar || row.state === 'neutral') continue;
    plots.push({ kind: 'bgcolor', t0: bar[0]!, t1: bar[0]! + barMs, color: COLOURS[row.state], alpha: 0.18 });
  }
  return plots;
}

/** The inputs of the piece, as the registry reads them. */
export const RANGE_PRESSURE: StudyDef = {
  api: 1,
  id: 'range-pressure',
  name: 'Range pressure',
  inputs: INPUTS,
  data: [{ key: 'chart', kind: 'candles', label: 'Chart candles' }],
  compute(ctx) {
    const series = ctx.data.candles('chart');
    if (!series || series.bars.length < 2) return null;
    const bars = series.bars, barMs = bars.length > 1 ? Math.abs(bars[1]![0]! - bars[0]![0]!) : ctx.zoneBarMs;
    const rows = rangePressure(bars, readInputs(INPUTS, ctx.params)), plots = plotsOf(bars, barMs, rows);
    if (!plots.length) return null;
    // What a panel may read (D-31). One row, not one a bar: `plotsOf` already carries a bar's state as its colour, and a row per bar would
    // double the frame's objects for the same numbers. The last completed bar is what a panel shows; a per-bar readout would need a typed
    // array in the contract and a measurement, not a copy of the plots.
    const last = rows[rows.length - 1];
    const counts = rows.reduce<Record<string, number>>((tally, row) => {
      tally[row.state] = (tally[row.state] ?? 0) + 1;
      return tally;
    }, {});
    const readout = [
      {
        id: 'rp:last',
        label: 'last bar',
        values: last ? [{ id: 'state', value: last.state }, { id: 'value', value: last.value }] : [],
      },
      { id: 'rp:window', label: 'window', values: Object.entries(counts).map(([state, count]) => ({ id: state, value: count })) },
    ];
    return { plots, readout } as StudyOutput;
  },
};
