const TIMEFRAME_NAMES: Readonly<Record<string, string>> = { '1m': t('1-minute'), '5m': t('5-minute'), '15m': t('15-minute'), '30m': t('30-minute'), '1h': t('1-hour'), '4h': t('4-hour'), '1d': t('Daily'), '1w': t('Weekly'), '1M': t('Monthly') };
/** How a timeframe is written in its list: the exchange's day, week and month candles as D, W and M (Karl, 2026-10-22), the rest by their size. */
