/**
 * One switch per study: whether the map draws it. A study the save does not name draws, so a page or a layout from before the switches
 * existed turns nothing off, and a study added later is on until someone turns it off.
 */
export type StudySwitches = Readonly<Record<string, boolean>>;

/** The switches a save or a layout holds: only `id: boolean` entries with a usable id, anything else dropped (the file can come from anywhere). */
export function readStudySwitches(saved: unknown): StudySwitches {
  if (!saved || typeof saved !== 'object' || Array.isArray(saved)) return {};
  const out: Record<string, boolean> = {};
  for (const [id, value] of Object.entries(saved as Record<string, unknown>)) {
    if (typeof value !== 'boolean' || !id || id.length > 80) continue;
    out[id] = value;
  }
  return out;
}

/** Whether a study is on: off only when its switch says so. */
export function studyOn(switches: StudySwitches, id: string): boolean { return switches[id] !== false; }

/** One study turned on or off, the rest untouched. */
export function setStudy(switches: StudySwitches, id: string, on: boolean): StudySwitches { return { ...switches, [id]: on }; }
