import type { InputSpec, InputValues } from '../inputs/schema.ts';
import type { Bar } from '../series/source.ts';
import type { SumRow } from '../../shared/print-sums.ts';

/**
 * The study contract, versioned from the first day (`api: 1`): a third-party study will be written against this, so a change that a
 * study could notice bumps `api`. A study is a pure function of its inputs and the data the host hands it:
 *
 * - it declares `data: DataReq[]` (what it will ask for) and receives the resolved series through `StudyData`; it imports no hub, no
 *   store and no fetch;
 * - `compute` reads nothing but `ctx` (view, now, zone, coin, windows, anchors, palette, data) and returns what to draw;
 * - the painter (`draw/painter.ts`) turns that into canvas calls, so no study knows a canvas.
 *
 * The forms `Plot` admits are the ones the card lists (line, polyline, box, label, bgcolor, plot) plus the two its note fixes: a grid of
 * values (concentration per cell, per price row and per time) and a mark with a label at one level (a sweep, a level taken), not a
 * continuous line.
 */
export const STUDY_API = 1 as const;

export interface DataReq {
  readonly key: string;
  readonly kind: 'candles' | 'sums';
  /** What a panel says it reads, English as the key of a translation. */
  readonly label: string;
}

/** Candles a host resolved, and how far the history behind them reaches. */
export interface StudyCandles {
  readonly bars: readonly Bar[];
  /** Where the history begins (ms): a line whose start is earlier has no true average and is not drawn. */
  readonly heldFrom: number;
  /** Where the chart's own candles take over from the history; Infinity when they do not. */
  readonly liveFrom: number;
}

/** Large-order sums a host resolved, and where the recording's count begins (null: not known). */
export interface StudySums { readonly rows: readonly SumRow[]; readonly since: number | null }

/** What the host resolved for this frame. A key the host has not answered yet is null: the study draws what it can. */
export interface StudyData {
  candles(key: string): StudyCandles | null;
  sums(key: string): StudySums | null;
}

export interface Bounds { readonly t0: number; readonly t1: number; readonly p0: number; readonly p1: number }

/** One live period touching the view (a session of the study's period, in the chart's zone). */
export interface StudyWindow { readonly from: number; readonly to: number; readonly key: string }

/** The colours a study may ask for: a palette's, reduced to what a drawing needs. */
export interface StudyPalette {
  readonly dark: boolean;
  readonly vwap: string;
  readonly bid: string;
  readonly ask: string;
  readonly panel: string;
}

export interface StudyContext {
  readonly params: InputValues;
  readonly data: StudyData;
  readonly view: Bounds;
  readonly now: number;
  readonly zone: string;
  readonly coin: string;
  /** The live periods touching the view, host-resolved (sessions of the input's period, in `zone`). */
  readonly windows: readonly StudyWindow[];
  /** The moments the person anchored, host-resolved for the coin on screen (ms, oldest first). */
  readonly anchors: readonly number[];
  /** A bar size that starts a bar on every period boundary of `zone` (a quarter hour in Nepal). */
  readonly zoneBarMs: number;
  /** The moment a replay shows, or null when the chart follows the market. */
  readonly replayAt: number | null;
  readonly palette: StudyPalette;
}

export interface Point { readonly t: number; readonly p: number }

export interface LineStyle {
  readonly color?: string;
  readonly width?: number;
  readonly dash?: readonly number[];
  readonly alpha?: number;
  /** A darker (or lighter) stroke behind the line, so it reads over the heatmap. */
  readonly halo?: boolean;
}

export interface GridCell { readonly t0: number; readonly t1: number; readonly p0: number; readonly p1: number; readonly value: number }

export type Plot =
  | { readonly kind: 'line'; readonly points: readonly Point[]; readonly style?: LineStyle }
  | { readonly kind: 'polyline'; readonly loops: readonly (readonly Point[])[]; readonly style?: LineStyle }
  | { readonly kind: 'box'; readonly t0: number; readonly t1: number; readonly p0: number; readonly p1: number; readonly color?: string; readonly width?: number; readonly alpha?: number }
  | { readonly kind: 'label'; readonly t: number; readonly p: number; readonly text: string; readonly color?: string }
  | { readonly kind: 'bgcolor'; readonly t0: number; readonly t1: number; readonly p0?: number; readonly p1?: number; readonly color: string; readonly alpha?: number }
  | { readonly kind: 'plot'; readonly points: readonly Point[]; readonly style?: LineStyle; readonly fillTo?: number }
  | { readonly kind: 'grid'; readonly cells: readonly GridCell[]; readonly color?: string }
  | { readonly kind: 'mark'; readonly t: number; readonly p: number; readonly text?: string; readonly color?: string; readonly shape?: 'triangle' | 'dot' };

/** A name for the price axis, placed with the key levels' and the Volume profile's: earlier on the axis wins the room. */
export interface AxisTag { readonly key: string; readonly price: number; readonly text: string; readonly rank: number; readonly color?: string }

/** A name at the right end of a line that runs to now, at its last point. */
export interface OutputLabel { readonly text: string; readonly price: number; readonly t: number; readonly rank: number; readonly color?: string }

/** A named value a panel reads: a code or a number, never a sentence (the panel translates the code). */
export interface ReadoutValue { readonly id: string; readonly value: number | string | boolean }

/**
 * One line of a readout: a thing (a plan, a bar) and its named values. `id` and the values are **codes**: the visible words are the
 * app's (`t()` and the packs), so a piece never ships prose. The painter ignores every row here; a panel reads them, so the panel and the
 * chart cannot say different things and the calculation is not paid twice (D-31).
 */
export interface ReadoutRow { readonly id: string; readonly label: string; readonly values: readonly ReadoutValue[] }

export interface StudyOutput {
  readonly plots: readonly Plot[];
  readonly labels?: readonly OutputLabel[];
  readonly tags?: readonly AxisTag[];
  /** Numbers a panel reads (D-31). Optional: a study without it draws exactly as before. */
  readonly readout?: readonly ReadoutRow[];
}

export interface StudyDef {
  readonly api: typeof STUDY_API;
  readonly id: string;
  readonly name: string;
  readonly inputs: readonly InputSpec[];
  readonly data: readonly DataReq[];
  compute(ctx: StudyContext): StudyOutput | null;
}
