import type { AxisTag, GridCell, LineStyle, OutputLabel, Point, StudyOutput } from '../studies/contract.ts';
import type { Scope } from './scope.ts';

/**
 * Draws what studies return. The canvas calls are the ones the VWAP made before the migration (halo then colour, the names at the right
 * end claimed on the shared board), so a migrated study keeps the same pixels: same API calls, in the same order.
 */

/** The points inside [t0, t1] and the one just outside each end, so a line runs to the chart's edges. `points` sorted by time. */
export function visiblePoints<T extends { readonly t: number }>(points: readonly T[], t0: number, t1: number): readonly T[] {
  let a = 0, b = points.length;
  while (a < b) { const m = (a + b) >> 1; if (points[m]!.t < t0) a = m + 1; else b = m; }
  let c = a, d = points.length;
  while (c < d) { const m = (c + d) >> 1; if (points[m]!.t <= t1) c = m + 1; else d = m; }
  return points.slice(Math.max(0, a - 1), Math.min(points.length, c + 1));
}

function strokePath(ctx: CanvasRenderingContext2D, points: readonly Point[], scope: Scope, style: LineStyle): void {
  const { view, width, height, palette } = scope;
  const halo = palette.dark ? 'rgba(0,0,0,0.55)' : 'rgba(255,255,255,0.75)';
  const dash = style.dash ?? [];
  ctx.globalAlpha = style.alpha ?? 1;
  ctx.setLineDash([...dash]);
  ctx.beginPath();
  let started = false;
  for (const point of points) {
    const x = view.t0 === view.t1 ? 0 : (point.t - view.t0) / (view.t1 - view.t0) * width;
    const y = (1 - (point.p - view.p0) / (view.p1 - view.p0)) * height;
    if (!started) { ctx.moveTo(x, y); started = true; } else ctx.lineTo(x, y);
  }
  const lineWidth = style.width ?? 1;
  if (style.halo !== false) { ctx.strokeStyle = halo; ctx.lineWidth = lineWidth + 2; ctx.stroke(); }
  ctx.strokeStyle = style.color ?? palette.vwap;
  ctx.lineWidth = lineWidth;
  ctx.stroke();
}

function drawGrid(ctx: CanvasRenderingContext2D, cells: readonly GridCell[], scope: Scope, color: string | undefined): void {
  let peak = 0;
  for (const cell of cells) peak = Math.max(peak, Math.abs(cell.value));
  if (!(peak > 0)) return;
  const { view, width, height } = scope;
  const x = (t: number): number => (view.t1 === view.t0 ? 0 : (t - view.t0) / (view.t1 - view.t0) * width);
  const y = (p: number): number => (1 - (p - view.p0) / (view.p1 - view.p0)) * height;
  for (const cell of cells) {
    const x0 = x(cell.t0), x1 = x(cell.t1), y0 = y(cell.p1), y1 = y(cell.p0);
    if (!(x1 > x0) || !(y1 > y0)) continue;
    const share = Math.abs(cell.value) / peak;
    ctx.globalAlpha = 0.08 + 0.72 * share;
    ctx.fillStyle = color ?? scope.palette.vwap;
    ctx.fillRect(x0, y0, x1 - x0, y1 - y0);
  }
  ctx.globalAlpha = 1;
}

function drawMark(ctx: CanvasRenderingContext2D, t: number, p: number, scope: Scope, color: string | undefined, shape: 'triangle' | 'dot', text: string | undefined): void {
  const { view, width, height, palette } = scope;
  const halo = palette.dark ? 'rgba(0,0,0,0.55)' : 'rgba(255,255,255,0.75)';
  const x = (t - view.t0) / (view.t1 - view.t0) * width;
  const y = (1 - (p - view.p0) / (view.p1 - view.p0)) * height;
  const tone = color ?? palette.vwap;
  ctx.globalAlpha = 1;
  if (shape === 'triangle') {
    const foot = y + 7;
    ctx.setLineDash([]); ctx.beginPath(); ctx.moveTo(x, foot - 5); ctx.lineTo(x + 5, foot + 4); ctx.lineTo(x - 5, foot + 4); ctx.closePath();
    ctx.fillStyle = tone; ctx.fill(); ctx.strokeStyle = halo; ctx.lineWidth = 1; ctx.stroke();
  } else {
    ctx.beginPath(); ctx.arc(x, y, 2.5, 0, Math.PI * 2); ctx.fillStyle = tone; ctx.fill(); ctx.strokeStyle = halo; ctx.lineWidth = 1; ctx.stroke();
  }
  if (text) {
    ctx.font = '600 10px ui-sans-serif, system-ui, sans-serif'; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    ctx.fillStyle = tone; ctx.fillText(text, x + 8, y - 8);
  }
}

function drawPlot(ctx: CanvasRenderingContext2D, plot: StudyOutput['plots'][number], scope: Scope): void {
  const { view, width, height, palette } = scope;
  const y = (p: number): number => (1 - (p - view.p0) / (view.p1 - view.p0)) * height;
  const x = (t: number): number => (view.t1 === view.t0 ? 0 : (t - view.t0) / (view.t1 - view.t0) * width);
  switch (plot.kind) {
    case 'line':
    case 'plot': {
      const points = visiblePoints(plot.points, view.t0, view.t1);
      if (points.length < 1) return;
      strokePath(ctx, points, scope, plot.style ?? {});
      return;
    }
    case 'polyline':
      for (const loop of plot.loops) { const points = visiblePoints(loop, view.t0, view.t1); if (points.length > 1) strokePath(ctx, points, scope, plot.style ?? {}); }
      return;
    case 'box': {
      const x0 = x(plot.t0), x1 = x(plot.t1), y0 = y(plot.p1), y1 = y(plot.p0);
      ctx.globalAlpha = plot.alpha ?? 1;
      if (plot.color) { ctx.fillStyle = plot.color; ctx.fillRect(x0, y0, x1 - x0, y1 - y0); }
      ctx.strokeStyle = plot.color ?? palette.vwap; ctx.lineWidth = plot.width ?? 1; ctx.setLineDash([]);
      ctx.strokeRect(x0, y0, x1 - x0, y1 - y0);
      ctx.globalAlpha = 1;
      return;
    }
    case 'label':
      ctx.globalAlpha = 1; ctx.setLineDash([]);
      ctx.fillStyle = plot.color ?? palette.vwap; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
      ctx.fillText(plot.text, x(plot.t), y(plot.p) - 8);
      return;
    case 'bgcolor':
      ctx.globalAlpha = plot.alpha ?? 0.2; ctx.fillStyle = plot.color;
      ctx.fillRect(x(plot.t0), y(plot.p1 ?? view.p1), x(plot.t1) - x(plot.t0), y(plot.p0 ?? view.p0) - y(plot.p1 ?? view.p1));
      ctx.globalAlpha = 1;
      return;
    case 'grid':
      drawGrid(ctx, plot.cells, scope, plot.color);
      return;
    case 'mark':
      drawMark(ctx, plot.t, plot.p, scope, plot.color, plot.shape ?? 'triangle', plot.text);
      return;
  }
}

/**
 * Paints each study's output (one canvas, clipped to the plot), the labels at the right end last and clear of one another, and returns the
 * price-axis tags the host places with the key levels' and the Volume profile's.
 */
export function paintStudies(ctx: CanvasRenderingContext2D, outputs: readonly StudyOutput[], scope: Scope): AxisTag[] {
  const tags: AxisTag[] = [];
  for (const output of outputs) {
    const labels = output.labels ?? [];
    if (!output.plots.length && !labels.length && !(output.tags ?? []).length) continue;
    ctx.save(); ctx.beginPath(); ctx.rect(0, 0, scope.width, scope.height); ctx.clip(); ctx.lineJoin = 'round';
    for (const plot of output.plots) drawPlot(ctx, plot, scope);
    ctx.setLineDash([]); ctx.globalAlpha = 1;
    // The names at the right edge, the first rank first; one that would cover another is left out (the shared board's rule).
    ctx.font = '600 10px ui-sans-serif, system-ui, sans-serif'; ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
    for (const label of [...labels].sort((a, b) => a.rank - b.rank)) {
      const y = (1 - (label.price - scope.view.p0) / (scope.view.p1 - scope.view.p0)) * scope.height;
      const left = (label.t - scope.view.t0) / (scope.view.t1 - scope.view.t0) * scope.width;
      if (!(left <= scope.width + 4 && left > 40)) continue;
      const textWidth = ctx.measureText(label.text).width + 8;
      if (y < 7 || y > scope.height - 7 || !scope.board.claim({ x0: scope.width - 2 - textWidth, x1: scope.width - 2, y0: y - 7, y1: y + 7 })) continue;
      ctx.globalAlpha = 0.85; ctx.fillStyle = scope.palette.panel; ctx.fillRect(scope.width - 2 - textWidth, y - 7, textWidth, 14);
      ctx.globalAlpha = 1; ctx.fillStyle = label.color ?? scope.palette.vwap; ctx.fillText(label.text, scope.width - 6, y);
    }
    ctx.restore();
    for (const tag of output.tags ?? []) tags.push(tag);
  }
  return tags;
}

export type { OutputLabel };
