import { isTimeframe, type Timeframe } from '../time/timeframe.ts';

/**
 * A study's inputs, declared once and validated at the edge: a layout or a third-party study's saved values are data from outside, so
 * every value is checked against its declaration (kind, limits, options) before `compute` sees it. Pure: no DOM, no clock.
 */
export type InputValue = boolean | number | string;
export type InputValues = Readonly<Record<string, InputValue>>;

interface BaseInput {
  readonly id: string;
  /** What a panel shows, English as the key of a translation. */
  readonly name: string;
  /** The panel section it belongs to (Pine's `group`). */
  readonly group?: string;
}

export interface BoolInput extends BaseInput { readonly kind: 'bool'; readonly default: boolean }
export interface IntInput extends BaseInput {
  readonly kind: 'int';
  readonly default: number;
  readonly min: number;
  readonly max: number;
  readonly step?: number;
}
export interface FloatInput extends BaseInput {
  readonly kind: 'float';
  readonly default: number;
  readonly min: number;
  readonly max: number;
  readonly step?: number;
  readonly precision?: number;
}
export interface StringInput extends BaseInput {
  readonly kind: 'string';
  readonly default: string;
  readonly options?: readonly string[];
}
export interface ColorInput extends BaseInput {
  readonly kind: 'color';
  readonly default: string;
  readonly options?: readonly string[];
}
export interface TimeframeInput extends BaseInput { readonly kind: 'tf'; readonly default: Timeframe }
export interface SourceInput extends BaseInput {
  readonly kind: 'source';
  readonly default: string;
  readonly options: readonly string[];
}

export type InputSpec = BoolInput | IntInput | FloatInput | StringInput | ColorInput | TimeframeInput | SourceInput;

const MAX_TEXT = 120;

/** Every input at its default: what a study computes with before anyone touches its panel. */
export function defaultInputs(specs: readonly InputSpec[]): InputValues {
  const out: Record<string, InputValue> = {};
  for (const spec of specs) out[spec.id] = spec.default;
  return out;
}

const inOptions = (value: string, options: readonly string[] | undefined): boolean => options === undefined || options.includes(value);

function readOne(spec: InputSpec, value: unknown): InputValue {
  switch (spec.kind) {
    case 'bool': return typeof value === 'boolean' ? value : spec.default;
    case 'int': {
      if (typeof value !== 'number' || !Number.isFinite(value)) return spec.default;
      return Math.max(spec.min, Math.min(spec.max, Math.round(value)));
    }
    case 'float': {
      if (typeof value !== 'number' || !Number.isFinite(value)) return spec.default;
      const clamped = Math.max(spec.min, Math.min(spec.max, value));
      return spec.precision === undefined ? clamped : Number(clamped.toFixed(spec.precision));
    }
    case 'string':
      return typeof value === 'string' && value.length > 0 && value.length <= MAX_TEXT && inOptions(value, spec.options) ? value : spec.default;
    case 'color':
      return typeof value === 'string' && value.length > 0 && value.length <= MAX_TEXT && inOptions(value, spec.options) ? value : spec.default;
    case 'tf':
      return typeof value === 'string' && isTimeframe(value) ? value : spec.default;
    case 'source':
      return typeof value === 'string' && inOptions(value, spec.options) ? value : spec.default;
  }
}

/** The saved values read against their declarations: an unknown or invalid value falls back to its default, and unknown ids are dropped. */
export function readInputs(specs: readonly InputSpec[], saved: unknown): InputValues {
  const source = typeof saved === 'object' && saved !== null && !Array.isArray(saved) ? saved as Record<string, unknown> : {};
  const out: Record<string, InputValue> = {};
  for (const spec of specs) out[spec.id] = readOne(spec, Object.hasOwn(source, spec.id) ? source[spec.id] : undefined);
  return out;
}
