/**
 * A piece's own settings panel (T-0045): the switch first, then every input the piece declares, built from its `InputSpec`s. A piece that
 * adds an input shows it without touching this file. The values live in `state.studyParams[id]` and travel in the page's save and in a
 * layout; `readInputs` checks them against the declaration before `compute` sees them, so a file from outside cannot put anything else in.
 */
import { el } from '../dom.ts';
import type { Store } from '../store.ts';
import { t } from '../i18n.ts';
import { heading, note, rangeRow, selectRow, switchRow } from '../ui.ts';
import { setStudy, studyOn } from './switches.ts';
import { setStudyOpacity, studyAlpha } from './opacity.ts';
import { studyLabel } from './labels.ts';
import { TIMEFRAMES } from '../hub.ts';
import type { InputSpec, InputValue, InputValues } from '../../engine/inputs/schema.ts';
import type { StudyDef } from '../../engine/studies/contract.ts';

/**
 * An input's name or group in the page's language. Every literal is a `t()` of its own (T-0045, review): the packs check that a page only
 * asks for words it uses, and a dynamic key would slip past that check untranslated. A piece from outside the build keeps its own words.
 */
function inputWords(raw: string): string {
  // Composed names (T-0050): a piece names `Asia A label` or `PD high` by joining its own code with what the switch does. The code stays
  // (it is the piece's, and the Pine's), and the part that describes the setting is translated, so no panel is half in English.
  // A previous period (`Prev. Day`, `Prev. 1H`): the code stays and the word that says it is the period before is translated.
  const previous = /^Prev\. (.+)$/.exec(raw);
  if (previous) return t('{name} previous', { name: previous[1]! });
  // A 90-minute-cycle session is its zone and its letter (`Asia A`, `NY PM M`): the zone is translated, the letter is the Pine's.
  const session = /^(Asia|London|NY AM|NY PM) ([AMDX])$/.exec(raw);
  if (session) return `${inputWords(session[1]!)} ${session[2]!}`;
  const composed = /^(.*) (label|colour|high|low|close)$/.exec(raw);
  if (composed) {
    const base = composed[1]!, what = composed[2]!;
    switch (what) {
      case 'label': return t('{name} label', { name: base });
      case 'colour': return t('{name} colour', { name: base });
      case 'high': return t('{name} high', { name: base });
      case 'low': return t('{name} low', { name: base });
      case 'close': return t('{name} close', { name: base });
    }
  }
  switch (raw) {
    case 'Anchor': return t('Anchor');
    case 'Extend': return t('Extend');
    case 'Last': return t('Last');
    case 'Mitigation': return t('Mitigation');
    case 'Mode': return t('Mode');
    case 'Two frames': return t('Two frames');
    case 'Second timeframe': return t('Second timeframe');
    case 'Inputs': return t('Inputs');
    case 'Length': return t('Length');
    case 'Asia': return t('Asia');
    case 'London': return t('London');
    case 'NY AM': return t('NY AM');
    case 'NY PM': return t('NY PM');
    case '50% (not drawn by the Pine)': return t('50% (not drawn by the Pine)');
    case '90 min cycle': return t('90 min cycle');
    case 'Auto: top %': return t('Auto: top %');
    case 'Bands': return t('Bands');
    case 'Bearish': return t('Bearish');
    case 'Bearish zones': return t('Bearish zones');
    case 'Bins over the candle of': return t('Bins over the candle of');
    case 'Bookmap': return t('Bookmap');
    case 'Bookmap trigger': return t('Bookmap trigger');
    case 'Border': return t('Border');
    case 'Bullish': return t('Bullish');
    case 'Bullish zones': return t('Bullish zones');
    case 'Candles': return t('Candles');
    case 'Colours': return t('Colours');
    case 'Fill transparency': return t('Fill transparency');
    case 'Higher-timeframe candles': return t('Higher-timeframe candles');
    case 'Increment': return t('Increment');
    case 'Label': return t('Label');
    case 'Labels': return t('Labels');
    case 'Levels': return t('Levels');
    case 'Manual: delta threshold': return t('Manual: delta threshold');
    case 'Min volume %': return t('Min volume %');
    case 'Offset': return t('Offset');
    case 'Open (not drawn by the Pine)': return t('Open (not drawn by the Pine)');
    case 'Periods': return t('Periods');
    case 'Previous OHLC': return t('Previous OHLC');
    case 'Price bins': return t('Price bins');
    case 'Follow the chart timeframe': return t('Follow the chart timeframe');
    case 'Actual (forming candle)': return t('Actual (forming candle)');
    case 'Actual timeframe': return t('Actual timeframe');
    case 'Orderflow': return t('Orderflow');
    case 'Chart bias (closed candles)': return t('Chart bias (closed candles)');
    case 'Display': return t('Display');
    case 'Position': return t('Position');
    case 'Countdown': return t('Countdown');
    case 'Trend continuation': return t('Trend continuation');
    case 'Price bins (bookmap)': return t('Price bins (bookmap)');
    case 'Price in the label': return t('Price in the label');
    case 'Price-axis tags': return t('Price-axis tags');
    case 'Range in the label': return t('Range in the label');
    case 'Range pressure': return t('Range pressure');
    case 'Reverse zone': return t('Reverse zone');
    case 'ST entry': return t('ST entry');
    case 'ST entry (trade plan)': return t('ST entry (trade plan)');
    case 'Session': return t('Session');
    case 'Session VWAP': return t('Session VWAP');
    case 'Singularity': return t('Singularity');
    case 'Smooth': return t('Smooth');
    case 'Style': return t('Style');
    case 'Threshold mode': return t('Threshold mode');
    case 'Timeframe': return t('Timeframe');
    case 'Timeframe candles': return t('Timeframe candles');
    case 'Timeframe label': return t('Timeframe label');
    case 'Trade plan': return t('Trade plan');
    case 'Type': return t('Type');
    case 'VWAP': return t('VWAP');
    case 'Waves': return t('Waves');
    case 'Whale VWAP': return t('Whale VWAP');
    case 'Whale size (USD)': return t('Whale size (USD)');
    case 'Wick': return t('Wick');
    case 'Width': return t('Width');
    case 'Windows': return t('Windows');
    case 'asia': return t('asia');
    case 'london': return t('london');
    case 'nyam': return t('nyam');
    case 'nypm': return t('nypm');
    default: return raw;
  }
}

/** One input's value: what the person saved, else the piece's default. */
export function studyInputValue(study: StudyDef, values: InputValues | undefined, input: InputSpec): InputValue {
  const held = values?.[input.id];
  if (held !== undefined && typeof held === typeof input.default) return held;
  return input.default;
}

/** A value written into the state, by study and input: the one way the panel changes anything. */
export function setStudyParam(store: Store, id: string, key: string, value: InputValue): void {
  const now = store.state.studyParams[id] ?? {};
  store.set({ studyParams: { ...store.state.studyParams, [id]: { ...now, [key]: value } } });
}

/** A free string: the one kind with no list and no numbers (a title, a label); validated again by `readInputs`. */
function textRow(name: string, what: string, value: string, onChange: (value: string) => void): HTMLElement {
  const box = el('input', { type: 'text', value });
  box.onchange = () => onChange(box.value);
  return el('label', { class: 'field', tip: what }, el('span', { class: 'label' }, el('span', { class: 'name', textContent: name }), el('span', { class: 'desc', textContent: what })), box);
}

/** A colour: the browser's own picker, so no palette has to be invented for a piece. */
function colorRow(name: string, what: string, value: string, onChange: (value: string) => void): HTMLElement {
  const box = el('input', { type: 'color', value });
  box.oninput = () => onChange(box.value);
  return el('label', { class: 'field', tip: what }, el('span', { class: 'label' }, el('span', { class: 'name', textContent: name }), el('span', { class: 'desc', textContent: what })), box);
}

/** The row a declaration asks for; `null` for a kind this build does not know, said in the panel instead of guessing a control. */
function inputRow(study: StudyDef, input: InputSpec, value: InputValue, set: (value: InputValue) => void): HTMLElement | null {
  const name = inputWords(input.name), what = input.group ? inputWords(input.group) : '';
  switch (input.kind) {
    case 'bool': return switchRow(name, what, value === true, on => set(on));
    case 'int': return rangeRow(name, what, { min: input.min, max: input.max, step: input.step ?? 1, value: typeof value === 'number' ? value : input.default, format: v => String(Math.round(v)) }, v => set(Math.round(v)));
    case 'float': return rangeRow(name, what, { min: input.min, max: input.max, step: input.step ?? (input.max - input.min) / 100, value: typeof value === 'number' ? value : input.default, format: v => v.toFixed(input.precision ?? 2) }, v => set(v));
    case 'string': return input.options?.length
      ? selectRow(name, what, input.options.map(option => [option, option] as [string, string]), typeof value === 'string' ? value : input.default, v => set(v))
      : textRow(name, what, typeof value === 'string' ? value : input.default, v => set(v));
    case 'color': return input.options?.length
      ? selectRow(name, what, input.options.map(option => [option, option] as [string, string]), typeof value === 'string' ? value : input.default, v => set(v))
      : colorRow(name, what, typeof value === 'string' ? value : input.default, v => set(v));
    case 'tf': return selectRow(name, what, Object.keys(TIMEFRAMES).map(tf => [tf, tf] as [string, string]), typeof value === 'string' ? value : input.default, v => set(v));
    case 'source': return selectRow(name, what, input.options.map(option => [option, option] as [string, string]), typeof value === 'string' ? value : input.default, v => set(v));
    default: return null;
  }
}

/** The panel: its switch first (the same as the bar's lamp), then one row an input, in the piece's own order and groups. */
export function buildStudyPanel(store: Store, study: StudyDef, _tools: HTMLElement, body: HTMLElement, rebuild: () => void): void {
  const label = studyLabel(study.id, study.name), values = store.state.studyParams[study.id];
  body.append(heading(label));
  body.append(switchRow(label, t('Draws its plots on the map.'), studyOn(store.state.studySwitches, study.id), on => {
    store.set({ studySwitches: setStudy(store.state.studySwitches, study.id, on) }); rebuild();
  }));
  // Its own opacity (T-0046): the same number the Layers panel used to give every piece at once, now one for each.
  body.append(rangeRow(t('Opacity'), t('How strongly this piece is drawn; 0 hides it without turning it off.'),
    { min: 0, max: 100, step: 1, value: Math.round(studyAlpha(store.state, study.id) * 100), format: v => `${v}%` },
    v => store.set({ studyOpacity: setStudyOpacity(store.state.studyOpacity, study.id, v) })));
  let group: string | null = null;
  for (const input of study.inputs) {
    const want = input.group ?? null;
    if (want && want !== group) { body.append(heading(inputWords(want))); group = want; }
    const row = inputRow(study, input, studyInputValue(study, values, input), value => setStudyParam(store, study.id, input.id, value));
    if (row) body.append(row); else body.append(note(t('{name}: this build has no control for this kind of input.', { name: inputWords(input.name) })));
  }
  if (!study.inputs.length) body.append(note(t('This piece has no inputs of its own.')));
}
