import { STUDY_API, type Plot, type StudyDef, type StudyOutput } from '../engine/studies/contract.ts';
import { readInputs, type InputSpec } from '../engine/inputs/schema.ts';
import { timeframeMs, type Timeframe } from '../engine/time/timeframe.ts';
import type { Bar } from '../engine/series/source.ts';

/**
 * `trend-bias`: the OEC TREND CONTINUATION table (`OddEyeCircle` 107-151 inputs, `:2181-2260` table), the piece the platform plan calls
 * `orderflow-bias`. It is a bias by candles, not orderflow: `Orderflow_Bias_TF` (`:834-900`) only compares closes against the previous
 * candle's high and low, which is why D-21 names it the candle bias and A-10 leaves the real delta as a later, separate improvement.
 *
 * One row a timeframe of the group its chart timeframe shows (`GlobalFunctions library:190-200`): M, D, 1H, 5m on a 5m/1H/D/M chart; W,
 * 4H, 15m on a 1m/15m/4H/W chart; none on 30m, as Pine draws no column there. The formula is Pine's, in its order: green (`close >=
 * high[2]`), red (`close <= low[2]`), then grey/neutral inside `[low[2], high[2]]` (equal bounds included, overriding green/red), then the
 * previous candle's colours (`prev_*`) overriding that.
 *
 * The engine's contract has no pane-anchored table, so it is drawn with `bgcolor` cells and `label`s placed from `ctx.view`: same columns,
 * states and colours as Pine, anchored to the chart instead of the pane. The card says so.
 *
 * `compute` is pure: no hub, store, DOM or canvas; the seven series come resolved through `StudyData.candles`.
 */
const MINUTE = 60_000, DAY = 86_400_000, WEEK = 604_800_000, MONTH = 2_592_000_000;

export type BiasState = 'bullish' | 'bearish' | 'pre-bullish' | 'pre-bearish' | 'neutral';
type Orientation = 'horizontal' | 'vertical';

const TF_LABEL: Readonly<Record<Timeframe, string>> = { '1': '1m', '5': '5m', '15': '15m', '30': '30m', '60': '1H', '240': '4H', D: 'D', W: 'W', M: 'M' };
const STATE_TEXT: Readonly<Record<BiasState, string>> = { bullish: 'Bullish', bearish: 'Bearish', 'pre-bullish': 'Pre-Bullish', 'pre-bearish': 'Pre-Bearish', neutral: 'Neutral' };

/** The seven series Pine reads through `request.security` (`:131-151`): one `DataReq` each, resolved by the host. */
const SERIES: readonly { readonly tf: Timeframe; readonly key: string; readonly label: string }[] = [
  { tf: 'M', key: 'series:M', label: 'Monthly candles' },
  { tf: 'W', key: 'series:W', label: 'Weekly candles' },
  { tf: 'D', key: 'series:D', label: 'Daily candles' },
  { tf: '240', key: 'series:240', label: '4-hour candles' },
  { tf: '60', key: 'series:60', label: '1-hour candles' },
  { tf: '15', key: 'series:15', label: '15-minute candles' },
  { tf: '5', key: 'series:5', label: '5-minute candles' },
];

const INPUTS: readonly InputSpec[] = [
  { id: 'orderflow', kind: 'bool', name: 'Orderflow', default: true, group: 'Trend continuation' },
  { id: 'actual', kind: 'bool', name: 'Chart bias (closed candles)', default: true, group: 'Trend continuation' },
  { id: 'orientation', kind: 'string', name: 'Display', default: 'horizontal', options: ['horizontal', 'vertical'], group: 'Trend continuation' },
  { id: 'position', kind: 'string', name: 'Position', default: 'top-center', options: ['top-left', 'top-center', 'top-right', 'middle-left', 'middle-right', 'bottom-left', 'bottom-center'], group: 'Trend continuation' },
  { id: 'counter', kind: 'bool', name: 'Countdown', default: true, group: 'Trend continuation' },
  { id: 'live', kind: 'bool', name: 'Actual (forming candle)', default: true, group: 'Trend continuation' },
  { id: 'liveTf', kind: 'string', name: 'Actual timeframe', default: '60', options: ['5', '15', '60', '240', 'D', 'W', 'M'], group: 'Trend continuation' },
];

/** The bar size of a series, from its own starts (a study is told bars, not the chart's timeframe name). */
function barSize(bars: readonly Bar[]): number {
  for (let index = 1; index < bars.length; index += 1) { const step = bars[index]![0] - bars[index - 1]![0]; if (step > 0) return step; }
  return MINUTE;
}

/** The chart timeframe's name, for the chart-bias column (not Pine's `Actual`, which reads the HTF candle under way). */
export function chartTfName(chartMs: number): string {
  if (chartMs >= MONTH) return 'M';
  if (chartMs >= WEEK) return 'W';
  if (chartMs >= DAY) return 'D';
  const minutes = Math.round(chartMs / MINUTE);
  return minutes >= 240 ? '4H' : minutes >= 60 ? '1H' : `${minutes}m`;
}

/**
 * The bias of a series from its last two closed candles, as `Orderflow_Bias_TF` (`:834-900`): the last closed bar is Pine's `close[1]` /
 * `high[1]` / `low[1]`, the one before its `[2]`. `null` until there are three bars (two closed ones).
 */
export function biasState(bars: readonly Bar[]): BiasState | null {
  if (bars.length < 3) return null;
  const a = bars[bars.length - 2]!, b = bars[bars.length - 3]!;
  const high1 = a[2], low1 = a[3], close1 = a[4], high2 = b[2], low2 = b[3], close2 = b[4];
  let state: BiasState = 'neutral';
  // Pine's order, exactly: green, red, then grey/neutral (equal bounds count, and it overrides the two above), then the previous candle's.
  if (close1 >= high2) state = 'bullish';
  else if (close1 <= low2) state = 'bearish';
  if (close1 <= high2 && close1 >= low2) state = 'neutral';
  const prevGreen = (low1 < low2 && close1 <= high2 && close1 >= low2 && close1 > close2) || (high1 > high2 && low1 < low2 && close1 > close2);
  const prevRed = (high1 > high2 && close1 <= high2 && close1 >= low2 && close1 < close2) || (high1 > high2 && low1 < low2 && close1 < close2);
  if (prevGreen) state = 'pre-bullish';
  else if (prevRed) state = 'pre-bearish';
  // Not even a previous-candle colour: Pine leaves its default white, which the table shows as the neutral background.
  return state;
}

/** `Orderflow_Actual_TF` (`OddEyeCircle:776-800`): the bias of the candle that is **still forming**, against the closed one before it. */
export function actualBias(cur: Bar, prev: Bar): BiasState {
  const close = cur[4], high = cur[2], low = cur[3];
  const prevHigh = prev[2], prevLow = prev[3], prevClose = prev[4];
  const green = close >= prevHigh;
  const red = close <= prevLow;
  const neutral = close <= prevHigh && close >= prevLow;
  // Pine's `and` binds tighter than `or`: each side of the `or` is one run of `and`s.
  const prevGreen = (low < prevLow && neutral && close > prevClose) || (high > prevHigh && low < prevLow && close > prevClose);
  const prevRed = (high > prevHigh && neutral && close < prevClose) || (high > prevHigh && low < prevLow && close < prevClose);
  let state: BiasState = 'neutral'; // Pine's default is `color.white`, which the table shows as grey
  if (green) state = 'bullish'; else if (red) state = 'bearish';
  if (neutral) state = 'neutral';
  if (prevGreen) state = 'pre-bullish'; else if (prevRed) state = 'pre-bearish';
  return state;
}

/**
 * The live column: the bias of the series' **forming** candle, or `null` when its last bar has already closed (the exchange had not
 * opened the next one yet). The forming bar is the one whose period still contains `now`; if it has ended, nothing of this series is
 * under way and the column is not drawn.
 */
export function liveBias(bars: readonly Bar[], now: number): BiasState | null {
  if (bars.length < 2) return null;
  const size = barSize(bars);
  const cur = bars[bars.length - 1]!;
  if (!(cur[0] + size > now)) return null;
  return actualBias(cur, bars[bars.length - 2]!);
}

/** The fallback when `orderflow` is off: Pine colours the cell by the candle's own body (`close > open`). */
export function candleDirection(bars: readonly Bar[]): BiasState | null {
  if (bars.length < 2) return null;
  const bar = bars[bars.length - 2]!;
  return bar[4] > bar[1] ? 'bullish' : bar[4] < bar[1] ? 'bearish' : 'neutral';
}

/** Which group of columns a chart timeframe shows (`show_M` / `show_W`, `GlobalFunctions library:190-200`). */
export function biasGroups(chartMs: number): { month: boolean; week: boolean } {
  const minutes = Math.round(chartMs / MINUTE);
  if (chartMs < DAY) return { month: minutes === 5 || minutes === 60, week: minutes === 1 || minutes === 15 || minutes === 240 };
  if (chartMs === WEEK) return { month: false, week: true };
  return { month: chartMs >= DAY, week: false };
}

/** The timeframes the table shows, in Pine's table order, for a chart bar size. */
export function biasTimeframes(chartMs: number): readonly Timeframe[] {
  const groups = biasGroups(chartMs);
  if (groups.month) return ['M', 'D', '60', '5'];
  if (groups.week) return ['W', '240', '15'];
  return [];
}

/** The next close of `tf` after `now`: the UTC period boundary, as the exchange stamps them (00:00, Monday, the 1st). */
export function nextClose(now: number, tf: Timeframe): number {
  if (tf === 'M') { const date = new Date(now); return Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 1); }
  if (tf === 'W') { const day = Math.floor(now / DAY) * DAY, weekday = new Date(day).getUTCDay(); return day - ((weekday + 6) % 7) * DAY + WEEK; }
  const size = timeframeMs(tf);
  return Math.floor(now / size) * size + size;
}

/** Pine's `_Counter` text: days, hours, minutes and seconds left, the units that are zero left out. */
export function countdownText(now: number, close: number): string {
  const total = Math.max(0, Math.floor((close - now) / 1000));
  const d = Math.floor(total / 86_400), h = Math.floor(total % 86_400 / 3_600), m = Math.floor(total % 3_600 / 60), s = total % 60;
  const parts = [d > 0 ? `${d}D` : '', h > 0 ? `${h}H` : '', m > 0 ? `${m}m` : '', s > 0 ? `${s}s` : ''].filter(Boolean);
  return parts.length ? parts.join(' ') : '0s';
}

const stateColor = (state: BiasState, palette: { bid: string; ask: string; vwap: string }): string =>
  state === 'bullish' || state === 'pre-bullish' ? palette.bid : state === 'bearish' || state === 'pre-bearish' ? palette.ask : palette.vwap;

interface Column { readonly label: string; readonly state: BiasState; readonly tf: Timeframe | null; readonly merged?: boolean }

/** Where a table cell sits in the chart's own coordinates: the contract has no pane-anchored space. */
export function cellRect(view: { t0: number; t1: number; p0: number; p1: number }, col: number, row: number, cols: number, orientation: Orientation, position: string): { t0: number; t1: number; p0: number; p1: number } {
  const width = view.t1 - view.t0, height = view.p1 - view.p0;
  const left = position.includes('left') ? 0.03 : position.includes('right') ? 0.63 : 0.33;
  const top = position.startsWith('top') ? 0.05 : position.startsWith('middle') ? 0.4 : 0.72;
  const colWidth = (0.5 * width) / Math.max(1, cols), rowHeight = (0.06 * height);
  const x0 = view.t0 + width * (left + (orientation === 'horizontal' ? col : row) * (colWidth / width) * 1);
  const yTop = view.p1 - height * (top + (orientation === 'horizontal' ? row : col) * (rowHeight / height));
  const x1 = x0 + colWidth, y1 = yTop - rowHeight;
  return { t0: x0, t1: x1, p0: y1, p1: yTop };
}

export const TREND_BIAS: StudyDef = {
  api: STUDY_API,
  id: 'trend-bias',
  name: 'Trend bias',
  inputs: INPUTS,
  data: [{ key: 'chart', kind: 'candles', label: 'Chart candles' }, ...SERIES.map(s => ({ key: s.key, kind: 'candles' as const, label: s.label }))],
  compute(ctx): StudyOutput | null {
    const params = readInputs(INPUTS, ctx.params);
    const orderflow = params['orderflow'] !== false, counter = params['counter'] !== false, showActual = params['actual'] !== false;
    const live = params['live'] !== false;
    const liveTf = (SERIES.some(s => s.tf === params['liveTf']) ? params['liveTf'] : '60') as Timeframe;
    const orientation: Orientation = params['orientation'] === 'vertical' ? 'vertical' : 'horizontal';
    const position = typeof params['position'] === 'string' ? params['position'] : 'top-center';
    const chart = ctx.data.candles('chart');
    const chartMs = chart ? barSize(chart.bars) : 0;
    const stateOf = (bars: readonly Bar[]): BiasState | null => orderflow ? biasState(bars) : candleDirection(bars);
    const columns: Column[] = [];
    for (const tf of biasTimeframes(chartMs)) {
      const def = SERIES.find(s => s.tf === tf);
      const series = def ? ctx.data.candles(def.key) : null;
      const state = series ? stateOf(series.bars) : null;
      if (state) columns.push({ label: TF_LABEL[tf], state, tf });
    }
    if (showActual && chart) {
      const state = stateOf(chart.bars);
      if (state) columns.push({ label: `Chart ${chartTfName(chartMs)}`, state, tf: null });
    }
    // The Pine's `Actual` column (`:2249`): one cell, merged across the two rows, naming the timeframe it speaks for. Its state is read
    // from the series' forming candle, so it moves while that candle grows (`Orderflow_Actual_TF`, `:776`).
    if (live) {
      const def = SERIES.find(s => s.tf === liveTf);
      const series = def ? ctx.data.candles(def.key) : null;
      const state = series ? liveBias(series.bars, ctx.now) : null;
      if (state) columns.push({ label: `Actual ${TF_LABEL[liveTf]}`, state, tf: null, merged: true });
    }
    if (!columns.length) return null;
    // Pine's rows: the timeframe's name, its bias, and the countdown to its close (`_Counter`, `:2240`).
    const rows = 2 + (counter ? 1 : 0), plots: Plot[] = [];
    for (let col = 0; col < columns.length; col += 1) {
      const column = columns[col]!, color = stateColor(column.state, ctx.palette);
      if (column.merged) {
        const first = cellRect(ctx.view, col, 0, columns.length, orientation, position);
        const second = cellRect(ctx.view, col, 1, columns.length, orientation, position);
        const box = {
          t0: Math.min(first.t0, second.t0), t1: Math.max(first.t1, second.t1),
          p0: Math.min(first.p0, second.p0), p1: Math.max(first.p1, second.p1),
        };
        plots.push({ kind: 'bgcolor', ...box, color, alpha: 0.3 });
        plots.push({ kind: 'label', t: (box.t0 + box.t1) / 2, p: (box.p0 + box.p1) / 2, text: `${column.label} · ${STATE_TEXT[column.state]}`, color: ctx.palette.dark ? '#ffffff' : '#111111' });
        continue;
      }
      const texts = [column.label, STATE_TEXT[column.state], counter && column.tf ? countdownText(ctx.now, nextClose(ctx.now, column.tf)) : ''];
      for (let row = 0; row < rows; row += 1) {
        const rect = cellRect(ctx.view, col, row, columns.length, orientation, position);
        plots.push({ kind: 'bgcolor', t0: rect.t0, t1: rect.t1, p0: rect.p0, p1: rect.p1, color, alpha: row === 1 ? 0.38 : 0.18 });
        const text = texts[row]!;
        if (text) plots.push({ kind: 'label', t: (rect.t0 + rect.t1) / 2, p: (rect.p0 + rect.p1) / 2, text, color: ctx.palette.dark ? '#ffffff' : '#111111' });
      }
    }
    return { plots };
  },
};
