import { t } from '../i18n.ts';

/** The VWAP lines' names, as the page translates them: the session's, an anchor's, the whale buys and sells. */
export type VwapKind = 'session' | 'anchor' | 'whaleBuy' | 'whaleSell';

export const vwapCode = (kind: VwapKind, n: number): string =>
  kind === 'session' ? t('VWAP') : kind === 'anchor' ? `${t('AVWAP')} ${n}` : kind === 'whaleBuy' ? t('Whale buys') : t('Whale sells');
