import type { StudyDef } from './contract.ts';
import { SMA } from '../../indicators/builtin/sma.ts';
import { VWAP } from '../../indicators/vwap.ts';
import { HTF_CANDLES } from '../../indicators/htf-candles.ts';
import { PREVIOUS_OHLC } from '../../indicators/previous-ohlc.ts';
import { CYCLE_90 } from '../../indicators/cycle-90.ts';
import { REVERSE_ZONE } from '../../indicators/reverse-zone.ts';
import { RANGE_PRESSURE } from '../../indicators/range-pressure.ts';
import { SINGULARITY } from '../../indicators/singularity.ts';
import { BOOKMAP_TRIGGER } from '../../indicators/bookmap-trigger.ts';
import { TREND_BIAS } from '../../indicators/trend-bias.ts';
import { ST_ENTRY } from '../../indicators/st-entry.ts';

/**
 * The one list of studies. Adding an indicator is a file under `src/indicators/` (or `src/indicators/builtin/`) plus one entry here: that
 * is the card's acceptance, and `tests/engine-registry.test.mts` holds the list to the API version.
 */
const BUILTIN: readonly StudyDef[] = [SMA, VWAP, HTF_CANDLES, PREVIOUS_OHLC, CYCLE_90, REVERSE_ZONE, RANGE_PRESSURE, SINGULARITY, BOOKMAP_TRIGGER, ST_ENTRY, TREND_BIAS];
const ADDED: StudyDef[] = [];

export function studies(): readonly StudyDef[] { return [...BUILTIN, ...ADDED]; }

export function studyById(id: string): StudyDef | null {
  for (const study of studies()) if (study.id === id) return study;
  return null;
}

/** A study from outside the build (a third-party file): refused when its id is taken or its API is not this one. */
export function registerStudy(study: StudyDef): boolean {
  if (studyById(study.id) || ADDED.some(added => added.id === study.id)) return false;
  if (study.api !== 1) return false;
  ADDED.push(study);
  return true;
}
