/**
 * The host the registered studies read their data from: `DataReq` resolved from what the page already holds, never from a new source.
 *
 * - `chart` is the chart's own series (`state.candles`), the series every pane already draws.
 * - `series:<tf>` (`5`, `15`, `60`, `240`, `D`, `W`, `M`) is that series when the chart is on that timeframe; otherwise the same candles the
 *   key levels and the VWAP already read from the exchange through `hub.vwapHistory`, loaded by the KeyLevelHistory the page keeps per bar
 *   size (no new endpoint, no new kind of request).
 * - `ltf` is the minute series under a coarser chart, from the same loader the key levels and the VWAP read (`hub.vwapHistory(60_000)`,
 *   `hub.ts:215`): the piece that asks for it (`bookmap-trigger`) groups those bars into the chart bar by their start. A chart already at a
 *   minute or finer has nothing under it and the page holds no sub-minute OHLC, so `ltf` is null there and says why; the trade tape's
 *   per-second prices are never turned into bars (`hub.flow` `ownPrice` has no open or close).
 * - Anything else (`prints`) is not resolved here on purpose: a study that asks for it draws nothing rather than being handed another series,
 *   and the miss is said once in the console.
 *
 * `paintRegisteredStudies` is the one call the map makes: it computes every registered study except the VWAP (that one has its own adapter
 * with settings and anchors) and paints them on the map's canvas with the engine's painter.
 */
import type { AppState, CandleRow } from '../store.ts';
import type { Hub } from '../hub.ts';
import { TIMEFRAMES } from '../hub.ts';
import type { Bounds } from '../view.ts';
import type { Palette } from '../theme.ts';
import type { Scope } from '../../engine/draw/scope.ts';
import { paintStudies } from '../../engine/draw/painter.ts';
import type { ReadoutRow, StudyCandles, StudyData, StudyOutput, StudyPalette, StudySums } from '../../engine/studies/contract.ts';
import { readInputs } from '../../engine/inputs/schema.ts';
import { studies } from '../../engine/studies/registry.ts';
import { historyTarget } from '../keylevels/history.ts';
import { barMsFor } from '../keylevels/levels.ts';
import type { KeyTag } from '../keylevels/paint.ts';
import { currentCoin } from '../coin.ts';
import { pageNow, replaying } from '../replay/clock.ts';
import { zoneId, zoneName } from '../format.ts';
import { studyOutcome, type StudyResult } from './outcome.ts';
import { studyOn } from './switches.ts';
import { studyAlpha } from './opacity.ts';

/** The bar size `ltf` is read at: a minute under any coarser chart, and null when the chart is already a minute or finer (no sub-minute OHLC is held). */
export function ltfBarMs(chartBarMs: number): number | null { return chartBarMs > 60_000 ? 60_000 : null; }

/** The bar sizes a study names in `series:<tf>`, as the Pine names them. */
const SERIES_MS: Readonly<Record<string, number>> = { '5': 300_000, '15': 900_000, '60': 3_600_000, '240': 14_400_000, D: 86_400_000, W: 604_800_000, M: 2_592_000_000 };
/** The studies this host does not compute: the VWAP has its own adapter (settings, anchors, whale sums). */
const OWN_ADAPTER = 'vwap';

export class StudyHost implements StudyData {
  #said = new Set<string>();
  constructor(private state: AppState, private hub: Hub, private invalidate: () => void) {}

  candles(key: string): StudyCandles | null {
    const series = this.#resolve(key);
    return series && series.bars.length >= 2 ? series : null;
  }

  /** No registered study asks for the large-order sums yet; when one does, it is a miss, not a guess. */
  sums(key: string): StudySums | null { this.#miss(key, 'sums'); return null; }

  #resolve(key: string): StudyCandles | null {
    if (key === 'chart') return this.#own();
    if (key === 'ltf') return this.#lower();
    const name = key.startsWith('series:') ? key.slice('series:'.length) : null;
    const bar = name ? SERIES_MS[name] : undefined;
    if (bar === undefined) { this.#miss(key, 'series'); return null; }
    const tf = TIMEFRAMES[this.state.timeframe] ?? 3_600_000;
    if (bar === tf) return this.#own();
    return this.#history(bar, key);
  }

  /** The minute series under the chart: from the same loader the key levels use, or nothing when the chart has nothing under it. */
  #lower(): StudyCandles | null {
    const bar = ltfBarMs(TIMEFRAMES[this.state.timeframe] ?? 3_600_000);
    if (bar === null) { this.#miss('ltf', 'lower'); return null; }
    return this.#history(bar, 'ltf');
  }

  /** The chart's own bars: held from its first bar, with no history to hand over to. */
  #own(): StudyCandles | null {
    const bars = this.state.candles;
    if (bars.length < 2) return null;
    return { bars, heldFrom: bars[0]![0], liveFrom: Infinity };
  }

  /** A coarser or finer series from the same exchange history the key levels read, asked for the two periods before the view. */
  #history(bar: number, key: string): StudyCandles | null {
    const target = historyTarget(this.state.seriesInstrument || this.state.marketId, currentCoin());
    if (!target) { this.#miss(key, 'market'); return null; }
    const from = Math.min(this.#viewFrom(), pageNow()) - 2 * bar;
    const history = this.hub.vwapHistory(bar);
    history.ensure(target, Math.max(0, from), bar, this.invalidate);
    if (history.id !== target.id || history.barMs !== bar || !history.bars.length) return null;
    return { bars: history.bars as readonly CandleRow[], heldFrom: history.heldFrom, liveFrom: Infinity };
  }

  #viewFrom(): number { return this.#view?.t0 ?? 0; }
  #view: Bounds | null = null;
  /** The view the ask is for (the two periods before it decide how far back to load). */
  setView(view: Bounds): this { this.#view = view; return this; }

  /** The keys this host could not resolve, in the order they were asked: a study that draws nothing for that reason says which. */
  #missing: string[] = [];
  missing(): readonly string[] { return this.#missing; }
  #miss(key: string, what: string): void {
    if (!this.#said.has(key)) { this.#said.add(key); this.#missing.push(key); }
  }
}

export interface StudiesScope {
  readonly state: AppState;
  readonly hub: Hub;
  readonly view: Bounds;
  readonly width: number;
  readonly height: number;
  readonly palette: Palette;
  readonly board: Scope['board'];
  readonly invalidate: () => void;
}

/** The last frame's outcomes, for the layers panel: the panel does not compute, it reads this. */
let report: readonly StudyResult[] = [];
export function studiesStatus(): readonly StudyResult[] { return report; }

/** The last frame's named numbers, per study, for the panels that read them (D-31): a panel never recomputes what the piece drew. */
let readouts = new Map<string, readonly ReadoutRow[]>();
export function studyReadout(id: string): readonly ReadoutRow[] { return readouts.get(id) ?? []; }

/** Said once per change, never per frame: a study that keeps failing keeps its line out of the console. */
let said = '';
function reportStudies(rows: readonly StudyResult[]): void {
  report = rows;
  const key = rows.map(row => `${row.id}:${row.miss ?? 'ok'}:${row.data ?? ''}:${row.error ?? ''}`).join('|');
  if (key === said) return;
  said = key;
  for (const row of rows) {
    if (!row.miss) continue;
    console.info(row.miss === 'error' ? `[studies] ${row.id}: error: ${row.error}`
      : row.miss === 'noData' ? `[studies] ${row.id}: no data for ${row.data}`
      : `[studies] ${row.id}: returned nothing`);
  }
}

/** The colours a study may ask for, from the map's palette. */
function studyPalette(p: Palette): StudyPalette { return { dark: p.dark, vwap: p.vwap, bid: p.bid, ask: p.ask, panel: p.panel }; }

/** Every registered study there is, computed against what the page holds and painted: the tags go to the axis like the VWAP's. */
export function paintRegisteredStudies(ctx: CanvasRenderingContext2D, o: StudiesScope): KeyTag[] {
  const palette = studyPalette(o.palette), outputs: { output: StudyOutput; alpha: number }[] = [], rows: StudyResult[] = [], named = new Map<string, readonly ReadoutRow[]>();
  for (const study of studies()) {
    if (study.id === OWN_ADAPTER || !studyOn(o.state.studySwitches, study.id)) continue;
    // A study that throws is caught here: its row says so and the others draw as usual.
    const host = new StudyHost(o.state, o.hub, o.invalidate).setView(o.view);
    let output: StudyOutput | null = null, error: unknown = null;
    try {
      output = study.compute({
        params: readInputs(study.inputs, o.state.studyParams[study.id] ?? null), data: host, view: o.view, now: pageNow(), zone: zoneId(), coin: currentCoin().coin,
        windows: [], anchors: [], zoneBarMs: barMsFor(zoneId(), o.view.t0, o.view.t1), replayAt: replaying() ? pageNow() : null, palette,
      });
    } catch (caught) { error = caught; }
    rows.push(studyOutcome(study.id, study.name, { output, error, missing: host.missing() }));
    // What the panel reads: the piece's own numbers, never a second calculation (D-31). A piece with nothing to say says nothing.
    if (output?.readout?.length) named.set(study.id, output.readout);
    // Each piece draws at its own opacity (T-0046), on top of the layer's: 0 means it is on but invisible, and it is not painted at all.
    if (output) { const alpha = studyAlpha(o.state, study.id); if (alpha > 0) outputs.push({ output, alpha }); }
  }
  reportStudies(rows);
  readouts = named;
  if (!outputs.length) return [];
  // One paint a piece, so its own alpha reaches only its plots; the tags still share the layer's one board and come back together.
  const tags: { key: string; price: number; rank: number; text: string; color?: string | undefined }[] = [];
  for (const drawn of outputs) {
    ctx.save(); ctx.globalAlpha *= drawn.alpha;
    tags.push(...paintStudies(ctx, [drawn.output], { view: o.view, width: o.width, height: o.height, palette, board: o.board }));
    ctx.restore();
  }
  return tags.map(tag => ({ key: tag.key, y: (1 - (tag.price - o.view.p0) / (o.view.p1 - o.view.p0)) * o.height, rank: tag.rank, text: tag.text, older: false, color: tag.color }));
}
