import { dayWindows, monthWindows, offsetMs, weekWindows, type ProfileWindow } from '../traded/sessions.ts';
import type { CandleRow } from '../store.ts';

/**
 * Key levels from each market's own daily, weekly and monthly candles (the exchange's 1d / 1w / 1M opens and
 * closes — UTC midnight, Monday, 1st on Binance, Bybit, OKX, … — not a wall-clock zone calendar). Previous high,
 * low and close of each completed period are drawn across the next one; an untouched level can run on until price
 * reaches it.
 */

export type PeriodKind = 'day' | 'week' | 'month';
export const PERIOD_KINDS: readonly PeriodKind[] = ['day', 'week', 'month'];
/** Which lines of one kind of period are drawn: the previous one's high and low, and its close. */
export interface PeriodLines { prev: boolean; close: boolean }
export type LevelWhat = 'high' | 'low' | 'close';

const MINUTE = 60_000, HOUR = 3_600_000, DAY = 86_400_000;
/** How far back the levels reach: about two months of daily bars cover previous week and month. */
export const MAX_BACK_MS = 62 * DAY;
/** Look back this many completed periods when scanning for untouched levels still in view. */
const LOOKBACK: Readonly<Record<PeriodKind, number>> = { day: 12, week: 8, month: 3 };
/** The most previous periods one kind may show (Key levels' panel); each one drawn needs the one before it, so a little more is read. */
export const MAX_PREVIOUS = 12;
const MAX_LINES = 600;

/** Exchange kline length used when asking for this period's native candles. */
export const PERIOD_MS: Readonly<Record<PeriodKind, number>> = {
  day: DAY,
  week: 604_800_000,
  month: 2_592_000_000,
};

/** One period bar as the exchange sent it (open time = exchange boundary). */
export interface PeriodBar {
  openTime: number;
  /** Exclusive end when known (next bar's open, or derived for the bar under way). */
  closeTime: number;
  open: number;
  high: number;
  low: number;
  close: number;
  /** True when the exchange has closed this bar (a later bar exists, or heldTo is past closeTime). */
  complete: boolean;
}

export type PeriodBars = Readonly<Record<PeriodKind, readonly PeriodBar[]>>;

/** One line on the chart. */
export interface KeyLine {
  period: PeriodKind;
  what: LevelWhat;
  /** A previous period's level (drawn over the next one). */
  prev: boolean;
  price: number;
  from: number;
  to: number;
  /**
   * For a previous period's level not traded through by `to`: the first later bar that reached it, or null if none
   * yet (runs on to the right edge). Absent: not extended.
   */
  reached?: number | null;
  /** When the period whose level it is began. */
  of: number;
  window: string;
}

/**
 * Build period bars from native exchange candles of one size. `closeTime` of each bar is the next bar's open; the
 * last bar's end is `lastEnd` (now, or the derived period end). A bar is complete when a later bar exists or
 * `heldTo` is at least its close (with a small slack for refresh lag).
 */
export function periodBarsFromCandles(candles: readonly CandleRow[], lastEnd: number, heldTo: number = Infinity, slackMs = 6 * 60_000): PeriodBar[] {
  if (!candles.length) return [];
  const sorted = [...candles].sort((a, b) => a[0] - b[0]);
  const out: PeriodBar[] = [];
  for (let i = 0; i < sorted.length; i++) {
    const c = sorted[i]!;
    const closeTime = i + 1 < sorted.length ? sorted[i + 1]![0] : lastEnd;
    if (!(closeTime > c[0])) continue;
    const complete = i + 1 < sorted.length || heldTo >= closeTime - slackMs;
    out.push({ openTime: c[0], closeTime, open: c[1], high: c[2], low: c[3], close: c[4], complete });
  }
  return out;
}

/** First bar at or after `after` whose range reaches `price`. */
export function reachedAtBar(price: number, after: number, bars: readonly PeriodBar[]): number | null {
  for (const b of bars) {
    if (b.openTime < after) continue;
    if (b.low <= price && price <= b.high) return b.openTime;
  }
  return null;
}

/** Earliest candle time needed for the enabled lines. */
export function neededFrom(lines: Readonly<Record<PeriodKind, PeriodLines>>, _zone: string, t0: number, now: number, count = 1): number {
  let from = now;
  for (const period of PERIOD_KINDS) {
    const want = lines[period];
    if (!want.prev && !want.close) continue;
    const periods = Math.max(LOOKBACK[period], Math.min(MAX_PREVIOUS, count) + 2);
    const span = PERIOD_MS[period] * periods;
    from = Math.min(from, Math.min(t0, now) - span);
  }
  return Math.max(from, now - MAX_BACK_MS - PERIOD_MS.month);
}

export interface KeyLineOptions {
  t0: number;
  t1: number;
  now: number;
  untouched: boolean;
  /** How many previous periods (of each kind) are drawn, newest first (default 1). */
  count?: number;
}

/**
 * Lines from exchange-native day/week/month bars: over each period that touches the chart, the previous completed
 * period's high, low and close. Untouched previous levels can extend past the next period until price reaches them.
 */
export function keyLines(bars: PeriodBars, lines: Readonly<Record<PeriodKind, PeriodLines>>, o: KeyLineOptions): KeyLine[] {
  const out: KeyLine[] = [], end = Math.min(o.t1, o.now);
  if (!(end > o.t0)) return out;
  for (const period of PERIOD_KINDS) {
    const want = lines[period];
    if (!want.prev && !want.close) continue;
    const list = bars[period];
    if (list.length < 2) continue;
    for (let i = 1; i < list.length; i++) {
      const prev = list[i - 1]!, cur = list[i]!;
      if (!prev.complete) continue;
      // Draw previous levels across the current period (and lookback periods that still touch the view).
      if (cur.closeTime <= o.t0 - PERIOD_MS[period] * LOOKBACK[period]) continue;
      if (cur.openTime > end) continue;
      // How many past periods are shown (of each kind), newest first. 1 draws the last completed period over the one under way (or over the
      // last one when the history has ended); 2 adds the one before it, and so on. The period under way never uses a slot up.
      const shown = Math.max(1, Math.min(MAX_PREVIOUS, o.count ?? 1)), newestPast = list.length - 2;
      if (i - 1 < newestPast - (shown - 1)) continue;
      const to = cur.closeTime, under = cur.closeTime > o.now;
      const levels: [LevelWhat, number][] = [];
      if (want.prev) levels.push(['high', prev.high], ['low', prev.low]);
      if (want.close) levels.push(['close', prev.close]);
      for (const [what, price] of levels) {
        const line: KeyLine = {
          period, what, prev: true, price,
          from: cur.openTime, to,
          of: prev.openTime,
          window: `${period}|${cur.openTime}`,
        };
        if (o.untouched && !under) {
          const hit = reachedAtBar(price, cur.openTime, list.slice(i));
          if (hit === null || hit >= cur.closeTime) line.reached = hit;
        }
        out.push(line);
      }
    }
  }
  return out.length > MAX_LINES ? out.sort((a, b) => a.from - b.from).slice(-MAX_LINES) : out;
}

export const lineEnd = (line: KeyLine): number => line.reached === undefined ? line.to : line.reached === null ? Infinity : line.reached;

/**
 * The candle size whose bars start on every period boundary of `zone` (for VWAP / volume-profile calendars — not key levels).
 */
export function barMsFor(zone: string, from: number, to: number): number {
  let bar = HOUR;
  for (let t = from; ; t = Math.min(to, t + 7 * DAY)) {
    const minutes = Math.round(offsetMs(zone, t) / MINUTE);
    if (minutes % 30 !== 0) return 15 * MINUTE;
    if (minutes % 60 !== 0) bar = 30 * MINUTE;
    if (t >= to) return bar;
  }
}

/** Zone calendar windows (VWAP / delta CVD resets / volume profile). Key levels use exchange candles instead. */
export function windowsOf(period: PeriodKind, zone: string, t0: number, t1: number): ProfileWindow[] {
  return period === 'day' ? dayWindows(zone, t0, t1) : period === 'week' ? weekWindows(zone, t0, t1) : monthWindows(zone, t0, t1);
}
