import { price as fmtPrice } from '../app/format.ts';
import { vwapCode, type VwapKind } from '../app/vwap/names.ts';
import { vwapBarMs, vwapSeries, whaleSeries, type VwapPoint } from '../app/vwap/vwap.ts';
import { readInputs } from '../engine/inputs/schema.ts';
import type { InputSpec } from '../engine/inputs/schema.ts';
import type { AxisTag, LineStyle, OutputLabel, Plot, StudyDef, StudyOutput } from '../engine/studies/contract.ts';
import { STUDY_API } from '../engine/studies/contract.ts';

/**
 * The VWAP, migrated to the contract: the same math as `src/app/vwap/vwap.ts` (typical price weighted by volume, bands by the
 * volume-weighted deviation), now worked out from the data the host hands in instead of from the hub, and returned as plots instead of
 * drawn. The page's adapter (`src/app/vwap/study-adapter.ts`) resolves the sessions, anchors and whale sums; this file imports no hub, no
 * store and no fetch.
 */
const INPUTS: readonly InputSpec[] = [
  { id: 'session', kind: 'bool', name: 'Session VWAP', default: true, group: 'VWAP' },
  { id: 'period', kind: 'string', name: 'Session', default: 'day', options: ['day', 'week', 'month'], group: 'VWAP' },
  { id: 'bands', kind: 'int', name: 'Bands', default: 0, min: 0, max: 2, group: 'VWAP' },
  { id: 'labels', kind: 'bool', name: 'Labels', default: true, group: 'VWAP' },
  { id: 'tags', kind: 'bool', name: 'Price-axis tags', default: true, group: 'VWAP' },
  { id: 'whale', kind: 'bool', name: 'Whale VWAP', default: false, group: 'VWAP' },
  { id: 'whaleUsd', kind: 'float', name: 'Whale size (USD)', default: 1_000_000, min: 0, max: 1_000_000_000, group: 'VWAP' },
];

/** The tag and label order against the key levels' (0 to 11); the session VWAP ranks with the previous day's levels, anchors after the opens. */
const RANK = { session: 1.5, anchor: 6.5, whaleBuy: 9, whaleSell: 9 } as const;

interface Line { readonly kind: VwapKind; readonly n: number; readonly points: VwapPoint[]; readonly live: boolean; readonly key: string; readonly bar?: number; readonly liveFrom?: number }

const whaleKind = (kind: VwapKind): boolean => kind === 'whaleBuy' || kind === 'whaleSell';

const sessionStyle = (color: string): LineStyle => ({ width: 1.8, alpha: 1, color, halo: true });
const anchorStyle = (color: string): LineStyle => ({ width: 1.5, dash: [9, 3, 2, 3], alpha: 1, color, halo: true });
const whaleStyle = (color: string): LineStyle => ({ width: 1.3, alpha: 0.95, color, halo: true });
const bandStyle = (color: string, k: number): LineStyle => ({ width: 1.1, dash: [3, 4], alpha: k === 1 ? 0.8 : 0.55, color, halo: true });

const point = (q: VwapPoint): { t: number; p: number } => ({ t: q.t, p: q.vwap });

export const VWAP: StudyDef = {
  api: STUDY_API,
  id: 'vwap',
  name: 'VWAP',
  inputs: INPUTS,
  data: [
    { key: 'session', kind: 'candles', label: 'Session candles' },
    { key: 'anchor', kind: 'candles', label: 'Anchored candles' },
    { key: 'whale', kind: 'sums', label: 'Large market orders' },
  ],
  compute(ctx): StudyOutput | null {
    const params = readInputs(INPUTS, ctx.params);
    const sessionOn = params['session'] === true, whaleOn = params['whale'] === true;
    const bandsRaw = params['bands'], bands = typeof bandsRaw === 'number' && Number.isFinite(bandsRaw) ? Math.max(0, Math.min(2, Math.round(bandsRaw))) : 0;
    const labelsOn = params['labels'] === true, tagsOn = params['tags'] === true;
    const now = ctx.now, replayAt = ctx.replayAt, palette = ctx.palette;
    const sessions = ctx.windows, anchors = ctx.anchors;
    const sessionBar = vwapBarMs(sessions.length ? now - sessions[0]!.from : 0, ctx.zoneBarMs);
    const anchorBars = anchors.map(at => vwapBarMs(now - at, ctx.zoneBarMs));
    const plots: Plot[] = [], labels: OutputLabel[] = [], tags: AxisTag[] = [];

    // A history bar's point counts once the bar is over; the chart's own candles (from `liveFrom`) and the whale lines are cut to the moment already.
    const cut = (line: Line): Line => replayAt === null || line.bar === undefined ? line : { ...line, points: line.points.filter(q => q.t >= (line.liveFrom ?? Infinity) || q.t + line.bar! <= replayAt) };

    const emit = (line: Line, style: LineStyle): void => {
      const points = cut(line).points;
      if (!points.length) return;
      const code = vwapCode(line.kind, line.n), last = points[points.length - 1]!, color = line.kind === 'whaleBuy' ? palette.bid : line.kind === 'whaleSell' ? palette.ask : palette.vwap;
      if (line.kind === 'session') for (let k = bands; k >= 1; k--) {
        plots.push({ kind: 'line', points: points.map(q => ({ t: q.t, p: q.vwap + k * q.sd })), style: bandStyle(color, k) });
        plots.push({ kind: 'line', points: points.map(q => ({ t: q.t, p: q.vwap - k * q.sd })), style: bandStyle(color, k) });
      }
      plots.push({ kind: 'line', points: points.map(point), style });
      const first = line.points[0]!, ty = first.t;
      if (line.kind === 'anchor' && ty >= ctx.view.t0 && ty <= ctx.view.t1) plots.push({ kind: 'mark', t: ty, p: first.vwap, color: palette.vwap, shape: 'triangle' });
      if (line.live && labelsOn) labels.push({ text: `${code} ${fmtPrice(last.vwap)}`, price: last.vwap, t: last.t, rank: RANK[line.kind], color });
      if (tagsOn && !whaleKind(line.kind)) tags.push({ key: `vwap|${line.key}`, price: last.vwap, text: code, rank: RANK[line.kind], color: palette.vwap });
    };

    // The session lines, oldest first, each with its bars and bands.
    if (sessionOn && sessions.length) {
      const series = ctx.data.candles(`session:${sessionBar}`);
      if (series) for (const window of sessions) {
        if (series.heldFrom > window.from) continue;
        const points = vwapSeries(series.bars, window.from, window.to);
        if (points.length) emit({ kind: 'session', n: 0, points, live: window.to > now, key: window.key, bar: sessionBar, liveFrom: series.liveFrom }, sessionStyle(palette.vwap));
      }
    }

    // The whale lines of each session, from where the recording's count begins when that is later.
    if (whaleOn && sessions.length) {
      const sums = ctx.data.sums('whale');
      if (sums) for (const window of sessions) {
        const upTo = replayAt !== null ? Math.min(window.to, replayAt - 60_000 + 1) : window.to;
        const since = sums.since !== null ? Math.floor(sums.since / 60_000) * 60_000 : window.from;
        const { buys, sells } = whaleSeries(sums.rows, Math.max(window.from, since), upTo, Math.min(window.to, now));
        if (buys.length) emit({ kind: 'whaleBuy', n: 0, points: buys, live: window.to > now, key: `whale-buy|${window.key}` }, whaleStyle(palette.bid));
        if (sells.length) emit({ kind: 'whaleSell', n: 0, points: sells, live: window.to > now, key: `whale-sell|${window.key}` }, whaleStyle(palette.ask));
      }
    }

    // The anchors, from the first whole bar after the moment chosen: a bar begun before it would carry volume from before.
    anchors.forEach((at, index) => {
      const bar = anchorBars[index]!, series = ctx.data.candles(`anchor:${bar}`), start = Math.ceil(at / bar) * bar;
      if (!series || series.heldFrom > start) return;
      const points = vwapSeries(series.bars, start, Infinity);
      if (points.length) emit({ kind: 'anchor', n: index + 1, points, live: true, key: `anchor|${at}`, bar, liveFrom: series.liveFrom }, anchorStyle(palette.vwap));
    });

    return plots.length || tags.length ? { plots, labels, tags } : null;
  },
};
