import { t } from '../i18n.ts';

/**
 * A study's name in the language of the page (T-0045): its id is a literal `t()` here, so the packs know the name is asked. A study from
 * outside the build keeps its own name. One place for it, because the Layers panel and the piece's own panel must say the same.
 */
export function studyLabel(id: string, own: string): string {
  switch (id) {
    case 'sma': return t('Simple moving average');
    case 'htf-candles': return t('Higher-timeframe candles');
    case 'previous-ohlc': return t('Previous OHLC');
    case 'cycle-90': return t('90 min cycle');
    case 'reverse-zone': return t('Reverse zone');
    case 'range-pressure': return t('Range pressure');
    case 'singularity': return t('Singularity');
    case 'bookmap-trigger': return t('Bookmap trigger');
    case 'st-entry': return t('ST entry');
    default: return own;
  }
}
