import { el } from './dom.ts';
import { togglePanel, type Panel } from './ui.ts';
import { t } from './i18n.ts';

/** Where the author and the code can be found. */
export const AUTHOR = Object.freeze({
  name: 'PONCE54958',
  line: t('Meraki Traders'),
  x: 'https://x.com/PONCE54958',
  xHandle: '@PONCE54958',
  github: 'https://github.com/PONCE54958/oecliquidity.github.io',
  /** Where the page is published: what a screenshot carries in its corner. */
  site: 'https://ponce54958.github.io/OEClIquidityplay/',
});

function link(href: string, label: string, detail: string): HTMLAnchorElement {
  return el('a', { class: 'author-link', href, target: '_blank', rel: 'noopener noreferrer' }, el('b', { textContent: label }), el('span', { textContent: detail }));
}

/** The author box: what this project is, who made it, and where to find them. Opens under `anchor`. */
export function toggleAuthor(anchor: HTMLElement): Panel | null {
  return togglePanel(anchor, { title: t('About'), width: 340, align: 'right' }, (_tools, body) => {
    body.classList.add('author-body');
    body.append(
      el('div', { class: 'author-card' },
        el('div', { class: 'avatar', textContent: AUTHOR.name[0] ?? 'K', ariaHidden: 'true' }),
        el('div', {}, el('strong', { textContent: AUTHOR.name }), el('p', { textContent: AUTHOR.line }))),
      el('p', { class: 'fine', textContent: t('It reads public exchange data straight from your browser and sends nothing to anyone. It is built in free time, so things can occasionally break; tell me when they do.') }),
      el('div', { class: 'author-links' }, link(AUTHOR.x, 'X', AUTHOR.xHandle)),
    );
  });
}
