import { STUDY_API, type Plot, type StudyDef, type StudyOutput } from '../engine/studies/contract.ts';
import { readInputs, type InputSpec, type InputValues } from '../engine/inputs/schema.ts';
import type { Bar } from '../engine/series/source.ts';
import { CYCLE_90_ZONE, CYCLE_SESSIONS, cycleSessions, type CycleSession, type CycleVariant, type CycleZone } from './cycle-90.ts';

/**
 * `reverse-zone`: the OEC REVERSE ZONE piece, chart version (D-18) and per session of the 90-minute cycle (D-19).
 *
 * The Pine (`OECLiquidityindicators/OddEyeCircle`): the chart conditions are `isRZ_Bullish_Condition` (2712) and
 * `isRZ_Bearish_Condition` (2718) — four candles of the chart's own series. The drawing (3357-3445) makes the box on the trigger bar:
 * bullish from `low[1]` (top) to `low[2]` (bottom), bearish from `high[2]` (top) to `high[1]` (bottom) — the levels are copied as they are,
 * including the Pine's order. The bullish trigger only exists inside the A or M complements (`time_critical_complement_A or _M`, 3361); the
 * bearish one inside D or X (`3432`, and the box at `3433`). The per-session combination (`rz_Bull_Asia_A` … `rz_s_bookmap_*`, 3008-3031) counts a trigger per session.
 *
 * Sessions are not recalculated here: the piece imports `cycleSessions` from `cycle-90` (T-1014, T-1025) and asks it for the windows of
 * the stretch. The bullish zone lives in an A or M session and the bearish one in a D or X session (`:3432`), the two windows the
 * complement of each variant is. **Both sides are emitted**: the note this piece carried until T-1031 — that `cycle-90`
 * did not carry D/X and the bearish zone had to stay off — was false once T-1025 landed, and it kept the bearish half of the product
 * silent (`bookmap-trigger` and `st-entry` read it).
 *
 * No HTF variants (D-18) and no demon boxes: what this piece returns is the chart zone and its two levels. `compute` is pure and imports no
 * hub, store or fetch; the engine's painter draws the plots.
 *
 * One overlap worth saying: NY AM's D and X windows are the same in the Pine (`cycle_zeusy_nyam_D_time` = `cycle_zeusy_nyam_X_time`,
 * `OddEyeCircle:2669-2670`), so `sessionAt` finds the D one first and NY AM is never reported as X. Nothing is lost: the Pine accepts
 * that window for the zone under either complement (`complement_D or complement_X`, `:3432` / `:3630`), and the *range* there is the D
 * one anyway, because `_Draw_Range` gates both NY AM calls with `cycle_nyam_D` alone (`:3081-3082`) — which is why the Pine's own X
 * label for that group is empty.
 */
export interface ZoneOhlc { readonly o: number; readonly h: number; readonly l: number; readonly c: number }
export type ZoneSide = 'bull' | 'bear';

/** `isRZ_Bullish_Condition` (`OddEyeCircle:2712`), on the chart's own last four candles. */
export function rzBullishChart(cur: ZoneOhlc, p1: ZoneOhlc, p2: ZoneOhlc, p3: ZoneOhlc): boolean {
  return cur.c > cur.o && cur.c >= p1.c && cur.c > p2.c && cur.c > p3.o
    && p1.c > p2.c && p1.c > p3.o && p1.l >= p2.l && p2.l < p3.l && p3.c < p3.o && p3.l > p2.l && p3.l < p1.l;
}

/** `isRZ_Bearish_Condition` (`OddEyeCircle:2718`). */
export function rzBearishChart(cur: ZoneOhlc, p1: ZoneOhlc, p2: ZoneOhlc, p3: ZoneOhlc): boolean {
  return cur.c < cur.o && cur.c <= p1.c && cur.c < p2.c && cur.c < p3.o
    && p1.c < p2.c && p1.c < p3.o && p1.h <= p2.h && p2.h > p3.h && p3.c > p3.o && p3.h < p2.h && p3.h > p1.h;
}

const INPUTS: readonly InputSpec[] = [
  { id: 'bull', kind: 'bool', name: 'Bullish zones', default: true, group: 'Reverse zone' },
  // The Pine's own two: `rz_mode` defaults to 'Present' and `rz_last` to 5 (`OEC:416`, `:415`), and the cap is applied in that mode
  // only (`GF:925-928`: `while array.size(_box_array) > _last`, dropping the oldest). 'Historic' keeps them all.
  { id: 'mode', kind: 'string', name: 'Mode', default: 'Present', options: ['Present', 'Historic'], group: 'Reverse zone' },
  { id: 'last', kind: 'int', name: 'Last', default: 5, min: 1, max: 20, group: 'Reverse zone' },
  // `rz_style` defaults to 'Future' (`OEC:420`), and only that style stretches the box 8 bars past its end (`OEC:3501-3505`).
  { id: 'style', kind: 'string', name: 'Style', default: 'Future', options: ['Right', 'Future'], group: 'Reverse zone' },
  // The two that only exist in the 'Right' style (`OEC:421-422`): the box is anchored at `timenow`, not at the last bar.
  { id: 'anchor', kind: 'int', name: 'Anchor', default: 30, min: 0, max: 300, group: 'Reverse zone' },
  { id: 'extend', kind: 'int', name: 'Extend', default: 160, min: 1, max: 1_000, group: 'Reverse zone' },
  // `rz_mitigated` is off by default in the Pine (`OEC:417`), so the zones survive unless someone switches this on.
  { id: 'mitigated', kind: 'bool', name: 'Mitigation', default: false, group: 'Reverse zone' },
  { id: 'bear', kind: 'bool', name: 'Bearish zones', default: true, group: 'Reverse zone' },
];

const ohlc = (bar: Bar): ZoneOhlc => ({ o: bar[1], h: bar[2], l: bar[3], c: bar[4] });
const flag = (params: InputValues, id: string): boolean => params[id] === true;
const labelOf = (id: string): string => CYCLE_SESSIONS.find(spec => spec.id === id)?.label ?? id;
const number = (params: InputValues, id: string, fallback: number): number => typeof params[id] === 'number' && Number.isFinite(params[id]) ? params[id] : fallback;
const text = (params: InputValues, id: string, fallback: string): string => typeof params[id] === 'string' ? params[id] as string : fallback;

/** The session a bar falls in, whichever variant: which side it may carry is decided by that variant (`:3361`, `:3432`). */
function sessionAt(sessions: readonly CycleSession[], t: number): CycleSession | null {
  for (const session of sessions) if (t >= session.from && t < session.to) return session;
  return null;
}

/** The side a session's window belongs to: A and M are the Pine's bullish windows, D and X its bearish ones (`:3361`, `:3432`). */
export function sideOfVariant(variant: CycleVariant): ZoneSide { return variant === 'A' || variant === 'M' ? 'bull' : 'bear'; }

/**
 * `Bool_TRUE(c) => c and not c[1]` (`GF:384`, used at `OEC:2736`): the zone is drawn on the bar the condition turns true, not on every bar
 * it holds. Exported so the rule can be tested on its own, with a condition that can hold twice in a row, instead of through a chart
 * pattern that cannot.
 *
 * The bar at index 3 has no previous window to compare with: there the Pine evaluates `c[1]` over a window it cannot build, `not na` is `na`,
 * and it draws nothing — so the guard answers `false`. The hand-written cases carry a neutral bar in front for that reason: the pattern has to
 * land on bar 4 or later. What this guard is *not* is a change of the rule: the rule is the Pine's and is tested on its own.
 */
export function onlyEdges(holds: (c: ZoneOhlc, a: ZoneOhlc, b: ZoneOhlc, d: ZoneOhlc) => boolean, bars: readonly Bar[], at: number): boolean {
  if (at < 3) return false;
  if (!holds(ohlc(bars[at]!), ohlc(bars[at - 1]!), ohlc(bars[at - 2]!), ohlc(bars[at - 3]!))) return false;
  if (at < 4) return false;
  return !holds(ohlc(bars[at - 1]!), ohlc(bars[at - 2]!), ohlc(bars[at - 3]!), ohlc(bars[at - 4]!));
}

/** The Pine's cap in 'Present' mode: the newest `last` zones, the oldest dropped first (`GF:925-928`). */
export function capZones(zones: readonly ReverseZone[], last: number): ReverseZone[] {
  const size = Math.max(1, Math.min(20, Math.round(last)));
  return zones.length <= size ? [...zones] : zones.slice(zones.length - size);
}

/**
 * The Pine trims each array on its own: `_bullbox_RZ` through one cleaner and `_bearbox_RZ` through the other (`OEC:646-647`), and each one
 * does its own `while array.size(_box_array) > _last` (`GF:926-929`, `:960-963`). Up to `last` bullish and `last` bearish, ten in all.
 */
export function capBySide(zones: readonly ReverseZone[], last: number): ReverseZone[] {
  const kept = [...capZones(zones.filter(item => item.side === 'bull'), last), ...capZones(zones.filter(item => item.side === 'bear'), last)];
  return kept.sort((a, b) => a.start - b.start || (a.side < b.side ? -1 : a.side > b.side ? 1 : 0));
}

export interface ReverseZone {
  readonly side: ZoneSide;
  /** The chart bar the condition fired on (its start). */
  readonly start: number;
  readonly end: number;
  readonly top: number;
  readonly bottom: number;
  /** The cycle session the Pine's window puts it in: A/M carry the bullish side, D/X the bearish one (`:3361`, `:3432`). */
  readonly session: CycleSession | null;
}

/**
 * The zones of the stretch, oldest first, one a chart bar whose condition holds. A bullish zone only exists inside an A/M session
 * (`3361`) and a bearish one inside a D or X session (`3432`): the window decides which condition is even looked at, so a bearish
 * pattern inside A/M is not a zone, as in the Pine.
 * A forming bar is never read: the last bar counts only once its period has ended.
 */
export function reverseZones(bars: readonly Bar[], now: number, zone: CycleZone): ReverseZone[] {
  if (bars.length < 4) return [];
  const barMs = bars[1]![0] - bars[0]![0];
  if (!(barMs > 0)) return [];
  const sessions = cycleSessions(bars, bars[0]![0], bars[bars.length - 1]![0] + barMs, now, zone);
  const zones: ReverseZone[] = [];
  for (let index = 3; index < bars.length; index += 1) {
    const current = bars[index]!;
    if (current[0] + barMs > now) break; // the forming bar carries no zone
    const cur = ohlc(current), p1 = ohlc(bars[index - 1]!), p2 = ohlc(bars[index - 2]!), p3 = ohlc(bars[index - 3]!);
    const start = bars[index - 1]![0], end = current[0] + barMs;
    const session = sessionAt(sessions, current[0]);
    if (!session) continue;
    // The Pine draws on the bar the condition turns true, not on every bar it holds: `Bool_TRUE(c) => c and not c[1]` (`GF:384`,
    // used at `OEC:2736`). It is inert with these two conditions, and that is a fact, not a guess: for the condition to hold twice in a
    // row a clause of one bar would have to contradict a clause of the next. Bullish asks `low[1] >= low[2]` at `i` (L(i-1) >= L(i-2))
    // and, at `i+1`, `low[2] < low[3]` (L(i-1) < L(i-2)); bearish is the mirror with `high[1] <= high[2]` against `high[2] > high[3]`.
    // It is ported anyway: it is the Pine's rule, and it holds if a condition ever loosens.
    // The Pine's levels, in its own order: bullish low[1] over low[2], bearish high[2] over high[1] (`:3357-3445`).
    if (sideOfVariant(session.variant) === 'bull') {
      if (onlyEdges(rzBullishChart, bars, index)) zones.push({ side: 'bull', start, end, top: p1.l, bottom: p2.l, session });
      continue;
    }
    if (onlyEdges(rzBearishChart, bars, index)) zones.push({ side: 'bear', start, end, top: p2.h, bottom: p1.h, session });
  }
  return zones;
}

export const REVERSE_ZONE: StudyDef = {
  api: STUDY_API,
  id: 'reverse-zone',
  name: 'Reverse zone',
  inputs: INPUTS,
  data: [{ key: 'chart', kind: 'candles', label: 'Chart candles' }],
  compute(ctx): StudyOutput | null {
    const series = ctx.data.candles('chart');
    if (!series || series.bars.length < 4) return null;
    const params = readInputs(INPUTS, ctx.params);
    // The windows are the Pine's zone (D-14, D-30): the page's zone never moves them, only writes their hours.
    const zone: CycleZone = CYCLE_90_ZONE;
    const bull = flag(params, 'bull'), bear = flag(params, 'bear');
    const all = reverseZones(series.bars, ctx.now, zone).filter(item => item.side === 'bull' ? bull : bear);
    // The Pine's two cleaners, mirrors of each other: the bullish box dies on a close under its bottom (`GF:917-921`) and the bearish
    // one on a close over its top (`GF:936-966`, `Delete_Present_Box_Bearish_Mitigated`, `precio = box.get_top(bx)`).
    const killed = (item: ReverseZone): boolean => item.side === 'bull'
      ? series.bars.some(bar => bar[0] >= item.end && bar[4] < item.bottom)
      : series.bars.some(bar => bar[0] >= item.end && bar[4] > item.top);
    const survived = flag(params, 'mitigated') ? all.filter(item => !killed(item)) : all;
    // The Pine's `rz_mode` (`OEC:416`): 'Present' keeps the last `rz_last` boxes, 'Historic' keeps them all; mitigation first, then the cap.
    const zones = text(params, 'mode', 'Present') === 'Historic' ? survived : capBySide(survived, number(params, 'last', 5));
    if (!zones.length) return null;
    const plots: Plot[] = [], tags = [];
    const barMs = series.bars.length > 1 ? series.bars[1]![0] - series.bars[0]![0] : 0;
    // `limit_right(bars) => timenow + (time - time[1]) * bars` (`GF:281-282`): anchored at now, not at the last bar. A late last bar would
    // drag the box exactly as much as the delay.
    const now = ctx.replayAt ?? ctx.now;
    const style = text(params, 'style', 'Future');
    const future = style === 'Future', right = style === 'Right';
    const anchorAt = now + Math.max(0, Math.round(number(params, 'anchor', 30))) * barMs;
    const extendAt = now + Math.max(1, Math.round(number(params, 'extend', 160))) * barMs;
    for (const item of zones) {
      const color = item.side === 'bull' ? ctx.palette.bid : ctx.palette.ask;
      const name = `${item.side === 'bull' ? '+' : '-'}RZ${item.session ? ' ' + labelOf(item.session.id) : ''}`;
      // 'Future' stretches the zone eight bars (`OEC:3501-3505`); 'Right' does not draw the zone at all: it draws a box anchored at
      // `timenow`, 30 bars out and 160 wide (`0EC:3362`, `:421-422`), at the zone's prices.
      const t0 = right && barMs > 0 ? anchorAt : item.start;
      const t1 = future && barMs > 0 ? item.end + 8 * barMs : right && barMs > 0 ? extendAt : item.end;
      plots.push({ kind: 'box', t0, t1, p0: item.bottom, p1: item.top, color, alpha: 0.5 });
      // The session and the side travel in the tag's key: that is the per-session state the caller can group, not only a drawing.
      tags.push({ key: `rz:${item.side}:${item.session?.id ?? 'none'}`, price: item.top, text: name, rank: 3, color });
    }
    return { plots, tags };
  },
};
