import { STUDY_API, type Plot, type StudyDef, type StudyOutput } from '../engine/studies/contract.ts';
import { readInputs, type InputSpec, type InputValues } from '../engine/inputs/schema.ts';
import type { Bar } from '../engine/series/source.ts';
import { CYCLE_90_ZONE, CYCLE_SESSIONS, cycleSessions, type CycleSession, type CycleVariant, type CycleZone } from './cycle-90.ts';

/**
 * `singularity`: the OEC SINGULARITY piece, chart version (D-18) and per session of the 90-minute cycle (D-19). It is the sister of
 * `reverse-zone` (`src/indicators/reverse-zone.ts`): same shape, another condition.
 *
 * The Pine (`OECLiquidityindicators/OddEyeCircle`): the chart conditions are `isSingularity_Bullish_Condition` (2724) and
 * `isSingularity_Bearish_Condition` (2730), four candles of the chart's own series. The drawing (3564-3704) makes the box on the trigger
 * bar: bullish from `low[1]` (top) to `low[3]` (bottom), bearish from `high[3]` (top) to `high[1]` (bottom) — the levels are copied as they
 * are, including the Pine's order (the conditions do not order high[3] above high[1], so a bearish box may come inverted; the levels still
 * travel exactly as the Pine passes them). The bullish trigger only exists inside the A or M complements (`:3571`); the bearish one inside
 * D or X (`:3630`, and the box at `:3632`).
 *
 * Sessions are not recalculated: `cycleSessions` from `cycle-90` (T-1014) gives the windows of every variant (T-1025). The bullish zone
 * lives in an A or M session and the bearish one in a D or X session (`:3630`), so **both sides are emitted**: the note this piece carried
 * until T-1031 — that D/X were not carried and the bearish zone had to stay off — was false once T-1025 landed, and it kept the bearish
 * half of the product silent.
 *
 * No `SINGULARITY HTF` and no demon boxes (D-18). `compute` is pure and imports no hub, store or fetch; the painter draws the plots.
 *
 * One overlap worth saying: NY AM's D and X windows are the same in the Pine (`cycle_zeusy_nyam_D_time` = `cycle_zeusy_nyam_X_time`,
 * `OddEyeCircle:2669-2670`), so `sessionAt` finds the D one first and NY AM is never reported as X. Nothing is lost: the Pine accepts
 * that window for the zone under either complement (`complement_D or complement_X`, `:3432` / `:3630`), and the *range* there is the D
 * one anyway, because `_Draw_Range` gates both NY AM calls with `cycle_nyam_D` alone (`:3081-3082`) — which is why the Pine's own X
 * label for that group is empty.
 */
export interface ZoneOhlc { readonly o: number; readonly h: number; readonly l: number; readonly c: number }
export type ZoneSide = 'bull' | 'bear';

/** `isSingularity_Bullish_Condition` (`OddEyeCircle:2724`), on the chart's own last four candles. */
export function singularityBullishChart(cur: ZoneOhlc, p1: ZoneOhlc, p2: ZoneOhlc, p3: ZoneOhlc): boolean {
  return cur.c > cur.o && cur.c >= p1.c && cur.c > p2.c && cur.c > p3.c
    && p1.c > p1.o && p1.c > p2.c && p1.c > p3.c && p2.c > p2.o && p2.c > p3.o && p2.l >= p3.l && p2.c > p3.c && p3.c < p3.o;
}

/** `isSingularity_Bearish_Condition` (`OddEyeCircle:2730`). */
export function singularityBearishChart(cur: ZoneOhlc, p1: ZoneOhlc, p2: ZoneOhlc, p3: ZoneOhlc): boolean {
  return cur.c < cur.o && cur.c <= p1.c && cur.c < p2.c && cur.c < p3.c
    && p1.c < p1.o && p1.c < p2.c && p1.c < p3.c && p2.c < p2.o && p2.c < p3.o && p2.h <= p3.h && p2.c < p3.c && p3.c > p3.o;
}

const INPUTS: readonly InputSpec[] = [
  { id: 'bull', kind: 'bool', name: 'Bullish zones', default: true, group: 'Singularity' },
  { id: 'bear', kind: 'bool', name: 'Bearish zones', default: true, group: 'Singularity' },
  // The Pine's own colours (`OEC:480`, `:482`), not the palette's: the box is drawn with `singularity_*_css` and its fill is the same
  // colour at 50 of transparency (`OEC:3571`, `:3632`).
  { id: 'bullColor', kind: 'color', name: 'Bullish', default: '#73c3e1', group: 'Singularity' },
  { id: 'bearColor', kind: 'color', name: 'Bearish', default: '#ffc0b2', group: 'Singularity' },
  // The Pine's own style and its two distances (`OEC:476-478`): 'Future' by default, and the anchored box only in 'Right'.
  { id: 'style', kind: 'string', name: 'Style', default: 'Future', options: ['Right', 'Future'], group: 'Singularity' },
  { id: 'anchor', kind: 'int', name: 'Anchor', default: 30, min: 0, max: 300, group: 'Singularity' },
  { id: 'extend', kind: 'int', name: 'Extend', default: 160, min: 1, max: 1_000, group: 'Singularity' },
];

const ohlc = (bar: Bar): ZoneOhlc => ({ o: bar[1], h: bar[2], l: bar[3], c: bar[4] });
const number = (params: InputValues, id: string, fallback: number): number => typeof params[id] === 'number' && Number.isFinite(params[id]) ? params[id] : fallback;
const flag = (params: InputValues, id: string): boolean => params[id] === true;
const text = (params: InputValues, id: string, fallback: string): string => typeof params[id] === 'string' ? params[id] as string : fallback;

/** The session a bar falls in, whichever variant: the variant decides which side it may carry (`:3571`, `:3630`). */
function sessionAt(sessions: readonly CycleSession[], t: number): CycleSession | null {
  for (const session of sessions) if (t >= session.from && t < session.to) return session;
  return null;
}

/** The side a session's window belongs to: A and M are the Pine's bullish windows, D and X its bearish ones (`:3571`, `:3630`). */
export function sideOfVariant(variant: CycleVariant): ZoneSide { return variant === 'A' || variant === 'M' ? 'bull' : 'bear'; }

export interface SingularityZone {
  readonly side: ZoneSide;
  /** The chart bar the condition fired on (its start). */
  readonly start: number;
  readonly end: number;
  readonly top: number;
  readonly bottom: number;
  /** The cycle session the Pine's window puts it in: A/M carry the bullish side, D/X the bearish one (`:3571`, `:3630`). */
  readonly session: CycleSession | null;
}

/**
 * The zones of the stretch, oldest first, one a chart bar whose condition holds. A bullish zone only exists inside an A/M session
 * (`:3571`) and a bearish one inside a D or X session (`:3630`): the window decides which condition is looked at. A forming bar is
 * never read: the last bar counts only once its period has ended.
 */
export function singularityZones(bars: readonly Bar[], now: number, zone: CycleZone): SingularityZone[] {
  if (bars.length < 4) return [];
  const barMs = bars[1]![0] - bars[0]![0];
  if (!(barMs > 0)) return [];
  const sessions = cycleSessions(bars, bars[0]![0], bars[bars.length - 1]![0] + barMs, now, zone);
  const zones: SingularityZone[] = [];
  for (let index = 3; index < bars.length; index += 1) {
    const current = bars[index]!;
    if (current[0] + barMs > now) break; // the forming bar carries no zone
    const cur = ohlc(current), p1 = ohlc(bars[index - 1]!), p2 = ohlc(bars[index - 2]!), p3 = ohlc(bars[index - 3]!);
    const start = bars[index - 1]![0], end = current[0] + barMs;
    const session = sessionAt(sessions, current[0]);
    if (!session) continue;
    // Pine levels: bullish top low[1] over low[3] (`:3571`), bearish high[3] over high[1] (`:3632`), copied as they are.
    if (sideOfVariant(session.variant) === 'bull') {
      if (singularityBullishChart(cur, p1, p2, p3)) zones.push({ side: 'bull', start, end, top: p1.l, bottom: p3.l, session });
      continue;
    }
    if (singularityBearishChart(cur, p1, p2, p3)) zones.push({ side: 'bear', start, end, top: p3.h, bottom: p1.h, session });
  }
  return zones;
}

export const SINGULARITY: StudyDef = {
  api: STUDY_API,
  id: 'singularity',
  name: 'Singularity',
  inputs: INPUTS,
  data: [{ key: 'chart', kind: 'candles', label: 'Chart candles' }],
  compute(ctx): StudyOutput | null {
    const series = ctx.data.candles('chart');
    if (!series || series.bars.length < 4) return null;
    const params = readInputs(INPUTS, ctx.params);
    // The windows are the Pine's zone (D-14, D-30): the page's zone never moves them, only writes their hours.
    const zone: CycleZone = CYCLE_90_ZONE;
    const bull = flag(params, 'bull'), bear = flag(params, 'bear');
    const zones = singularityZones(series.bars, ctx.now, zone).filter(item => item.side === 'bull' ? bull : bear);
    if (!zones.length) return null;
    const plots: Plot[] = [], tags = [];
    // Same `limit_right` as `reverse-zone` (`GF:281-282`): in 'Right' the box is anchored at the port's own now, `timenow + bars * barMs`.
    // The Pine's bearish 'Right' box reads `rz_distancer` instead of `singularity_distancer` (`OEC:3632`); that cross-reference cannot be
    // reproduced with two separate pieces, so it is declared in the card and this piece uses its own distance.
    const barMs = series.bars.length > 1 ? series.bars[1]![0] - series.bars[0]![0] : 0;
    const now = ctx.replayAt ?? ctx.now;
    const right = text(params, 'style', 'Future') === 'Right';
    const anchorAt = now + Math.max(0, Math.round(number(params, 'anchor', 30) * barMs));
    const extendAt = now + Math.max(1, Math.round(number(params, 'extend', 160) * barMs));
    for (const item of zones) {
      const color = item.side === 'bull' ? text(params, 'bullColor', '#73c3e1') : text(params, 'bearColor', '#ffc0b2');
      // The Pine's own words, no session name (`OEC:3571`, `:3632`): `+S` / `-S`, and `+S Critical` / `-S Critical` when the bar is in the
      // complementary window — A for the bullish box and D for the bearish one (`time_critical_complement_D ? '-S Critical' : '-S'`).
      const critical = item.side === 'bull' ? item.session?.variant === 'A' : item.session?.variant === 'D';
      const name = `${item.side === 'bull' ? '+' : '-'}S${critical ? ' Critical' : ''}`;
      const t0 = right && barMs > 0 ? anchorAt : item.start, t1 = right && barMs > 0 ? extendAt : item.end;
      plots.push({ kind: 'box', t0, t1, p0: item.bottom, p1: item.top, color, alpha: 0.5 });
      tags.push({ key: `sg:${item.side}:${item.session?.id ?? 'none'}`, price: item.top, text: name, rank: 3.2, color });
    }
    return { plots, tags };
  },
};
