import type { AppState } from '../store.ts';
import type { Hub } from '../hub.ts';
import { TIMEFRAMES } from '../hub.ts';
import type { Bounds } from '../view.ts';
import { MAX_BACK_MS } from '../keylevels/levels.ts';
import type { HistoryTarget } from '../keylevels/history.ts';
import type { ProfileWindow } from '../traded/sessions.ts';
import { sessionsOf, vwapBarMs } from './vwap.ts';
import { anchorsOf } from './settings.ts';
import { flowIds } from '../cvd/ids.ts';
import { currentCoin, scaledUsd } from '../coin.ts';
import { pageNow, replaying } from '../replay/clock.ts';
import { VWAP } from '../../indicators/vwap.ts';
import { readInputs } from '../../engine/inputs/schema.ts';
import type { StudyCandles, StudyData, StudyOutput, StudyPalette } from '../../engine/studies/contract.ts';

/**
 * What the VWAP study needs from the page, kept out of `heat-pane.ts`: the sessions and anchors of its settings, its histories by bar size,
 * the whale sums, and the cache keyed by everything its output depends on. The study itself (`src/indicators/vwap.ts`) knows none of this:
 * it receives the data by key and returns plots.
 *
 * A thin move of the block that lived in `heat-pane.ts` (`#vwapPlan`, `#ensureVwap`, `#vwapBars`, `#vwapLines`): same queries, same cache
 * keys, same order.
 */
export interface VwapContext { readonly target: HistoryTarget | null; readonly zone: string; readonly barMs: number }
interface Plan { readonly sessions: readonly ProfileWindow[]; readonly sessionBar: number; readonly anchors: readonly { at: number; bar: number }[]; readonly reach: ReadonlyMap<number, number> }

export class VwapStudyData {
  #planned: { key: string; plan: Plan } | null = null;
  #drawn: { key: string; output: StudyOutput | null } | null = null;

  /** What the lines need: the sessions touching the chart (and their bar size), each anchor (and its bar size, by its age), and how far back each bar size must reach. */
  #plan(state: AppState, view: Bounds, context: VwapContext): Plan {
    const s = state.vwap, now = pageNow(), MIN = 60_000, HOUR = 3_600_000, coin = currentCoin().coin;
    const key = `${JSON.stringify(s)}|${context.zone}|${context.barMs}|${coin}|${Math.floor(view.t0 / HOUR)}|${Math.ceil(view.t1 / HOUR)}|${Math.floor(now / MIN)}`;
    if (this.#planned?.key === key) return this.#planned.plan;
    // The whale VWAP follows the same sessions, so they are worked out for either.
    const sessions = s.session || s.whale ? sessionsOf(s.period, context.zone, Math.max(view.t0, now - MAX_BACK_MS), view.t1, now, s.startMinute) : [];
    const sessionBar = vwapBarMs(sessions.length ? now - sessions[0]!.from : 0, context.barMs);
    const anchors = anchorsOf(s, coin, now).map(at => ({ at, bar: vwapBarMs(now - at, context.barMs) }));
    const reach = new Map<number, number>();
    const need = (bar: number, from: number): void => { reach.set(bar, Math.min(reach.get(bar) ?? Infinity, Math.floor(from / bar) * bar)); };
    if (sessions.length && s.session) need(sessionBar, sessions[0]!.from);
    for (const anchor of anchors) need(anchor.bar, anchor.at);
    const plan = { sessions, sessionBar, anchors, reach };
    this.#planned = { key, plan };
    return plan;
  }

  /** Ask for the candles the lines need, one history per bar size, and the whale sums from the first session (within the week recorded). */
  ensure(state: AppState, view: Bounds, context: VwapContext, hub: Hub, invalidate: () => void): void {
    if (!state.vwap.on) return;
    const plan = this.#plan(state, view, context);
    for (const [bar, from] of plan.reach) hub.vwapHistory(bar).ensure(context.target, from, bar, invalidate);
    // The seven days the recorder keeps, from a whole hour: a start moving with the clock would ask again every minute.
    const kept = Math.ceil((Date.now() - 7 * 86_400_000) / 3_600_000) * 3_600_000;
    if (state.vwap.whale && plan.sessions.length) hub.ensureWhale(flowIds(state, hub.flow.ids), Math.max(plan.sessions[0]!.from, kept), scaledUsd(state.vwap.whaleUsd));
  }

  /** One bar size's bars, with the chart's own candles after the history's last when they are of the same market and no coarser. */
  #candles(state: AppState, bar: number, target: HistoryTarget, hub: Hub): StudyCandles | null {
    const history = hub.vwapHistory(bar);
    if (history.id !== target.id || history.barMs !== bar || !history.bars.length) return null;
    const held = history.bars, lastStart = held[held.length - 1]![0], tf = TIMEFRAMES[state.timeframe] ?? 3_600_000;
    if (!(target.own && state.seriesInstrument === state.marketId && tf <= bar)) return { bars: held, heldFrom: history.heldFrom, liveFrom: Infinity };
    const live = state.candles.filter(candle => candle[0] >= lastStart);
    if (!live.length) return { bars: held, heldFrom: history.heldFrom, liveFrom: Infinity };
    const from = live[0]![0];
    // A held bar reaching into the chart's candles would count that stretch twice.
    return { bars: [...held.filter(candle => candle[0] + bar <= from), ...live], heldFrom: history.heldFrom, liveFrom: from };
  }

  /** The study's output for the frame, worked out again only when the plan, a history, the chart's last candle, the whale sums or the palette change. */
  frame(state: AppState, view: Bounds, context: VwapContext, hub: Hub, palette: StudyPalette): StudyOutput | null {
    if (!state.vwap.on || !context.target) return null;
    const plan = this.#plan(state, view, context), target = context.target;
    const tail = state.candles[state.candles.length - 1];
    const versions = [...plan.reach.keys()].map(bar => { const history = hub.vwapHistory(bar); return `${bar}:${history.id}:${history.version}`; }).join(',');
    // With the venues on screen: switched, the sums held are another set's until the new ones come.
    const whaleIds = flowIds(state, hub.flow.ids), whale = hub.whale;
    const whaleKey = whale ? `${whale.key}|${whale.at}|${whale.tail.size}|${[...whale.tail.values()].at(-1)?.[1] ?? 0}|${[...whale.tail.values()].at(-1)?.[3] ?? 0}|${whaleIds.join(',')}` : '';
    const colors = `${palette.dark ? 1 : 0}|${palette.vwap}|${palette.bid}|${palette.ask}`;
    const key = `${this.#planned?.key}|${versions}|${state.candles.length}|${tail ? `${tail[0]}|${tail[2]}|${tail[3]}|${tail[5]}` : ''}|${whaleKey}|${colors}${replaying() ? `|r${Math.floor(pageNow() / 60_000)}` : ''}`;
    if (this.#drawn?.key === key) return this.#drawn.output;
    const whaleReady = state.vwap.whale && whale !== null
      && whale.minUsd === scaledUsd(state.vwap.whaleUsd) && whale.ids.size === whaleIds.length && whaleIds.every(id => whale.ids.has(id));
    const data: StudyData = {
      candles: (requested: string): StudyCandles | null => {
        const at = requested.indexOf(':');
        const bar = Number(requested.slice(at + 1));
        return at > 0 && Number.isFinite(bar) && bar > 0 ? this.#candles(state, bar, target, hub) : null;
      },
      sums: (requested: string) => requested === 'whale' && whaleReady && whale ? { rows: hub.whaleRows(), since: whale.since } : null,
    };
    const params = readInputs(VWAP.inputs, {
      session: state.vwap.session, period: state.vwap.period, bands: state.vwap.bands,
      labels: state.vwap.labels, tags: state.vwap.tags, whale: state.vwap.whale, whaleUsd: state.vwap.whaleUsd,
    });
    const output = VWAP.compute({
      params, data, view, now: pageNow(), zone: context.zone, coin: currentCoin().coin,
      windows: plan.sessions.map(window => ({ from: window.from, to: window.to, key: window.key })),
      anchors: plan.anchors.map(anchor => anchor.at),
      zoneBarMs: context.barMs,
      replayAt: replaying() ? pageNow() : null,
      palette,
    });
    this.#drawn = { key, output };
    return output;
  }
}
