/**
 * The full top bar's decks, in the order a person moved them: Market, Panels, Chart, Alerts and the page's own. The order is kept in
 * `hlm-deck-order-v1`; a deck the saved list does not name (one added since) comes after the others, so none ever goes missing. Pure, so a
 * test can check a junk list; the toolbar reads and writes the storage.
 */
export const DECK_IDS = ['market', 'panels', 'chart', 'alerts', 'tools'] as const;
export type DeckId = (typeof DECK_IDS)[number];
export const DECK_ORDER_KEY = 'hlm-deck-order-v1';

export function orderDecks(saved: unknown): DeckId[] {
  const known = new Set<DeckId>(DECK_IDS), out: DeckId[] = [];
  if (Array.isArray(saved)) for (const id of saved) if (typeof id === 'string' && known.has(id as DeckId) && !out.includes(id as DeckId)) out.push(id as DeckId);
  for (const id of DECK_IDS) if (!out.includes(id)) out.push(id);
  return out;
}

/** The decks' order as this browser last left it (the registry's order when it has none). */
export function readDeckOrder(): DeckId[] {
  try { return orderDecks(JSON.parse(window.localStorage.getItem(DECK_ORDER_KEY) ?? 'null')); } catch { return orderDecks(null); }
}

/** Keep the decks' order for this page and the next; a browser without storage keeps it for this page only (the DOM is the order). */
export function saveDeckOrder(ids: readonly DeckId[]): void {
  try { window.localStorage.setItem(DECK_ORDER_KEY, JSON.stringify(ids)); } catch { /* storage unavailable */ }
}
