import { PERIOD_KINDS, type PeriodKind, type PeriodLines } from './levels.ts';

/**
 * The Key levels' settings: whether they show, which lines of the day, the week and the month (previous high/low and previous close),
 * whether an untouched previous level runs on, and the labels at the lines' right ends and on the price axis. Days and weeks start in the
 * Volume profile's zone (`traded.zone`), so the two never disagree about when a day began.
 */
export interface KeyLevelSettings extends Record<PeriodKind, PeriodLines> {
  on: boolean;
  untouched: boolean;
  /** How opaque the previous levels are drawn, in percent (100: solid). */
  opacity: number;
  /** How many previous periods (of each kind) are drawn, the newest first (1: only the last completed one). */
  count: number;
  labels: boolean;
  tags: boolean;
}

const NONE: PeriodLines = { prev: false, close: false };
/** Off until switched on; then previous day/week/month high, low and close — the levels most people look at. */
export const KEY_LEVEL_DEFAULTS: Readonly<KeyLevelSettings> = {
  on: false,
  day: { prev: true, close: true },
  week: { prev: true, close: true },
  month: { prev: true, close: true },
  untouched: true,
  opacity: 100,
  count: 3,
  labels: true,
  tags: true,
};

const flag = (value: unknown, fallback: boolean): boolean => typeof value === 'boolean' ? value : fallback;

/** Settings from storage, field by field: whatever is missing or not valid falls back to the default. */
export function readKeyLevels(saved: unknown): KeyLevelSettings {
  const s = (saved && typeof saved === 'object' ? saved : {}) as Partial<Record<keyof KeyLevelSettings, unknown>>, d = KEY_LEVEL_DEFAULTS;
  const lines = (period: PeriodKind): PeriodLines => {
    const x = (s[period] && typeof s[period] === 'object' ? s[period] : {}) as Partial<Record<keyof PeriodLines | 'mid' | 'open' | 'sofar', unknown>>, def = d[period];
    // Legacy: older saves used `open` for the period open; treat it as previous close. Drop mid/sofar.
    const close = typeof x.close === 'boolean' ? x.close : typeof x.open === 'boolean' ? x.open : def.close;
    return { prev: flag(x.prev, def.prev), close: flag(close, def.close) };
  };
  const opacity = typeof s.opacity === 'number' && Number.isFinite(s.opacity) ? Math.max(10, Math.min(100, Math.round(s.opacity))) : d.opacity;
  const count = typeof s.count === 'number' && Number.isFinite(s.count) ? Math.max(1, Math.min(12, Math.round(s.count))) : d.count;
  return { on: flag(s.on, d.on), day: lines('day'), week: lines('week'), month: lines('month'), untouched: flag(s.untouched, d.untouched), opacity, count, labels: flag(s.labels, d.labels), tags: flag(s.tags, d.tags) };
}

/** Whether any line is chosen at all. */
export const anyLine = (s: KeyLevelSettings): boolean => PERIOD_KINDS.some(p => s[p].prev || s[p].close);
