import { CANDLE_VENUES, fetchCandles, fetchNativePeriodCandles, type Fetcher } from '../../shared/history.ts';
import { instrumentIdFor, type Coin, type Listing, type MarketVenue } from '../../shared/coins.ts';
import type { CandleRow } from '../store.ts';
import { MAX_BACK_MS, PERIOD_KINDS, PERIOD_MS, periodBarsFromCandles, type PeriodBar, type PeriodBars, type PeriodKind } from './levels.ts';
import { candleEndFromOpen } from '../price-line.ts';

/** History rows are objects; the app's CandleRow is a tuple. */
function asTuple(r: { start: number; open: number; high: number; low: number; close: number; volume?: number }): CandleRow {
  return [r.start, r.open, r.high, r.low, r.close, r.volume ?? 0];
}

/**
 * The candles a series is worked out from, read from the exchange's own history, in two shapes:
 *
 * - The key levels' own daily, weekly and monthly candles as the exchange defines them (1d / 1w / 1M opens: UTC midnight, Monday, the 1st
 *   on the major venues), one stretch of each held and refreshed every few minutes (`ensurePeriods`, `periodBars`).
 * - A stretch of candles of one size (hourly, or finer in a zone off the hour: `barMsFor`), which the VWAP, the volume profile's past
 *   windows and the bar statistics' candle delta read (`ensure`), with their taker buys where the venue reports them (`withBuy`).
 */

const DAY = 86_400_000;
const HOUR = 3_600_000;
const REFRESH_MS = 5 * 60_000;
const RETRY_MS = 60_000;
const MAX_PAGES = 12;
const FALLBACK: readonly MarketVenue[] = ['binance', 'bybit', 'okx', 'hyperliquid', 'bitget', 'binancespot', 'coinbase', 'bybitspot', 'okxspot', 'bitgetspot', 'deribit'];

export interface HistoryTarget { id: string; listing: Listing; own: boolean }

export function historyTarget(chartId: string, coin: Coin): HistoryTarget | null {
  const spot = /^([^:]+):(.+):spot$/.exec(chartId);
  const chart = spot ? `${spot[1]}spot:${spot[2]}` : chartId;
  const venues = [chart.split(':')[0]!, ...FALLBACK];
  for (let i = 0; i < venues.length; i++) {
    const venue = venues[i]!, listing = coin.markets[venue as MarketVenue], id = instrumentIdFor(venue, coin);
    if (!CANDLE_VENUES.includes(venue) || !listing || !id || (i === 0 && id !== chart)) continue;
    // Coinbase/Deribit have no native 1w/1M — still usable for daily; week/month simply stay empty.
    return { id, listing, own: id === chart };
  }
  return null;
}

export function profileTarget(coin: Coin): HistoryTarget | null {
  for (const venue of FALLBACK) {
    const listing = coin.markets[venue], id = instrumentIdFor(venue, coin);
    if (CANDLE_VENUES.includes(venue) && listing && id) return { id, listing, own: false };
  }
  return null;
}

/**
 * The spot market whose candles join the perpetual's in the volume profile: Binance spot beside Binance's perpetual, more of the coin's
 * trading split the same way by its taker buys. Null where the target is another venue's or the coin has no Binance spot market.
 */
export function profileCompanion(coin: Coin, target: HistoryTarget | null): HistoryTarget | null {
  if (!target || !target.id.startsWith('binance:')) return null;
  const listing = coin.markets.binancespot, id = instrumentIdFor('binancespot', coin);
  return CANDLE_VENUES.includes('binancespot') && listing && id ? { id, listing, own: false } : null;
}

/** One stretch of the exchange's native period candles, and where its requests reached. */
interface PeriodState {
  bars: CandleRow[];
  askedFrom: number;
  heldTo: number;
  exhausted: boolean;
  refreshedAt: number;
  pending: boolean;
  retryAt: number;
}

const emptyPeriod = (): PeriodState => ({ bars: [], askedFrom: Infinity, heldTo: -Infinity, exhausted: false, refreshedAt: 0, pending: false, retryAt: 0 });

export class KeyLevelHistory {
  #key = '';
  #id = '';
  /** The key levels' native period candles, one stretch a period. */
  #periods: Record<PeriodKind, PeriodState> = { day: emptyPeriod(), week: emptyPeriod(), month: emptyPeriod() };
  /** The one size of candles `ensure` holds (the fine path: VWAP, profile, candle delta). */
  #barMs = HOUR;
  #bars: CandleRow[] = [];
  /** How far back the history is known to go, or was asked for and is not there: what is not asked again. */
  #askedFrom = Infinity;
  /** The time the last successful request of the newest bars reached. */
  #heldTo = -Infinity;
  /** Set when asking further back brought nothing older: the exchange's history begins there. */
  #exhausted = false;
  #refreshedAt = 0;
  #pending = false;
  #retryAt = 0;
  /** Bumped whenever the bars change, for the pane's cache. */
  version = 0;
  /** Whether the bars carry their taker buys where the venue reports them (the volume profile's, for its split). */
  withBuy = false;
  state: 'idle' | 'loading' | 'ready' | 'unavailable' = 'idle';

  /**
   * `refreshMs`: how often the newest bars are asked again (the VWAP wants them every minute). `maxBackMs`: how far back bars are kept
   * (the key levels' two months; the volume profile's past weeks reach further).
   */
  constructor(private get: Fetcher, private now: () => number = Date.now, private refreshMs: number = REFRESH_MS, private maxBackMs: number = MAX_BACK_MS) {}

  get id(): string { return this.#id; }
  get barMs(): number { return this.#barMs; }
  /** Whether the key levels' native period candles are the ones held (rather than one size of them). */
  get periodMode(): boolean { return this.#periods.day.bars.length > 0 || this.#periods.week.bars.length > 0 || this.#periods.month.bars.length > 0; }
  /** The bars, oldest first: the fine path's, or the daily ones while the period candles are held. */
  get bars(): readonly CandleRow[] { return this.periodMode ? this.#periods.day.bars : this.#bars; }
  /** Where the bars held begin (Infinity while there are none). */
  get heldFrom(): number {
    if (!this.periodMode) return this.#bars[0]?.[0] ?? Infinity;
    const starts = PERIOD_KINDS.map(p => this.#periods[p].bars[0]?.[0]).filter((t): t is number => t !== undefined);
    return starts.length ? Math.min(...starts) : Infinity;
  }
  /** Up to when the bars held are known: the last successful refresh reached. */
  get heldTo(): number {
    if (!this.periodMode) return this.#heldTo;
    const ends = PERIOD_KINDS.map(p => this.#periods[p].heldTo).filter(t => t > 0);
    return ends.length ? Math.max(...ends) : -Infinity;
  }

  /**
   * Whether the bars held reach back to `from`: 'yes'; 'coming' when they do not yet and may (a request is out, or one can still be asked); 'never'
   * when they will not (the exchange's history begins later, nothing could be read at all, or the next try is a minute off).
   */
  reach(from: number): 'yes' | 'coming' | 'never' {
    if (this.#bars.length && this.heldFrom <= from) return 'yes';
    if (this.state === 'unavailable' || this.#exhausted) return 'never';
    if (this.#pending || this.state === 'loading' || this.state === 'idle') return 'coming';
    return this.now() < this.#retryAt ? 'never' : 'coming';
  }

  /**
   * Make sure `barMs` candles of `target` from `from` are held or on their way; `onLoad` runs when an answer changes them. The fine path:
   * the VWAP's bars, the volume profile's past windows and the candle delta's.
   
   */
  ensure(target: HistoryTarget | null, from: number, barMs: number, onLoad: () => void): void {
    const key = target ? `${target.id}|${barMs}` : '';
    if (key !== this.#key) { this.#reset(key, target?.id ?? '', barMs); this.version++; }
    if (!target) return;
    const now = this.now();
    if (this.#pending || now < this.#retryAt) return;
    const want = Math.floor(from / DAY) * DAY;
    let a: number, b: number, forward = false;
    if (!this.#bars.length) { a = want; b = now; forward = true; }
    else if (want < this.#askedFrom && !this.#exhausted) { a = want; b = this.#bars[0]![0]; }
    else if (now - this.#refreshedAt >= this.refreshMs) { a = this.#bars[this.#bars.length - 1]![0] - 2 * barMs; b = now; forward = true; }
    else return;
    const asked = this.#key, before = this.#bars[0]?.[0] ?? Infinity;
    this.#pending = true; if (!this.#bars.length) this.state = 'loading';
    // A page that fails after others came keeps them, the next call asking on back from where they reach: on the first load and the walks
    // further back, never on a refresh of the newest bars, where what came could lie apart from what is held and leave a hole.
    const partial = !forward || !this.#bars.length;
    void fetchCandles(target.id, barMs, a, b, this.get, target.listing, MAX_PAGES, { pageSize: 1500, partial, buy: this.withBuy }).then(rows => {
      if (asked !== this.#key) return;
      if (forward) this.#refreshedAt = this.now();
      if (rows.length) { this.#mergeFine(rows as CandleRow[]); if (forward) this.#heldTo = Math.max(this.#heldTo, b); }
      else if (!this.#bars.length) this.#retryAt = this.now() + RETRY_MS;
      // Reached what was asked: done back to there. Stopped short with older bars than before (the page ceiling, or a short history): the
      // next call asks on from where it got to. Nothing older at all: the exchange's history begins here.
      const progress = this.heldFrom < before;
      if (this.heldFrom <= a + barMs) this.#askedFrom = Math.min(this.#askedFrom, a);
      else if (progress) this.#askedFrom = Math.min(this.#askedFrom, this.heldFrom);
      else if (!forward || this.#bars.length) this.#exhausted = true;
      this.state = this.#bars.length ? 'ready' : 'unavailable';
      onLoad();
    }, () => {
      if (asked !== this.#key) return;
      this.#retryAt = this.now() + RETRY_MS;
      this.state = this.#bars.length ? 'ready' : 'unavailable';
      onLoad();
    }).finally(() => { if (asked === this.#key) this.#pending = false; });
  }

  /**
   * Ensure the market's own day, week and month candles from `from` on are held or loading; `onLoad` runs when any period updates. One
   * stretch a period, each refreshed every `refreshMs`, extended back only when the chart asks for earlier periods.
   */
  ensurePeriods(target: HistoryTarget | null, from: number, onLoad: () => void): void {
    const key = target ? `${target.id}|period` : '';
    if (key !== this.#key) { this.#reset(key, target?.id ?? '', DAY); this.version++; }
    if (!target) return;
    const now = this.now();
    let anyLoading = false, anyPending = false;
    for (const period of PERIOD_KINDS) {
      const st = this.#periods[period], periodMs = PERIOD_MS[period];
      if (st.pending) { anyPending = true; continue; }
      if (now < st.retryAt) continue;
      const want = Math.min(from, now - periodMs * 3);
      let a: number, b: number, forward = false;
      if (!st.bars.length) { a = want; b = now; forward = true; }
      else if (want < st.askedFrom && !st.exhausted) { a = want; b = st.bars[0]![0]; }
      else if (now - st.refreshedAt >= this.refreshMs) { a = st.bars[st.bars.length - 1]![0] - 2 * periodMs; b = now; forward = true; }
      else continue;
      const asked = this.#key, before = st.bars[0]?.[0] ?? Infinity;
      st.pending = true; anyPending = true;
      if (!st.bars.length) anyLoading = true;
      void fetchNativePeriodCandles(target.id, periodMs, a, b, this.get, target.listing, MAX_PAGES).then(rows => {
        if (asked !== this.#key) return;
        if (forward) st.refreshedAt = this.now();
        if (rows.length) {
          this.#mergePeriod(period, rows.map(asTuple));
          if (forward) st.heldTo = Math.max(st.heldTo, b);
          this.version++;
          onLoad();
        } else if (!st.bars.length) {
          st.retryAt = this.now() + RETRY_MS;
        }
        const heldFrom = st.bars[0]?.[0] ?? Infinity;
        const progress = heldFrom < before;
        if (heldFrom <= a + periodMs) st.askedFrom = Math.min(st.askedFrom, a);
        else if (progress) st.askedFrom = Math.min(st.askedFrom, heldFrom);
        else if (!forward || st.bars.length) st.exhausted = true;
        st.pending = false;
        this.#refreshState();
      }, () => {
        if (asked !== this.#key) return;
        st.pending = false;
        st.retryAt = this.now() + RETRY_MS;
        this.#refreshState();
      });
    }
    if (anyLoading) this.state = 'loading';
    else if (!anyPending) this.#refreshState();
  }

  /** Native period bars ready for `keyLines`. */
  periodBars(now: number = this.now()): PeriodBars {
    const out = {} as Record<PeriodKind, PeriodBar[]>;
    for (const p of PERIOD_KINDS) {
      const st = this.#periods[p], list = st.bars;
      if (!list.length) { out[p] = []; continue; }
      const last = list[list.length - 1]!;
      const lastEnd = candleEndFromOpen(last[0], PERIOD_MS[p]);
      out[p] = periodBarsFromCandles(list, Math.max(lastEnd, now), st.heldTo > 0 ? st.heldTo : now);
    }
    return out;
  }

  #mergeFine(rows: readonly CandleRow[]): void {
    const byStart = new Map<number, CandleRow>(this.#bars.map(r => [r[0], r])), oldest = this.now() - this.maxBackMs - DAY;
    for (const r of rows) if (Number.isFinite(r[0]) && r[2] >= r[3]) byStart.set(r[0], r);
    // A page open for weeks would otherwise keep every bar it ever read: none older than the levels can reach is kept.
    this.#bars = [...byStart.values()].filter(r => r[0] >= oldest).sort((x, y) => x[0] - y[0]);
    this.version++;
  }

  #mergePeriod(period: PeriodKind, rows: CandleRow[]): void {
    const st = this.#periods[period];
    if (!rows.length) return;
    const map = new Map<number, CandleRow>();
    for (const r of st.bars) map.set(r[0], r);
    for (const r of rows) map.set(r[0], r);
    const merged = [...map.values()].sort((a, b) => a[0] - b[0]);
    const cut = this.now() - this.maxBackMs - PERIOD_MS.month;
    st.bars = merged.filter(r => r[0] >= cut);
  }

  #reset(key: string, id: string, barMs: number): void {
    this.#key = key; this.#id = id; this.#barMs = barMs; this.#bars = []; this.#askedFrom = Infinity; this.#heldTo = -Infinity; this.#exhausted = false;
    this.#refreshedAt = 0; this.#pending = false; this.#retryAt = 0;
    this.#periods = { day: emptyPeriod(), week: emptyPeriod(), month: emptyPeriod() };
    this.state = id ? 'loading' : 'idle';
  }

  #refreshState(): void {
    const any = PERIOD_KINDS.some(p => this.#periods[p].bars.length > 0);
    const pending = PERIOD_KINDS.some(p => this.#periods[p].pending);
    if (pending && !any) this.state = 'loading';
    else if (any) this.state = 'ready';
    else if (this.#id) this.state = 'unavailable';
    else this.state = 'idle';
  }
}
