/**
 * The engine's timeframes, as Pine names them, and the conversions the app needs to hand its own chart timeframes to a study.
 *
 * The card lists `'1','5','15','60','240','D','W','M'`; `'30'` is added because the chart has a 30-minute timeframe
 * (`store.ts` TIMEFRAME_IDS) and a study that could not run on it would be a trap.
 */
export type Timeframe = '1' | '5' | '15' | '30' | '60' | '240' | 'D' | 'W' | 'M';

export const TF_MS: Readonly<Record<Timeframe, number>> = {
  '1': 60_000,
  '5': 300_000,
  '15': 900_000,
  '30': 1_800_000,
  '60': 3_600_000,
  '240': 14_400_000,
  'D': 86_400_000,
  'W': 604_800_000,
  'M': 2_592_000_000,
};

export const TIMEFRAMES: readonly Timeframe[] = ['1', '5', '15', '30', '60', '240', 'D', 'W', 'M'];

/** The engine's one-minute timeframe. */
export const TF_1 = (): Timeframe => '1';

export function isTimeframe(value: string): value is Timeframe {
  return (TIMEFRAMES as readonly string[]).includes(value);
}

export function timeframeMs(tf: Timeframe): number { return TF_MS[tf]; }

/**
 * The higher timeframe above `tf`, as the card asks (D→W→M): week for a day, month for a week, and nothing above a month. Intraday
 * folow the same ladder (1→5→15→30→60→240→D)? No: those are *other* resolutions of the same clock, not a "higher" one, and Pine's
 * `request.security` on a higher timeframe of an intraday chart is the chart's own D. So an intraday timeframe's HTF is `D`.
 */
export function HTF(tf: Timeframe): Timeframe | null {
  switch (tf) {
    case 'D': return 'W';
    case 'W': return 'M';
    case 'M': return null;
    default: return 'D';
  }
}

/** The app's chart timeframe id (`store.ts` TIMEFRAME_IDS) as the engine's timeframe, or null when it has none. */
export function timeframeFromChart(id: string): Timeframe | null {
  switch (id) {
    case '1m': return '1';
    case '5m': return '5';
    case '15m': return '15';
    case '30m': return '30';
    case '1h': return '60';
    case '4h': return '240';
    case '1d': return 'D';
    case '1w': return 'W';
    case '1M': return 'M';
    default: return null;
  }
}
